window.POEM_DB=window.POEM_DB||{};POEM_DB["song_014"]={"n":"范成大","dyn":"宋","poems":[{"t":"藻侄比课五言诗已有意趣老怀甚喜因吟病中十二首示之可率昆季赓和胜终日饱閒也 其三","f":"五言律诗","c":["日煖衣犹袭，宵长被有棱。","朝晡三楪饭，昏晓一釭灯。","伴坐跧如几，扶行瘦比藤。","生缘堪入画，寂寞憩松僧。"]},{"t":"一篙","f":"七言绝句","c":["一篙新绿浦东西，雪絮漫江雁不飞。","宿雨才晴风又转，片帆那得及时归。"]},{"t":"七十二冢","f":"七言绝句","c":["一棺何用冢如林，谁复如公负此心。","闻说群胡为封土，世间随事有知音。"]},{"t":"七里店口占","f":"五言绝句","c":["分手暮江寒，徘徊立马看。","寻常相见易，倍觉别离难。"]},{"t":"九日忆菊坡","f":"七言绝句","c":["菊坡长恨隔横塘，城郭山林自不双。","放棹松江花已远，涛江之外更鄞江。"]},{"t":"九月十日南山见梅","f":"七言绝句","c":["五斗留连首屡回，来寻南涧濯尘埃。","春风直恐渊明去，借与横斜对菊开。"]},{"t":"九月五日晴暖步后园","f":"七言绝句","c":["海气烘晴入断霞，半空云影界山斜。","轻罗小扇游蜂畔，只比东风有菊花。"]},{"t":"九盘坡布水","f":"七言绝句","c":["莫惜萦回上九盘，洗心双瀑雪花寒。","野翁酌水煎茶献，自古人来到此难。"]},{"t":"入城","f":"七言绝句","c":["十里清风一饷间，片帆真欲解人颜。","林家庄近闻鹅鸭，船到阊门尽未关。"]},{"t":"入崇宁界","f":"七言绝句","c":["桑间三宿尚回头，何况三年濯锦游。","草草郫筒中酒处，不知身已在彭州。"]},{"t":"八月二十二日寓直玉堂雨后顿凉","f":"七言绝句","c":["雨意蒸云暗夕阳，浓薰满院落花香。","题诗弄笔北窗下，将此工夫报答凉。"]},{"t":"十一月大雾中自胥口渡太湖","f":"七言绝句","c":["白雾漫空白浪深，舟如竹叶信浮沉。","科头晏起吾何敢，自有山川印此心。"]},{"t":"十月二十六日三偈 其二","f":"五言绝句","c":["有个安心法，无时不可行。","只将今日事，随分了今生。"]},{"t":"十月二十六日三偈 其一","f":"五言绝句","c":["声闻与色尘，普以妙香薰。","昔汝来迷我，今吾却戏君。"]},{"t":"十月二十六日三偈 其三","f":"五言绝句","c":["窗外尘尘事，窗中梦梦身。","既知身是梦，一任事如尘。"]},{"t":"三月二日北门马上","f":"七言绝句","c":["新街如拭过鸣驺，芍药酴醾竞满头。","十里珠帘都捲上，少城风物似扬州。"]},{"t":"三月四日骤煖","f":"七言绝句","c":["日脚融晴晚气暄，睡馀初觉薄罗便。","如何柳絮沾泥处，煖似槐阴转午天。"]},{"t":"三江亭观雪","f":"七言绝句","c":["阴山阳朔雪中回，行到天西玉作堆。","乘兴却游东海上，白银宫阙认蓬莱。"]},{"t":"自晨至午起居饮食皆以墙外人物之声为节戏书四绝 其四","f":"七言绝句","c":["起傍东窗手把书，华颠种种不禁梳。","朝餐欲到须巾裹，已有重来晚市鱼。"]},{"t":"自晨至午起居饮食皆以墙外人物之声为节戏书四绝 其一","f":"七言绝句","c":["巷南敲板报残更，街北弹丝行诵经。","已被两人惊梦断，谁家风鸽斗鸣铃。"]},{"t":"自晨至午起居饮食皆以墙外人物之声为节戏书四绝 其三","f":"七言绝句","c":["北砦教回挝鼓远，东禅饭熟打钟频。","小童三唤先生起，日满东窗煖似春。"]},{"t":"自晨至午起居饮食皆以墙外人物之声为节戏书四绝 其二","f":"七言绝句","c":["菜市喧时窗透明，饼师叫后药煎成。","閒居日出都无事，惟有开门扫地声。"]},{"t":"上沙","f":"七言绝句","c":["水边犬吠隔疏林，篱落萧森日半阴。","繁杏锁红春意浅，晚梅飘粉暮寒深。"]},{"t":"上沙舍舟","f":"七言绝句","c":["村北村南打稻声，竹舆随处款柴荆。","斜阳倒景天如醉，明日山行更好晴。"]},{"t":"上沙遇雨快凉","f":"七言绝句","c":["刮地风来健葛衣，一凉便觉暑光低。","云头龙挂如垂箸，雨在中峰白塔西。"]},{"t":"书樊子南游西山二记后 其二 大面","f":"七言绝句","c":["春晚娑罗百叶开，仙翁精舍长蓬莱。","朝元未罢门深闭，不管人间有客来。"]},{"t":"与现寿二长老游寿泉因话去年林屋之游题赠 其二","f":"七言绝句","c":["松风放浪入云关，二衲相从一士閒。","人与瘦筇俱老健，去年今日在包山。"]},{"t":"与现寿二长老游寿泉因话去年林屋之游题赠 其一","f":"七言绝句","c":["何年锡杖斸清甘，天遣深源寿此庵。","金靥万枝浮倒影，为君题作菊花潭。"]},{"t":"与郑少融赵养民二使者访古訾家洲归憩松关二君欲助力兴废戏书此付长老善良以当疏头","f":"七言绝句","c":["飘飘竹雨润轻裘，袅袅松风系小舟。","安得从容兴废手，越人重上訾家洲。"]},{"t":"久雨地湿","f":"七言绝句","c":["汗础经旬未肯乾，破窗随处有蜗涎。","只今不耐春阴得，想见黄梅细雨天。"]},{"t":"于潜","f":"七言绝句","c":["邑居官寺两凄清，晚市都无菜可羹。","何处直能令鬼怕，祗今犹自有人行。"]},{"t":"口号","f":"七言绝句","c":["我是苏州监本呆，与爷上寿献棺材。","宗室元来是皇族，雨下水从屋上来。"]},{"t":"大风","f":"七言绝句","c":["春晴虽好恨多风，到眼花枝转眼空。","晴不与花为道地，争如云淡雨濛濛。"]},{"t":"大风","f":"七言绝句","c":["飓母从来海若家，青天白地忽飞沙。","烦将残暑驱除尽，只莫颠狂损稻花。"]},{"t":"大宁河","f":"七言绝句","c":["梨枣从来数内丘，大宁河畔果园稠。","荆箱扰扰拦街卖，红皱黄团满店头。"]},{"t":"大扶?","f":"七言绝句","c":["身如鱼跃上长竿，路似镜中相对看。","珍重山丁扶我过，人间踽踽独行难。"]},{"t":"大波林","f":"七言绝句","c":["湖路荒寒又险艰，大千空水我居间。","篙师晚始分南北，指点青青汉口山。"]},{"t":"大通界首驿","f":"七言绝句","c":["愚悃无华敢自欺，寸诚珍重吏民知。","东风重倚庭前树，送别人情似到时。"]},{"t":"大雪送炭与芥隐","f":"七言绝句","c":["无因同拨地炉灰，想见柴荆晚未开。","不是雪中须送炭，聊装风景要诗来。"]},{"t":"大黄花","f":"七言绝句","c":["大芋高荷半亩阴，玉英危缀碧瑶簪。","谁知一叶莲花面，中有将军剑戟心。"]},{"t":"小春海棠来禽","f":"七言绝句","c":["东君好事惜年华，偏爱荒园野老家。","一任西风管摇落，小春自管数枝花。"]},{"t":"小涧","f":"五言绝句","c":["石碍珠旒溅，滩平雾縠铺。","小童能好事，系马斸菖蒲。"]},{"t":"山径","f":"七言绝句","c":["云根新径络山腰，暗绿交阴宿露飘。","行到竹深啼鸟闹，鹁鸠老怨画眉娇。"]},{"t":"山顶","f":"七言绝句","c":["翠屏无路强攀缘，我与枯藤各半仙。","不敢高声天阙近，人间漠漠但寒烟。"]},{"t":"马迹石","f":"七言绝句","c":["跨马凌空亦快哉，龙腰鹤背谩徘徊。","游人欲识仙踪处，但觅苍崖白塔来。"]},{"t":"中秋无月三首 其一","f":"七言绝句","c":["儿女无悰坐客稀，今年孤负隔年期。","谁从天上牢遮月，不管人间大欠诗。"]},{"t":"中秋无月三首 其二","f":"七言绝句","c":["扑地痴云欲万重，家家帘幕护房栊。","世间第一无情物，谁似中秋雨与风。"]},{"t":"中秋无月三首 其三","f":"七言绝句","c":["一生露下风前客，两岁愁边病里身。","姑置阴晴圆缺事，药寮灯火正相亲。"]},{"t":"中秋后两日自上沙回闻千岩观下岩桂盛开复舣石湖留赏一日赋两绝 其一","f":"七言绝句","c":["金粟枝头一夜开，故应全得小诗催。","篮舆缓缓随儿女，引入天香洞里来。"]},{"t":"中秋后两日自上沙回闻千岩观下岩桂盛开复舣石湖留赏一日赋两绝 其二","f":"楚辞体","c":["千岩观下碧瑶林，岁晚青青共此心。","隐士归兮花未老，每年来把一杯深。"]},{"t":"中秋清晖阁静坐因思前二年石湖四明赏月","f":"七言绝句","c":["前年银界接天迷，去岁金盘涌海低。","漂泊相逢重一笑，秦淮东畔女墙西。"]},{"t":"书怀二绝再送文季高兼呈新帅阎才元侍郎 其一","f":"七言绝句","c":["剑关云栈守非难，函谷泥封久未刊。","今日汉中谁国士，莫教春草上斋坛。"]},{"t":"书怀二绝再送文季高兼呈新帅阎才元侍郎 其二","f":"七言绝句","c":["西出阳关有旧知，薰风渌水泛莲时。","烦君传语诗书帅，更寄台城别后词。"]},{"t":"书樊子南游西山二记后 其一 牡丹瓶","f":"七言绝句","c":["仙山草木锁卿云，不到花平不离尘。","十丈牡丹如锦盖，人间姚魏却争春。"]},{"t":"云间湖光亭","f":"七言绝句","c":["微风不动敛涛湍，组练晶晶色界寒。","斜照发挥犹未尽，月明残夜更来看。"]},{"t":"云露堂前杏花","f":"七言绝句","c":["蜡红枝上粉红云，日丽烟浓看不真。","浩荡光风无畔岸，如何锁得杏园春。"]},{"t":"五月闻莺二首 其二","f":"七言绝句","c":["一声初上最高枝，忙杀呕哑百舌儿。","老尽西园千树绿，却怜槐眼正迷离。"]},{"t":"五月闻莺二首 其一","f":"七言绝句","c":["桑阴净尽麦头齐，江上闻莺每岁迟。","不及晓风鹎鵊子，迎春啼到送春时。"]},{"t":"从巨济乞蜡梅","f":"七言绝句","c":["寂寥人在晓鸡窗，苦忆花前续断肠。","全树折来应不惜，君家真色自生香。"]},{"t":"从宗伟乞冬笋山药","f":"七言绝句","c":["竹坞拨沙犀顶锐，药畦粘土玉肌丰。","裹芽束缊能分似，政及莱芜甑釜空。"]},{"t":"以狨坐覆蒲龛中","f":"七言绝句","c":["蠹蚀尘昏度几年，蒙茸依旧软如绵。","且来助煖乌皮几，莫忆冲寒紫绣鞯。"]},{"t":"元夕四首 其四","f":"七言绝句","c":["落梅秾李趁时新，枯木崖边一任春。","尚爱乡音醒病耳，隔墙时有卖饧人。"]},{"t":"元夕四首 其三","f":"七言绝句","c":["药炉汤鼎煮孤灯，禅版蒲团老病僧。","儿女强修元夕供，玉蛾先避雪鬅鬙。"]},{"t":"元夕四首 其一","f":"七言绝句","c":["粉痕红点万花攒，玉气珠光宝月团。","帘箔通明香似雾，东君无处著春寒。"]},{"t":"元夕四首 其二","f":"七言绝句","c":["不夜城中陆地莲，小梅初破月初圆。","新年第一佳时节，谁肯如翁闭户眠。"]},{"t":"元夕大风雨二绝 其一","f":"七言绝句","c":["东风无赖妒华年，一夜凄寒到酒边。","放尽珠帘遮画炬，莫教檐雨湿青烟。"]},{"t":"元夕大风雨二绝 其二","f":"七言绝句","c":["河倾海立夜翻盆，不独妨灯更损春。","冻涩笙簧犹可耐，滴皴梅颊势须嗔。"]},{"t":"元夕泊舟霅川","f":"七言绝句","c":["莲炬光中月自圆，人情草草竞华年。","最怜一夜旗亭鼓，能共钟声到客船。"]},{"t":"元日马上二绝 其一","f":"七言绝句","c":["泥絮心情雪样髯，诗囊羞涩酒杯嫌。","年来万事都消减，惟有床头历日添。"]},{"t":"元日马上二绝 其二","f":"七言绝句","c":["筋骸全比去年非，骑吹声中忆钓矶。","待得江风欺老病，何如闻健一蓑归。"]},{"t":"内丘梨园","f":"七言绝句","c":["汗后鹅梨爽似冰，花身耐久老犹荣。","园翁指似还三笑，曾共翁身见太平。"]},{"t":"刈麦","f":"七言绝句","c":["麦头熟颗已如珠，小阨惟忧积雨馀。","丐我一晴天易耳，十分终惠莫乘除。"]},{"t":"双庙","f":"七言绝句","c":["平地孤城寇若林，两公犹解障妖祲。","大梁襟带洪河险，谁遣神州陆地沉。"]},{"t":"双燕","f":"五言绝句","c":["底处飞双燕，衔泥上药栏。","莫教惊得去，留取隔帘看。"]},{"t":"壬辰七月十六日侵晨真率会石湖路中书事","f":"七言绝句","c":["白葛乌纱称老农，溪南溪北水车风。","稻头的皪粘朝露，步入明珠翠网中。"]},{"t":"天平寺","f":"七言绝句","c":["旧游彷佛记三年，轰饮题诗夜满山。","山上白云应解笑，又将尘土涴朱颜。"]},{"t":"天成桥","f":"七言绝句","c":["一冈邑屋旧河滩，却望河身百里间。","涌土涨沙漫白道，天成桥石在高山。"]},{"t":"太行","f":"七言绝句","c":["西北浮云捲莫秋，太行南麓照封丘。","横峰侧岭知多少，行到燕山翠未休。"]},{"t":"文王庙","f":"七言绝句","c":["堂堂十乱欲兴周，肯使君王死作囚。","巧笑入宫天亦笑，可怜元不费深谋。"]},{"t":"方竹杖","f":"七言绝句","c":["竹君个个面团团，此士刚方独凛然。","外貌中心俱壁立，任从痴子削教圆。"]},{"t":"无题","f":"七言绝句","c":["闻道明朝送旧官，无情更鼓夜将阑。","此生见面知何日，忍泪须臾子细看。"]},{"t":"月夜泛舟新塘","f":"七言绝句","c":["溪上清风柳万重，绿烟无路月朦胧。","船头忽逐回塘转，一水迢迢却向东。"]},{"t":"水月庵谒现老不值","f":"五言绝句","c":["有客叩岩扃，无人管送迎。","片云閒出岫，水月自空明。"]},{"t":"王千岭","f":"七言绝句","c":["山灵设险合峥嵘，行客何须向此行。","羸马不前人雨汗，此身安得讳劳生。"]},{"t":"王正之提刑见和末利小诗甚工今日末利渐过木犀正开复用韵奉呈二绝 其二","f":"七言绝句","c":["末利吟馀又木犀，碧瑶叶底露金支。","从今日日须搜句，莫遣砚池生网丝。"]},{"t":"王正之提刑见和末利小诗甚工今日末利渐过木犀正开复用韵奉呈二绝 其一","f":"七言绝句","c":["南花宜夏不禁凉，犹绕珍丛觅旧香。","留得典刑传菊圃，别篘新酒待重阳。"]},{"t":"风止","f":"七言绝句","c":["收尽狂飙捲尽云，一竿晴日晓光新。","柳魂花魄都无恙，依旧商量作好春。"]},{"t":"碧虚席上得赵养民运使寄诗约今晚可归次韵迓之","f":"七言绝句","c":["偶携尊酒上孱颜，忽忆行人瘴雾间。","便好来分苍石坐，已教不锁翠云关。"]},{"t":"丙午人日立春屈指癸卯孟夏晦得疾恰千日矣戏书","f":"七言绝句","c":["百年能有几春光，只合都将付醉乡。","衰病豁除千日外，尚馀三万五千场。"]},{"t":"丛台","f":"七言绝句","c":["凭高阅士剑如林，故国风流变古今。","袨服云仍犹左衽，丛台休恨绿芜深。"]},{"t":"东门外观刈熟民间租米船相衔入门喜作二绝 其二","f":"七言绝句","c":["潮到灵桥绿绕船，海边力穑屡丰年。","淡青山色深黄稻，恰似胥门九月天。"]},{"t":"东门外观刈熟民间租米船相衔入门喜作二绝 其一","f":"七言绝句","c":["菊莎杞棘爨无烟，日日文书横索钱。","今日甬东官况好，东津门外看租船。"]},{"t":"东坡祠堂","f":"七言绝句","c":["化原坊里尚黉堂，闻道苏仙有奉尝。","想见当年行乐处，牙旗铁马照金章。"]},{"t":"代儿童作立春贴门诗三首 其三","f":"五言绝句","c":["盛族推山长，修龄号栎翁。","屏花春不老，日日是东风。"]},{"t":"代儿童作立春贴门诗三首 其二","f":"五言绝句","c":["绿野添花径，青春引杖藜。","家人行乐处，双劝玉东西。"]},{"t":"代儿童作立春贴门诗三首 其一","f":"五言绝句","c":["剪綵宜春胜，泥金祝寿幡。","雪梅同雪鬓，相对两淩寒。"]},{"t":"代儿童作端午贴门诗三首 其三","f":"七言绝句","c":["黍筒小费名田课，昌歜多浮乐圣杯。","笑倩艾人看外户，北窗深处咏归来。"]},{"t":"代儿童作端午贴门诗三首 其二","f":"五言绝句","c":["管领神仙侣，追陪山长家。","往来惟意适，歌舞对年华。"]},{"t":"代儿童作端午贴门诗三首 其一","f":"五言绝句","c":["画閤围香里，明窗宴坐中。","兵符不须篆，丹转药炉红。"]},{"t":"代门生作立春书门贴子诗四首 其四","f":"五言绝句","c":["日月添书帙，湖山引杖藜。","剩周花甲子，多醉玉东西。"]},{"t":"代门生作立春书门贴子诗四首 其三","f":"五言绝句","c":["草木沾云露，峰峦近壁奎。","新春行乐处，南北共花溪。"]},{"t":"代门生作立春书门贴子诗四首 其二","f":"五言绝句","c":["有喜何须药，无尘即是仙。","壶中春日月，聊数八千年。"]},{"t":"代门生作立春书门贴子诗四首 其一","f":"五言绝句","c":["煖日黄金柳，光风白玉梅。","门阑开寿域，人物满春台。"]},{"t":"出塞路","f":"七言绝句","c":["当年玉帛聘辽阳，出塞曾歌此路长。","汉节重寻旧车辙，插天犹有万垂杨。"]},{"t":"北城梅为雪所厄","f":"七言绝句","c":["冻蕊粘枝瘦欲乾，新年犹未有春看。","雪花袛欲欺红紫，不道梅花也怕寒。"]},{"t":"半塘","f":"七言绝句","c":["柳暗阊门逗晓开，半塘塘下越溪回。","炊烟拥柂船船过，芳草缘堤步步来。"]},{"t":"占星者谓命宫月孛独行无害但去年复照作灾今年正月一日已出而岁星作福戏书二绝 其一","f":"七言绝句","c":["昔躔初度本除灾，何意重逢作病媒。","久住灵斿今日过，历翁欢喜劝椒杯。"]},{"t":"占星者谓命宫月孛独行无害但去年复照作灾今年正月一日已出而岁星作福戏书二绝 其二","f":"七言绝句","c":["暗曜加临有救神，煌煌福德自天仁。","只烦终惠苏残喘，官爵从渠奉董秦。"]},{"t":"卢沟","f":"七言绝句","c":["草草鱼梁枕水低，匆匆小驻濯涟漪。","河边服匿多生口，长记轺车放雁时。"]},{"t":"去年过弋阳访赵恂道通判话西湖旧游因题小诗近忽刻石寄来谩录","f":"七言绝句","c":["红尘宝马碧湖船，一梦如今费十年。","却照清溪寻绿鬓，但馀衰雪两萧然。"]},{"t":"发合江数里寄杨商卿诸公","f":"七言绝句","c":["临分满意说离愁，草草无言祇泪流。","船尾竹林遮县市，故人犹自立沙头。"]},{"t":"古梅二首 其一","f":"七言绝句","c":["孤标元不斗芳菲，雨瘦风皴老更奇。","压倒嫩条千万蕊，只消疏影两三枝。"]},{"t":"古梅二首 其二","f":"七言绝句","c":["谁似西湖处士才，诗中篱落久尘埃。","陆郎旧有梅花课，未见今年句子来。"]},{"t":"古鼎作香炉","f":"七言绝句","c":["云雷萦带古文章，子子孙孙永奉常。","辛苦勒铭成底事，如今流落管烧香。"]},{"t":"四时田园杂兴六十首 其二十三","f":"七言绝句","c":["海雨江风浪作堆，时新鱼菜逐春回。","荻芽抽笋河鲀上，楝子开花石首来。"]},{"t":"四十八盘","f":"七言绝句","c":["诘曲不前如宦拙，欹倾当面似交难。","若将世路比山路，世路更多千万盘。"]},{"t":"四月十六日拄笏亭偶题","f":"七言绝句","c":["转午闻鸡日正长，小亭方丈纳空光。","绿阴一雨浓如黛，何处风来百种香。"]},{"t":"四时田园杂兴六十首 其六","f":"七言绝句","c":["骑吹东来里巷喧，行春车马闹如烟。","系牛莫碍门前路，移系门西碌碡边。"]},{"t":"四时田园杂兴六十首 其四","f":"七言绝句","c":["老盆初熟杜茅柴，携向田头祭社来。","巫媪莫嫌滋味薄，旗亭官酒更多灰。"]},{"t":"四时田园杂兴六十首 其二十二","f":"七言绝句","c":["雨后山家起较迟，天窗晓色半熹微。","老翁欹枕听莺啭，童子开门放燕飞。"]},{"t":"四时田园杂兴六十首 其十","f":"七言绝句","c":["种园得果廑偿劳，不奈儿童鸟雀搔。","已插棘针樊笋径，更铺渔网盖樱桃。"]},{"t":"四时田园杂兴六十首 其十一","f":"七言绝句","c":["吉日初开种稻包，南山雷动雨连宵。","今年不欠秧田水，新涨看看拍小桥。"]},{"t":"四时田园杂兴六十首 其三","f":"七言绝句","c":["高田二麦接山青，傍水低田绿未耕。","桃杏满村春似锦，踏歌椎鼓过清明。"]},{"t":"四时田园杂兴六十首 其二十一","f":"七言绝句","c":["谷雨如丝复似尘，煮瓶浮蜡正尝新。","牡丹破萼樱桃熟，未许飞花减却春。"]},{"t":"四时田园杂兴六十首 其十七","f":"七言绝句","c":["新绿园林晓气凉，晨炊蚤出看移秧。","百花飘尽桑麻小，夹路风来阿魏香。"]},{"t":"四时田园杂兴六十首 其四十五","f":"七言绝句","c":["租船满载候开仓，粒粒如珠白似霜。","不惜两钟输一斛，尚赢糠覈饱儿郎。"]},{"t":"四时田园杂兴六十首 春日十二绝 其一","f":"七言绝句","c":["柳花深巷午鸡声，桑叶尖新绿未成。","坐睡觉来无一事，满窗晴日看蚕生。"]},{"t":"四时田园杂兴六十首 其三十五","f":"七言绝句","c":["采菱辛苦废犁锄，血指流丹鬼质枯。","无力买田聊种水，近来湖面亦收租。"]},{"t":"四时田园杂兴六十首 其十八","f":"七言绝句","c":["三旬蚕忌闭门中，邻曲都无步往踪。","犹是晓晴风露下，采桑时节暂相逢。"]},{"t":"四时田园杂兴六十首 夏日十二绝 其二十五","f":"七言绝句","c":["梅子金黄杏子肥，麦花雪白菜花稀。","日长篱落无人过，惟有蜻蜓蛱蝶飞。"]},{"t":"四时田园杂兴六十首 其五","f":"七言绝句","c":["社下烧钱鼓似雷，日斜扶得醉翁回。","青枝满地花狼藉，知是儿孙斗草来。"]},{"t":"四时田园杂兴六十首 其二十四","f":"七言绝句","c":["乌鸟投林过客稀，前山烟暝到柴扉。","小童一棹舟如叶，独自编阑鸭阵归。"]},{"t":"四时田园杂兴六十首 其二十","f":"七言绝句","c":["茅针香软渐包茸，蓬■甘酸半染红。","采采归来儿女笑，杖头高挂小筠笼。"]},{"t":"四时田园杂兴六十首 其三十一","f":"七言绝句","c":["昼出耘田夜绩麻，村庄儿女各当家。","童孙未解供耕织，也傍桑阴学种瓜。"]},{"t":"四时田园杂兴六十首 其十九","f":"七言绝句","c":["污莱一棱水周围，岁岁蜗庐没半扉。","不著茭青难护岸，小舟撑取葑田归。"]},{"t":"四时田园杂兴六十首 其四十四","f":"七言绝句","c":["新筑场泥镜面平，家家打稻趁霜晴。","笑歌声里轻雷动，一夜连枷响到明。"]},{"t":"四时田园杂兴六十首 其七","f":"七言绝句","c":["寒食花枝插满头，茜裙青袂几扁舟。","一年一度游山寺，不上灵岩即虎丘。"]},{"t":"四时田园杂兴六十首 其九","f":"七言绝句","c":["步屧寻春有好怀，雨馀蹄道水如杯。","随人黄犬搀前去，走到溪边忽自回。"]},{"t":"四时田园杂兴六十首 其十二","f":"七言绝句","c":["桑下春蔬绿满畦，菘心青嫩芥薹肥。","溪头洗择店头卖，日暮裹盐沽酒归。"]},{"t":"四时田园杂兴六十首 其八","f":"七言绝句","c":["郭里人家拜扫回，新开醪酒荐青梅。","日长路好城门近，借我茅亭煖一杯。"]},{"t":"四时田园杂兴六十首 其二","f":"七言绝句","c":["土膏欲动雨频催，万草千花一饷开。","舍后荒畦犹绿秀，邻家鞭笋过墙来。"]},{"t":"四花","f":"五言绝句","c":["素馨间末利，木犀和玉簪。","医来都屏去，头眩怕香侵。"]},{"t":"四明人董峄久居岳市乞诗","f":"七言绝句","c":["祝融峰下两逢春，雨宿风餐老病身。","莫笑五湖萍梗客，海边亦有未归人。"]},{"t":"市街","f":"七言绝句","c":["梳行讹杂马行残，药市萧骚土市寒。","惆怅软红佳丽地，黄沙如雨扑征鞍。"]},{"t":"平云阁","f":"七言绝句","c":["背倚天峰涌化宫，横空阁道拖双虹。","火云六月应奇绝，青琐玲珑八面风。"]},{"t":"归州竹枝歌二首 其一","f":"七言绝句","c":["东邻男儿得湘累，西舍女儿生汉妃。","城郭如村莫相笑，人家伐阅似渠稀。"]},{"t":"旧滑州","f":"七言绝句","c":["大伾山麓马徘徊，积水中间旧滑台。","渔子不知兴废事，清晨吹笛棹船来。"]},{"t":"正月六日风雪大作 其二","f":"七言绝句","c":["奇寒何事入芳辰，不管灯枝欲试新。","即日反风吹尽雪，东君已费一分春。"]},{"t":"正月六日风雪大作 其一","f":"七言绝句","c":["滕六无端巽二痴，翻天作恶破春迟。","邀梅勒柳何功业，谁与停杯一问之。"]},{"t":"玉茗花","f":"七言绝句","c":["折得瑶华付与谁，人间铅粉弄妆迟。","直须远寄骖鸾客，鬓脚飘飘可一枝。"]},{"t":"玉虚观去宜春二十五里许君上升时飞白茅数叶以赐王长史王以宅为观观旁至今有仙茅极异常草备五味尤辛辣云久食可仙道士煮汤以设客","f":"七言绝句","c":["白云堆里白茅飞，香味芳辛胜五芝。","揉叶煮泉摩腹去，全胜石髓畏风吹。"]},{"t":"玉麟堂会诸司观牡丹酴醾三绝 其一","f":"七言绝句","c":["东风微峭护馀春，红紫香中酒自温。","不用忙催银烛上，酴醾如雪照黄昏。"]},{"t":"玉麟堂会诸司观牡丹酴醾三绝 其二","f":"七言绝句","c":["洛园姚魏碧云愁，风物江东亦上游。","忆起遨头八年梦，彭州花槛满西楼。"]},{"t":"玉麟堂会诸司观牡丹酴醾三绝 其三","f":"七言绝句","c":["莫向花前惜酒杯，一年一度有花开。","浮生满百今强半，岁岁看花得几回。"]},{"t":"题蜀果图四首 其四 甘瓜","f":"五言绝句","c":["夏肤粗已皴，秋蒂熟将脱。","不辞抱蔓归，聊慰相如渴。"]},{"t":"甘雨应祈三绝 其一","f":"七言绝句","c":["晚稻成苞未肯肥，鹁鸠啼晓雨来时。","黄紬被冷初眠觉，先向芭蕉叶上知。"]},{"t":"甘雨应祈三绝 其二","f":"七言绝句","c":["数日虽蒙霢霂沾，浥尘终恨太廉纤。","今朝健起巡檐看，恰似庐山看水帘。"]},{"t":"甘雨应祈三绝 其三","f":"七言绝句","c":["高田一雨免飞埃，上水纲船亦可催。","说与东江津吏道，打量今晚涨痕来。"]},{"t":"甘棠驿","f":"七言绝句","c":["万里三年醉岭梅，东风刮地马头回。","心劳政拙无遗爱，惭向甘棠驿里来。"]},{"t":"田家","f":"七言绝句","c":["稚子呼牛女拾薪，山妻自脍小溪鳞。","安知曝背庭中老，不是渊明行辈人。"]},{"t":"白云岭","f":"七言绝句","c":["路入千峰一线通，陆离长剑立天风。","五年领客题诗处，正在孤云乱石中。"]},{"t":"白云泉","f":"七言绝句","c":["龙头高啄嗽飞流，玉醴甘浑乳气浮。","扪腹煮泉烹斗胯，真成骑鹤上扬州。"]},{"t":"白莲堂","f":"七言绝句","c":["古木参天护碧池，青钱弱叶战涟漪。","匆匆游子匆匆去，不见风清月冷时。"]},{"t":"白善坑","f":"七言绝句","c":["银须玉璞紫金精，犯难穷探亦有名。","白垩区区土同价，吴侬无事亦轻生。"]},{"t":"石湖芍药盛开向北使归过维扬时买根栽此因记旧事二首 其二","f":"七言绝句","c":["万里归程许过家，移将二十四桥花。","石湖从此添春色，莫把蒲萄苜蓿誇。"]},{"t":"石湖芍药盛开向北使归过维扬时买根栽此因记旧事二首 其一","f":"七言绝句","c":["竹西歌吹荻花秋，遗老垂洟送远游。","羌笛夜阑吹出塞，当年如此梦扬州。"]},{"t":"立春枕上","f":"七言绝句","c":["择蔬翻饼闹残更，儿女喧喧短梦惊。","想得春风连夜到，东禅粥鼓忽分明。"]},{"t":"立秋二绝 其一","f":"七言绝句","c":["三伏熏蒸四大愁，暑中方信此生浮。","岁华过半休惆怅，且对西风贺立秋。"]},{"t":"立秋二绝 其二","f":"七言绝句","c":["折枝楸叶起园瓜，赤小如珠咽井花。","洗濯烦襟酬节物，安排笑口问生涯。"]},{"t":"立秋后二日泛舟越来溪三绝 其一","f":"七言绝句","c":["西风初入小溪帆，旋织波纹绉浅蓝。","行入闹荷无水面，红莲沉醉白莲酣。"]},{"t":"龙母庙","f":"七言绝句","c":["孝龙分职隶湘西，天许宁亲岁一归。","风雹春春损桃李，山中寒食尚冬衣。"]},{"t":"龙津桥","f":"七言绝句","c":["燕石扶栏玉作堆，柳塘南北抱城回。","西山剩放龙津水，留待官军饮马来。"]},{"t":"伊尹墓","f":"七言绝句","c":["三尺黄垆直棘边，此心终古享皇天。","汲书猥述流传妄，剖击嗟无咎单篇。"]},{"t":"会同馆","f":"七言绝句","c":["万里孤臣致命秋，此身何止一沤浮。","提携汉节同生死，休问羝羊解乳不。"]},{"t":"会散夜步","f":"七言绝句","c":["忘却下楼扶我谁，接䍦颠倒酒沾衣。","贪看雪样满街月，不上篮舆步砌归。"]},{"t":"光武庙","f":"七言绝句","c":["云台列像拱真人，野老犹誇建武春。","不用剑锋能刜石，冰河一瞥已通神。"]},{"t":"再赋末利二绝 其二","f":"七言绝句","c":["忆曾把酒泛湘漓，末利毬边擘荔枝。","一笑相逢双玉树，花香如梦鬓如丝。"]},{"t":"再赋末利二绝 其一","f":"七言绝句","c":["薰蒸沉水意微茫，全树飞来烂熳香。","休向寒鸦看日景，袛今飞燕侍昭阳。"]},{"t":"再赋郡沼双莲三绝 其二","f":"七言绝句","c":["池光阑槛倚斜晖，把酒看花醉不归。","但许鸳鸯相对浴，休惊翡翠一双飞。"]},{"t":"再赋郡沼双莲三绝 其一","f":"七言绝句","c":["馆娃魂散碧云沉，化作双葩寄恨深。","千载不偿连理愿，一枝空有合欢心。"]},{"t":"再赋郡沼双莲三绝 其三","f":"七言绝句","c":["两岐秀罢已蒿莱，春意还从菡萏回。","不是使君和气胜，此花应向别人开。"]},{"t":"再赋简养正","f":"七言绝句","c":["南北梅枝噤雪寒，玉梨皴雨泪阑干。","一年春色摧残尽，更觅姚黄魏紫看。"]},{"t":"再赠寿老","f":"七言绝句","c":["澹斋寂莫澹庵空，玉柱金庭一梦中。","我病君衰犹见在，莫嫌俱作白头翁。"]},{"t":"华山道中","f":"七言绝句","c":["过午曾云未肯开，暖寒村店竹初灰。","萧萧林响棠梨战，晚恐阳山有雨来。"]},{"t":"吊陈叔宝词","f":"七言绝句","c":["赏心亭上再来游，烟月迷人独自愁。","行到江边无去路，却随潮水过扬州。"]},{"t":"守风嘲舟子","f":"七言绝句","c":["夺命稠滩百战馀，守风端坐恰乘除。","日长饱饭佳眠觉，閒傍芦花学钓鱼。"]},{"t":"安肃军","f":"七言绝句","c":["从古铜门控朔方，南城烟火北城荒。","台家抵死争溏泺，满眼秋芜衬夕阳。"]},{"t":"寺庄","f":"七言绝句","c":["大麦成苞小麦深，秧田水满绿浮针。","今年一饱全无虑，宽尽归舟去客心。"]},{"t":"州桥","f":"七言绝句","c":["州桥南北是天街，父老年年等驾回。","忍泪失声询使者，几时真有六军来。"]},{"t":"庆充自黄山归索其道中诗书一绝问之","f":"七言绝句","c":["鸣驺如电马如雷，知是婆娑醉尉回。","常日锦囊犹有句，况从三十六峰来。"]},{"t":"戏书二首 其一","f":"七言绝句","c":["长病人嫌理亦宜，吾今有计可扶衰。","烦君舁著山深处，恐有黄龙浴水医。"]},{"t":"戏书麻线堆下","f":"七言绝句","c":["一身半世走奔波，疑是三生宿债多。","折券已饶麻线岭，责偿难免竹竿坡。"]},{"t":"戏咏絮帽","f":"七言绝句","c":["尖斜缁撮似兜鍪，紧护风寒煖白头。","不解兵前当箭凿，解令晓枕睡齁齁。"]},{"t":"戏题无常钟二绝 其二","f":"七言绝句","c":["合成四大散成空，草木经春便有冬。","生灭去来相对代，为君题作有常钟。"]},{"t":"戏题无常钟二绝 其一","f":"七言绝句","c":["著衫脱裤两浮休，切莫随渠认路头。","三尺蒲牢关底事，寻声接响大悠悠。"]},{"t":"戏题牡丹","f":"七言绝句","c":["主人细意惜芳春，宝帐笼阶护紫云。","风日等閒犹不到，外边蜂蝶莫纷纷。"]},{"t":"戏题药裹","f":"七言绝句","c":["捲却丝纶飏却竿，莫随鱼鳖弄腥涎。","须知别有垂钩处，枯海无风浪拍天。"]},{"t":"戏题赵从善两画轴三首 其三","f":"七言绝句","c":["搔头珠重步微摇，约臂金寒束未牢。","要见低鬟揎玉腕，更须斜抱紫檀槽。"]},{"t":"戏题赵从善两画轴三首 其二","f":"七言绝句","c":["无笑无言两断魂，一杯谁为煖霜寒。","情知别有真真在，试与千呼万唤看。"]},{"t":"戏题赵从善两画轴三首 其一","f":"七言绝句","c":["一枝香杏一枝梅，各占东风挂玉钗。","居士石肠都似梦，王孙心眼怎安排。"]},{"t":"戏题致远书房","f":"七言绝句","c":["照丛菊靥万黄金，欹架薇条半绿阴。","逋客已随丹凤诏，但馀花草怨秋深。"]},{"t":"戏赠少梁","f":"七言绝句","c":["屈膝铜铺昼掩关，薰炉谁伴夕香寒。","秋来合有相思字，会待风前片叶看。"]},{"t":"戏赠脚婆","f":"七言绝句","c":["日满东窗照被堆，宿汤犹自暖如煨。","尺三汗脚君休笑，曾踏靴霜待漏来。"]},{"t":"次韵马少伊郁舜举寄示同游石湖诗卷七首 其七","f":"七言绝句","c":["潇洒王郎亦胜流，今年何事阻清游。","当家风味今如此，孤负山阴夜雪舟。"]},{"t":"次韵马少伊郁舜举寄示同游石湖诗卷七首 其六","f":"七言绝句","c":["得得来题小隐诗，拂香萦柳画船移。","湖边好景春犹未，须到秋清月满时。"]},{"t":"次韵马少伊郁舜举寄示同游石湖诗卷七首 其五","f":"七言绝句","c":["两贤风度蔼春阳，步屧随风上柳塘。","綵笔红笺芳径里，句中挟我万花香。"]},{"t":"次韵马少伊郁舜举寄示同游石湖诗卷七首 其四","f":"七言绝句","c":["红皱黄团熟暑风，甘瓜削玉藕玲珑。","身谋已落园丁后，满帽京尘日正中。"]},{"t":"次韵马少伊郁舜举寄示同游石湖诗卷七首 其三","f":"七言绝句","c":["镜面波光倒碧峰，半湖云锦万芙蓉。","去年荡桨香风里，行傍石桥花正浓。"]},{"t":"次韵马少伊郁舜举寄示同游石湖诗卷七首 其二","f":"七言绝句","c":["莫问朝歌与棘津，浮生惟有一杯春。","君看百战功名地，越戍吴台两窖尘。"]},{"t":"次韵马少伊郁舜举寄示同游石湖诗卷七首 其一","f":"七言绝句","c":["芜城老藓不知春，忽有柴门月色新。","芝草琅玕无锁钥，自无超俗扣门人。"]},{"t":"次韵乐先生吴中见寄八首 其二","f":"七言绝句","c":["官居门巷果园西，桃李成蹊杏压枝。","如许年芳忙里过，斩新今日试题诗。"]},{"t":"次韵乐先生吴中见寄八首 其五","f":"七言绝句","c":["送春濛雨涨蘋滩，荷叶田田柳絮阑。","想见垂虹三万顷，拍天湖水钓丝寒。"]},{"t":"次韵乐先生吴中见寄八首 其一","f":"七言绝句","c":["金鹤飞来尺素通，新诗字字挟光风。","三年湖海关心处，都在先生句子中。"]},{"t":"次韵乐先生吴中见寄八首 其六","f":"七言绝句","c":["知从了义透音闻，古井无波岂更浑。","便好一坑埋众妙，何须六结解诸根。"]},{"t":"次韵乐先生吴中见寄八首 其四","f":"七言绝句","c":["懒不看书似姓边，梦魂飞绕白鸥前。","须知席帽冲尘出，不似篷窗听雨眠。"]},{"t":"次韵乐先生吴中见寄八首 其三","f":"七言绝句","c":["暮林栖鸟各深枝，燕子知巢触幔飞。","倘有三椽今已去，不关五斗解忘归。"]},{"t":"次韵乐先生吴中见寄八首 其八","f":"七言绝句","c":["粟囊聊复寄三餐，埋没缁尘懒濯冠。","红紫百般纷过眼，乡山岁晚自苍官。"]},{"t":"次韵乐先生吴中见寄八首 其七","f":"七言绝句","c":["几多蝼蚁与王侯，往古来今共一丘。","遮莫功名掀宇宙，百年两角寄蜗牛。"]},{"t":"次韵乐先生除夜三绝 其二","f":"七言绝句","c":["天边客里五迎冬，争信还乡似寓公。","人事都非城郭是，独怜鸡犬识新丰。"]},{"t":"次韵乐先生除夜三绝 其三","f":"七言绝句","c":["床头历日鬓丝丝，懒倦慵吟守岁诗。","宜入新年须吉利，明朝把笔写门楣。"]},{"t":"次韵乐先生除夜三绝 其一","f":"七言绝句","c":["团蒲曲几坐成痴，北看南观恍是非。","道眼已空诗眼在，梅花欲动雪花稀。"]},{"t":"次韵代答刘文潜司业二绝 其一","f":"七言绝句","c":["平羌江上首空回，慈姥岩前定把杯。","纵使石肠都忘却，也应风雨送愁来。"]},{"t":"次韵代答刘文潜司业二绝 其二","f":"七言绝句","c":["回廊月下短歌行，惟有知音解有情。","一曲红窗声里怨，如今分作两愁城。"]},{"t":"次韵汉卿舅即事二绝 其二","f":"七言绝句","c":["万木垂垂欲改柯，根萌焦渴奈春何。","晚来础汗南风壮，会有溪云载雨过。"]},{"t":"次韵汉卿舅即事二绝 其一","f":"七言绝句","c":["风捲南枝一夜休，孤芳宁肯为人留。","淡妆素服真成梦，落月横参各自愁。"]},{"t":"次韵汉卿舅腊梅二首 其一","f":"七言绝句","c":["垂垂瘦萼泫微霜，剪剪纤英锁暗香。","金雀钗头金蛱蝶，春风传得旧宫妆。"]},{"t":"次韵汉卿舅腊梅二首 其二","f":"七言绝句","c":["湘袂朝天紫锦裳，光风微度绛霄香。","寿阳信美无仙骨，空把心情学澹妆。"]},{"t":"次韵孙长文泊姑苏馆","f":"七言绝句","c":["读书窗下一灯残，忽有诗来为暖寒。","闻道扁舟春共载，雪云虽冷不相干。"]},{"t":"次韵朱严州从李徽州乞牡丹三首 其三","f":"七言绝句","c":["阆风苑里司花女，肯作山腰水尾来。","十二玉栏天一笑，只今归路五云开。"]},{"t":"次韵朱严州从李徽州乞牡丹三首 其二","f":"七言绝句","c":["歙浦烟山蟠万叠，钓台云日拥千章。","两侯好事洗寒劣，宝槛移春入燕香。"]},{"t":"次韵朱严州从李徽州乞牡丹三首 其一","f":"七言绝句","c":["佳人绝世堕空谷，破恨解颜春亦来。","莫对溪山话京洛，碧云西北涨黄埃。"]},{"t":"次韵李子永梅村散策图","f":"七言绝句","c":["光风先放越溪春，萧散寻诗索笑人。","藜杖前头春浩荡，三生应是主林神。"]},{"t":"次韵汪仲嘉尚书喜雨 其二","f":"七言绝句","c":["老身穷若不须忧，未有毫分慰此州。","但得田间无叹息，何须地上见钱流。"]},{"t":"次韵汪仲嘉尚书喜雨 其一","f":"七言绝句","c":["雨云浑似雪云同，天意人心本自通。","吏役驱驱骑马滑，何如欹枕闭门中。"]},{"t":"次韵陆务观编修新津遇雨不得登修觉山径过眉州三绝 其二","f":"七言绝句","c":["离合纷纷怕远游，远游仍怕赋登楼。","何须一望三千里，望尽西州转更愁。"]},{"t":"次韵陆务观慈姥岩酌别二绝 其一","f":"七言绝句","c":["送我弥旬未忍回，可怜萧索把离杯。","不辞更宿中岩下，投老馀年岂再来。"]},{"t":"次韵陆务观慈姥岩酌别二绝 其二","f":"七言绝句","c":["明朝真是送人行，从此关山隔故情。","道义不磨双鲤在，蜀江流水贯吴城。"]},{"t":"次韵周子充正字馆中绯碧两桃花","f":"七言绝句","c":["碧城香雾赤城霞，深出刘郎未见花。","凭仗天风扶绛节，为招萼绿过羊家。"]},{"t":"次韵朋元卖花处见梅","f":"七言绝句","c":["烟浓日淡不多寒，担上看花雪作团。","想得竹边春已暗，明朝走马过溪看。"]},{"t":"次韵宣州西园二首 其一","f":"七言绝句","c":["苔茵无地著红尘，花草含芳一笑新。","不待东君能剪刻，相公笔力挽回春。"]},{"t":"次韵宣州西园二首 其二","f":"七言绝句","c":["星芒垂耀笔床寒，河汉波流砚滴乾。","棐几松跗入三昧，一篇诗就一杯残。"]},{"t":"次韵赵养民碧虚坐上","f":"七言绝句","c":["已将山色染眉黛，更挽江波添酒罍。","珍重江山劝人醉，笑人驱马惺惺回。"]},{"t":"次韵徐廷献机宜送自酿石室酒三首 其三","f":"七言绝句","c":["一语为君评石室，三杯便可博凉州。","百年兀兀同渠住，何处能生半点愁。"]},{"t":"次韵徐廷献机宜送自酿石室酒三首 其二","f":"七言绝句","c":["清绝仍香如橘露，甘馀小苦似松肪。","官槽重浊那知此，付与街头白面郎。"]},{"t":"次韵徐提举游石湖三绝 其三","f":"七言绝句","c":["天上麒麟翰墨林，当家手笔擅文心。","欲知万顷陂中意，但向三篇句里寻。"]},{"t":"次韵徐提举游石湖三绝 其二","f":"七言绝句","c":["日脚烘晴已破烟，山头云气尚披绵。","却须多谢朝来雨，洗净明湖镜里天。"]},{"t":"次韵徐提举游石湖三绝 其一","f":"七言绝句","c":["三径荒芜岫幌开，锦车何事肯徘徊。","春风想为高人住，落絮残花好在哉。"]},{"t":"次韵耿时举苦热","f":"七言律诗","c":["赤日才低又火云，巷南街北断知闻。","荷风拂簟昭苏我，竹月筛窗慰藉君。","避暑无奇那避谤，能觞便了莫能文。","浮湛放荡从今始，悔把长裾强沐薰。"]},{"t":"次韵致远自毗陵见寄二首 其一","f":"七言绝句","c":["黄鹄高飞碧落寒，向来山水梦惊残。","故情若问玄真子，依旧江头把钓竿。"]},{"t":"次韵致远自毗陵见寄二首 其二","f":"七言绝句","c":["新词一阕话羁愁，清似寒泉咽陇头。","官下有谁同此景，仲宣应是独登楼。"]},{"t":"次韵袁起岩许浦按教水军二绝句 其二","f":"七言绝句","c":["戈船战棹疾如飞，莫遣潮沙淀海湄。","草奏直须穷利病，奉身从此系安危。"]},{"t":"次韵袁起岩许浦按教水军二绝句 其一","f":"七言绝句","c":["横波组练试扬舲，风捲鱼龙海欲凝。","但得绨袍如挟纩，何妨铁甲冷如冰。"]},{"t":"次韵袁起岩常熟道中三绝句 其一","f":"七言绝句","c":["小雨萧寒破晚晴，疏疏密密滴檐声。","乌鸦盘舞黄云乱，早与商量雪意生。"]},{"t":"次韵袁起岩常熟道中三绝句 其三","f":"七言绝句","c":["使君横槊赋诗回，断取天风海雨来。","綵笔从今閒不得，雪花梅蕊一时开。"]},{"t":"次韵袁起岩常熟道中三绝句 其二","f":"七言绝句","c":["仄径难胜四牡騑，扁舟辛苦凿冰归。","简书鞅掌吟诗苦，并与东阳减带回。"]},{"t":"次韵郭季勇机宜雪观席上留别","f":"七言律诗","c":["胜绝尊前万事休，纵非吾土且登楼。","山迎雨脚俄飞过，风约江声欲倒流。","野水渐堪添酒面，夕阳依旧满帘钩。","凭阑从此迟归鞅，能及中秋对月不。"]},{"t":"次韵龚养正中秋无月三首 其三","f":"七言绝句","c":["丙夜清光些子见，儿童惊喜强雄夸。","阑珊高兴应无几，恰似春残看落花。"]},{"t":"次韵龚养正中秋无月三首 其二","f":"七言绝句","c":["去年怪雨无端甚，今岁痴云亦复然。","减却新诗酸却酒，乘除添得一更眠。"]},{"t":"次韵龚养正中秋无月三首 其一","f":"七言绝句","c":["词客幕天清露下，老翁卧病破窗中。","高吟大醉输公等，不见嫦娥与我同。"]},{"t":"次韵龚养正送水仙花","f":"七言绝句","c":["色界香尘付八还，正观不起况邪观。","花前犹有诗情在，还作凌波步月看。"]},{"t":"次韵曾仲躬侍郎同登伏龟楼二绝 其二","f":"七言绝句","c":["古来游客谩西东，领会谁如我与公。","露坐绳床天不尽，绝胜帘雨栋云中。"]},{"t":"次韵曾仲躬侍郎同登伏龟楼二绝 其一","f":"七言绝句","c":["带束江淮翠岫围，掌窥台殿碧鳞差。","刘郎句里登临眼，压倒三江二水诗。"]},{"t":"次韵温伯苦蚊","f":"七言绝句","c":["白鸟营营夜苦饥，不堪薰燎出窗扉。","小虫与我同忧患，口腹驱来敢倦飞。"]},{"t":"江上","f":"五言绝句","c":["天色无情淡，江声不断流。","古人愁不尽，留与后人愁。"]},{"t":"灯夕怀广蜀旧事","f":"七言绝句","c":["漓水桥西列炬香，少城楼下变灯忙。","儿嬉万里客程远，老懒一龛春梦长。"]},{"t":"灰洞","f":"七言绝句","c":["塞北风沙涨帽檐，路经灰洞十分添。","据鞍莫问尘多少，马耳冥濛不见尖。"]},{"t":"百丈山","f":"七言绝句","c":["沐雨梳风有底忙，解鞍来宿赞公房。","传闻三岭连天峻，未到王千已断肠。"]},{"t":"老陈道人自云梦被召作地上主者又常受一贵家供祝之曰他日必来吾家作儿戏赠小颂","f":"七言绝句","c":["野人何苦赴官差，符使追呼挠道怀。","幸有于门香积供，不如随喜去罗斋。"]},{"t":"耳鸣","f":"七言绝句","c":["风号高木水翻洪，历历音闻不是聋。","一任大千都震吼，便从卷叶證圆通。"]},{"t":"自天平岭过高景庵","f":"七言绝句","c":["卓笔峰前树作团，天平岭上石成关。","绿阴匝地无人过，落日秋蝉满四山。"]},{"t":"自宁国溪行至宣城舟人云凡百八十滩","f":"七言绝句","c":["波惊石险夜喧雷，晓泊旗亭笑眼开。","休问行人缘底瘦，适从百八十滩来。"]},{"t":"自育王过天童松林三十里","f":"七言绝句","c":["竹舆窈窕入萧森，逗雨梳风冷客襟。","翠锦屠苏三十里，不知脚底白云深。"]},{"t":"自横塘桥过黄山","f":"七言绝句","c":["阵阵轻寒细马骄，竹林茅店小帘招。","东风已绿南溪水，更染溪南万柳条。"]},{"t":"至昌为具赏东轩千叶梅然梅尚未开","f":"七言绝句","c":["玉叶重英意已芽，新移竹外小横斜。","东斋何事春工晚，铁树已花梅未花。"]},{"t":"芒种后积雨骤冷三绝 其三","f":"七言绝句","c":["梅霖倾泻九河翻，百渎交流海面宽。","良苦吴农田下湿，年年披絮插秧寒。"]},{"t":"芒种后积雨骤冷三绝 其二","f":"七言绝句","c":["梅黄时节怯衣单，五月江吴麦秀寒。","香篆吐云生暖热，从教窗外雨漫漫。"]},{"t":"芒种后积雨骤冷三绝 其一","f":"七言绝句","c":["一庵湿蛰似龟藏，深夏暄寒未可常。","昨日蒙絺今挟纩，莫嗔门外有炎凉。"]},{"t":"西瓜园","f":"七言绝句","c":["碧蔓凌霜卧软沙，年来处处食西瓜。","形模濩落淡如水，未可蒲萄苜蓿誇。"]},{"t":"讲武城","f":"七言绝句","c":["阿瞒虓武盖刘孙，千古还将鬼蜮论。","纵有周遭遗堞在，不如鱼复阵图尊。"]},{"t":"过江津县睡熟不暇梢船","f":"七言绝句","c":["西风扶橹似乘槎，水阔滩沉浪不花。","梦里竹间喧急雪，觉来船底滚鸣沙。"]},{"t":"过虎溪对东林苍岩翠樾下浸大涧宛似灵隐冷泉嘱长老法才作亭名曰过溪且为率山丁薙草定基一朝而毕","f":"七言绝句","c":["过溪无限翠屏开，大笑从教虎子猜。","不独山中添故事，仍教题作小飞来。"]},{"t":"过燕渡望大峨有白气如层楼拔起丛云中","f":"七言绝句","c":["围野千山暑气昏，大峨烟霭亦缤纷。","玉峰忽起三千丈，应是兜罗世界云。"]},{"t":"邢台驿","f":"七言绝句","c":["太行东麓照邢州，万叠烟螺紫翠浮。","谁解登临管风物，枯荷老柳替人愁。"]},{"t":"严关","f":"七言绝句","c":["回看瘴岭已无忧，尚有严关限北州。","裹饭长歌关外去，车如飞电马如流。"]},{"t":"严州","f":"七言绝句","c":["城府黄尘扑马鞍，一篙重探水云寒。","耳边眼底无公事，睡过严州二百滩。"]},{"t":"何同年书院","f":"五言绝句","c":["竹色侵晚帙，泉声漱嵌根。","试通丹灶路，应到老人村。"]},{"t":"馀杭","f":"七言绝句","c":["春晚山花各静芳，从教红紫送韶光。","忍冬清馥蔷薇酽，薰满千村万落香。"]},{"t":"馀杭初出陆","f":"七言绝句","c":["村媪群观笑老翁，宦途何处苦龙钟。","霜毛瘦骨犹千骑，少见行人似个侬。"]},{"t":"冷泉亭放水","f":"七言绝句","c":["古苔危磴著枯藜，脚底翻涛汹欲飞。","九陌倦游那有此，从教惊雪溅尘衣。"]},{"t":"初入湖南醴陵界","f":"七言绝句","c":["崖树阴阴夹暝途，出山欢喜见平芜。","一春客梦饱风雨，行尽江南闻鹧鸪。"]},{"t":"初三日出东郊碑楼院","f":"七言绝句","c":["远柳新晴暝紫烟，小江吹冻舞清涟。","红尘一鬨人归后，跕跕饥鸢蹙纸钱。"]},{"t":"初见山花","f":"七言绝句","c":["三日晴泥尚没靴，几将风雨过年华。","湘东二月春才到，恰有山樱一树花。"]},{"t":"初秋二首 其二","f":"五言绝句","c":["壮岁故多病，老年知不堪。","何须看公案，只此是真参。"]},{"t":"初秋二首 其一","f":"五言绝句","c":["急雨过窗纸，新凉生簟藤。","蹒跚老铃下，来炷壁间灯。"]},{"t":"岩桂三首 其三","f":"七言绝句","c":["一株萧索倚宣华，东苑香风属内家。","丹碧屠苏银烛照，平生奇绝象山花。"]},{"t":"岩桂三首 其二","f":"七言绝句","c":["越城芳径手亲栽，红浅黄深次第开。","不用小山招隐赋，身如强健日千回。"]},{"t":"初夏二首 其二","f":"七言绝句","c":["晴丝千尺挽韶光，百舌无声燕子忙。","永日屋头槐影暗，微风扇里麦花香。"]},{"t":"初夏二首 其一","f":"七言绝句","c":["清晨出郭更登台，不见馀春只么回。","桑叶露枝蚕向老，菜花成荚蝶犹来。"]},{"t":"初夏三绝呈游子明王仲显 其二","f":"七言绝句","c":["一帘芳树绿葱葱，胡蝶飞来觅绮丛。","雪白荼蘼红宝相，尚携春色见薰风。"]},{"t":"初夏三绝呈游子明王仲显 其一","f":"七言绝句","c":["东君不解惜芳菲，料峭寒中一梦非。","剪尽牡丹梅子绽，何须风雨送春归。"]},{"t":"初夏三绝呈游子明王仲显 其三","f":"七言绝句","c":["送春迎夏未闻雷，日日斜风细雨来。","不是故人能裹饭，柴门虽设为谁开。"]},{"t":"即事","f":"七言绝句","c":["醉袖笼鞭转柳塘，青门芳树掩残香。","谁惊翡翠双飞去，只有莲花对断肠。"]},{"t":"吴灯两品最高","f":"七言绝句","c":["镂冰影里百千光，剪綵毬中一万窗。","不是齐人誇管晏，吴中风物竟难双。"]},{"t":"赠寿老","f":"七言绝句","c":["农圃规模昔共论，云奎卜筑又逢君。","眉庵寿老长随喜，好个抛梁伏愿文。"]},{"t":"围田叹四绝 其四","f":"七言绝句","c":["台家水利有科条，膏润千年废一朝。","安得能言两黄鹄，为君重唱复陂谣。"]},{"t":"围田叹四绝 其二","f":"七言绝句","c":["山边百亩古民田，田外新围截半川。","六七月间天不雨，若为车水到山边。"]},{"t":"围田叹四绝 其三","f":"七言绝句","c":["壑邻罔利一家优，水旱无妨众户愁。","浪说新收若干税，不知逋失万新收。"]},{"t":"围田叹四绝 其一","f":"七言绝句","c":["万夫堙水水乾源，障断江湖极目天。","秋潦灌河无泄处，眼看漂尽小家田。"]},{"t":"宋玉宅","f":"七言绝句","c":["悲秋人去语难工，摇落空山草木风。","犹有市人传旧事，酒垆还在宋家东。"]},{"t":"寿栎前假山成移丹桂于马城自嘲","f":"七言绝句","c":["堂前趣就小嶙峋，未许蹒跚杖屦亲。","更遣移花三百里，世间真有大痴人。"]},{"t":"寿栎堂枕上","f":"七言绝句","c":["禅床初著小山屏，夜久秋凉枕席清。","绕鬓飞蚊妨好梦，卧听檐雨入池声。"]},{"t":"张恭甫正字折赠馆中碧桃因次子充韵","f":"七言绝句","c":["满枝晴雪照青霞，旧识桃源晕碧花。","俯仰京尘隔年梦，东风犹认故人家。"]},{"t":"怀古亭","f":"七言绝句","c":["朝来写得故人书，双鲤难寻雁亦无。","付与离堆江水去，解从郫县到成都。"]},{"t":"怀桂林所思亭","f":"七言绝句","c":["篸山奇绝送归时，曾榜新亭号所思。","桂水祗今湘水外，他年空有四愁诗。"]},{"t":"护龙河","f":"七言绝句","c":["新郭门前见客舟，清涟浅浅抱城楼。","六龙行在东南国，河若能神合断流。"]},{"t":"李次山自画两图其一泛舟湖山之下小女奴坐船头吹笛其一跨驴渡小桥入深谷各题一绝 其二","f":"七言绝句","c":["黄尘车马梦初阑，杳杳骑驴紫翠间。","饱识千峰真面目，当年拄笏漫看山。"]},{"t":"李次山自画两图其一泛舟湖山之下小女奴坐船头吹笛其一跨驴渡小桥入深谷各题一绝 其一","f":"七言绝句","c":["船头月午坐忘归，不管风鬟露满衣。","横玉三声湖起浪，前山应有鹊惊飞。"]},{"t":"李固渡","f":"七言绝句","c":["洪河万里界中州，倒捲银潢聒地流。","列弩燔梁那可渡，向来天数亦人谋。"]},{"t":"杨少监寄西征近诗来因赋二绝为谢诗卷第一首乃石湖作别时倡和也 其二","f":"七言绝句","c":["锦囊随上越王台，天海风涛亦壮哉。","书到岭头梅恰动，一枝应伴一篇来。"]},{"t":"杨少监寄西征近诗来因赋二绝为谢诗卷第一首乃石湖作别时倡和也 其一","f":"七言绝句","c":["柴门重客醉中归，尚忆挥毫索纸时。","何物与侬供不朽，西征卷首石湖诗。"]},{"t":"汴河","f":"七言绝句","c":["指顾枯河五十年，龙舟早晚定疏川。","还京却要东南运，酸枣棠梨莫蓊然。"]},{"t":"沈家店道傍棣棠花","f":"七言绝句","c":["乍晴芳草竞怀新，谁种幽花隔路尘。","绿地缕金罗结带，为谁开放可怜春。"]},{"t":"澧江渔舍","f":"七言绝句","c":["狡窟空来四十年，沿江犹自少炊烟。","茫茫旷土无人问，芦荻春深绿满川。"]},{"t":"澧浦","f":"七言绝句","c":["苇岸齐齐似碧城，江船罨岸逆风行。","绿蘋白芷俱憔悴，惟有蒌蒿满意生。"]},{"t":"灵祐观","f":"七言绝句","c":["旸谷西门锁洞宫，古苔斑驳桧蒙茸。","百廊三殿惟眢井，万壑千岩有瘦筇。"]},{"t":"灵泉","f":"七言绝句","c":["泉螭无语笑经过，欲拊茕鳏奈拙何。","孤奉明恩虽出岭，欢颜终少汗颜多。"]},{"t":"社日独坐","f":"七言绝句","c":["海棠雨后沁胭脂，杨柳风前撚绿丝。","香篆结云深院静，去年今日燕来时。"]},{"t":"秀州门外泊舟","f":"七言绝句","c":["拍岸清波扑岸埃，黑头霜鬓几徘徊。","禾兴门外官杨柳，又见扁舟上堰来。"]},{"t":"纳凉","f":"七言绝句","c":["雨洗新秋夜气清，悴肌无汗葛衣轻。","画檐分月下西壁，络纬飞来庭树鸣。"]},{"t":"良乡","f":"七言绝句","c":["新寒冻指似排签，村酒虽酸未可嫌。","紫烂山梨红皱枣，总输易栗十分甜。"]},{"t":"进修堂前荷池","f":"七言绝句","c":["方池留水胜埋盆，露入莲腮沁粉痕。","铃索无声人不到，小禽飞入闹荷根。"]},{"t":"连夕大风凌寒梅已零落殆尽三绝 其二","f":"七言绝句","c":["玉雪飘零贱似泥，惜花还记赏花时。","赏花不许轻攀折，只许家人戴一枝。"]},{"t":"连夕大风凌寒梅已零落殆尽三绝 其三","f":"七言绝句","c":["花开长恐赏花迟，花落何曾报我知。","人自多情春不管，强颜犹作送春诗。"]},{"t":"连夕大风凌寒梅已零落殆尽三绝 其一","f":"七言绝句","c":["枝南枝北玉初匀，夜半颠风捲作尘。","春梦都无三日好，一冬忙杀探梅人。"]},{"t":"邯郸驿","f":"七言绝句","c":["长安大道走邯郸，倚瑟佳人怅望间。","若见膻腥似今日，汉宫何用忆关山。"]},{"t":"邯郸道","f":"七言绝句","c":["薄晚霜侵使者车，邯郸阪峻且徐驱。","困来也作黄粱梦，不梦封侯梦石湖。"]},{"t":"邻山县","f":"七言绝句","c":["山顶嘘云黑似烟，修篁高柳共昏然。","鸟啼一夜劝归去，谁道东川无杜鹃。"]},{"t":"灶渚","f":"七言绝句","c":["白鱼出水卧银刀，紫笋堆盘脱锦袍。","扪腹将军犹未快，棹船西岸摘蒌蒿。"]},{"t":"京城","f":"七言绝句","c":["倚天栉栉万楼棚，圣代规模若化成。","如许金汤尚资盗，古来李绩胜长城。"]},{"t":"净光轩","f":"七言绝句","c":["翳华销尽八窗明，雨竹风泉演妙声。","身世只今高几许，北峰浑共倚阑平。"]},{"t":"净行寺傍皆圩田每为潦涨所决民岁岁兴筑患粮绝功辄不成","f":"七言绝句","c":["崩涛裂岸四三年，落日寒烟正渺然。","空腹荷锄那办此，人功未至不关天。"]},{"t":"和马少伊韵","f":"七言绝句","c":["气压伊吾一剑鸣，风生铜柱百蛮惊。","君家自有堂堂阵，我欲周旋恐曳兵。"]},{"t":"和丰驿","f":"七言绝句","c":["晚境惟于闭户宜，出门惟有病相随。","四方虽是男儿志，莫忘柯山在莒时。"]},{"t":"咏河市歌者","f":"七言绝句","c":["岂是从容唱《渭城》，个中当有不平鸣。","可怜日晏忍饥面，强作春深求友声。"]},{"t":"固城","f":"七言绝句","c":["柳棬凉罐汲泉遥，味苦仍咸似海潮。","却忆径山龙井水，一杯洗眼洞层霄。"]},{"t":"垂丝海棠","f":"七言绝句","c":["春工叶叶与丝丝，怕日嫌风不自持。","晓镜为谁妆未办，沁痕犹有泪胭脂。"]},{"t":"夜归","f":"七言绝句","c":["竹舆伊轧走长街，掠面风清醉梦回。","曲巷无声门户闭，一灯犹照酒垆开。"]},{"t":"夜坐有感","f":"七言绝句","c":["静夜家家闭户眠，满城风雨骤寒天。","号呼卖卜谁家子，想欠明朝籴米钱。"]},{"t":"夜坐听雨","f":"七言绝句","c":["四檐密密又疏疏，声到蒲团醉梦苏。","恰似秋眠天竺寺，东轩窗外听跳珠。"]},{"t":"夜雨","f":"七言绝句","c":["烛花垂穗伴空斋，心事如灰入壮怀。","老倦更阑惟熟睡，任他疏雨滴空阶。"]},{"t":"孟峤之家姬乞题扇二首 其二","f":"七言绝句","c":["翠袖凌寒弄月明，梅花影下醉三更。","一天风露谁惊觉，寂寞空杯缀落英。"]},{"t":"定兴","f":"七言绝句","c":["新城迁次少人烟，桑柘中间井径寒。","亦有染人来卖缬，淡红深碧挂长竿。"]},{"t":"宜春苑","f":"七言绝句","c":["狐冢獾蹊满路隅，行人犹作御园呼。","连昌尚有花临砌，肠断宜春寸草无。"]},{"t":"宝相花","f":"七言绝句","c":["谁把柔条夹砌栽，压枝万朵一时开。","为君也著诗收拾，题作西楼锦被堆。"]},{"t":"岩桂三首 其一","f":"七言绝句","c":["风帘疏爽月徘徊，怅望家人把酒杯。","病著幽窗知几日，瓶花两见木犀开。"]},{"t":"径山倾盖亭","f":"七言绝句","c":["万杉离立翠云幢，袅袅稀闻晚吹香。","山下行人尘扑面，谁知世界有清凉。"]},{"t":"拄笏亭晚望","f":"七言绝句","c":["林泉随处有清凉，山绕阑干客自忙。","溪雨不飞虹尚饮，乱蝉高柳满斜阳。"]},{"t":"放下庵即事三绝 其三","f":"七言绝句","c":["闭门幽僻断经过，静极兼无雀可罗。","林下故人知几个，就中老子得閒多。"]},{"t":"放下庵即事三绝 其二","f":"七言绝句","c":["病后天魔不战降，梦中千顷白鸥江。","心空境寂声尘尽，却爱秋蝇扑纸窗。"]},{"t":"放下庵即事三绝 其一","f":"七言绝句","c":["无风香篆吐长丝，书架凝尘不下帷。","鸟雀声和晴日暖，午窗扪虱坐多时。"]},{"t":"放舟风复不顺再泊马当对岸夹中马当水府即小说所载神助王勃一席清风处也戏题两绝 其一","f":"七言绝句","c":["万里江随倦客东，马当山嘴勒孤篷。","无才解赋珠帘雨，谁肯相赊一席风。"]},{"t":"放舟风复不顺再泊马当对岸夹中马当水府即小说所载神助王勃一席清风处也戏题两绝 其二","f":"七言绝句","c":["禁江上口柏山东，三日荒寒系短篷。","却忆宫亭湖里去，随人南北解分风。"]},{"t":"放鹤亭","f":"七言绝句","c":["石门关外古亭基，树老藤枯野径微。","放鹤道人今不见，故应人与鹤俱飞。"]},{"t":"昌化","f":"七言绝句","c":["翠染南山拥县门，一洲横截两溪分。","长官日永无公事，卧听滩声看白云。"]},{"t":"明日子充折赠次韵谢之","f":"七言绝句","c":["海上三山冠綵霞，六时高会雨天花。","步虚声里随风下，吹落寻常百姓家。"]},{"t":"明日复雨凉再用韵二首 其二","f":"七言绝句","c":["溅瓦排檐散万丝，颠狂风筱要扶持。","恩深到骨吾能报，急赋新凉第一诗。"]},{"t":"明日复雨凉再用韵二首 其一","f":"七言绝句","c":["东山朝日澹冥濛，一片云生万叠中。","宿雨未苏焦卷尽，又烦箕井唤雷公。"]},{"t":"明月堂","f":"七言绝句","c":["古来禅窟锁岩扃，拂子崔嵬拄杖横。","塔上佛光堂上月，莫言公案不分明。"]},{"t":"朋元不赴湖上观雪之集明日余召试玉堂见寄二绝次其韵 其二","f":"七言绝句","c":["文场宁复鬓霜宜，白玉堂前雪霁时。","不惜狂言枨忌讳，秃毫冰砚竟无奇。"]},{"t":"朋元不赴湖上观雪之集明日余召试玉堂见寄二绝次其韵 其一","f":"七言绝句","c":["雪溪清兴未渠阑，晚上西楼带月看。","公子自贪低唱酒，肯来同对玉峰寒。"]},{"t":"松醪","f":"七言绝句","c":["松风漱罢读离骚，翰墨仙翁百代豪。","一笑毡裘那办此，当年嵇阮尚餔糟。"]},{"t":"枕上","f":"七言绝句","c":["明月无声满屋梁，梦馀分影上人床。","素娥脉脉翻愁寂，付与风铃语夜长。"]},{"t":"枕上二绝效杨廷秀 其二","f":"七言绝句","c":["枕前百念忽纷然，旧学新闻总现前。","现到天明无可现，依前还我日高眠。"]},{"t":"枕上二绝效杨廷秀 其一","f":"七言绝句","c":["藤枕频移触画屏，无憀滋味厌残更。","寒鸡且道贪眠著，窗纸如何不肯明。"]},{"t":"枕上有感","f":"七言绝句","c":["窗明似月晓光新，被煖如薰睡息匀。","冲雨贩夫墙外过，故应嗤我是何人。"]},{"t":"枕上闻蒲饼焦","f":"七言绝句","c":["晓寒燕雀噤春阴，珍重清簧度好音。","窗色熹微欹枕听，梦成舟舣竹溪深。"]},{"t":"枫桥","f":"七言绝句","c":["朱门白壁枕弯流，桃李无言满屋头。","墙上浮图路傍堠，送人南北管离愁。"]},{"t":"泊衡州","f":"七言绝句","c":["客里仍哦对雨吟，夜来星月晓还阴。","空江十日无春事，船到衡阳柳色深。"]},{"t":"泸州南定楼","f":"七言绝句","c":["归艎东下兴悠哉，小住危阑把一杯。","楼下沄沄内江水，明朝同入大江来。"]},{"t":"牧马山道中","f":"七言绝句","c":["土桥茅屋两三家，竹里鸣泉漱白沙。","春色恼人无畔岸，乱飘风袖拂梅花。"]},{"t":"罗江","f":"七言绝句","c":["岭北初程分外贪，惊心犹自怯晴岚。","如何花木湘江上，也有黄茅似岭南。"]},{"t":"耶律侍郎","f":"七言绝句","c":["乍见华书眼似獐，低头惭愧紫荷囊。","人间无事无奇对，伏猎今成两侍郎。"]},{"t":"育王方丈","f":"七言绝句","c":["窗纸悲嘶万壑风，石梁飞涧倒枯松。","殷勤昨夜三更雨，添作投渊雪色龙。"]},{"t":"育王望海亭","f":"七言绝句","c":["海云晻霭日茏葱，案指光中万象空。","想见蓬莱西望眼，也应知我立长风。"]},{"t":"范氏庄园","f":"七言绝句","c":["夕阳尘土涨郊墟，六六峰头梦觉馀。","竹色唤人来下马，乱蝉深处有图书。"]},{"t":"范阳驿","f":"七言绝句","c":["邮亭偪仄但宜冬，恰似披裘坐土空。","枕上惊回丹阙梦，屋头白塔满铃风。"]},{"t":"虎丘六绝句 其二 千人坐","f":"七言绝句","c":["听经人散藓花深，千古谁能更赏音。","只好岸巾披鹤氅，风清月白坐弹琴。"]},{"t":"虎丘六绝句 其六 方丈南窗","f":"七言绝句","c":["鼓板钟鱼彻晓喧，谁云方外事萧然。","窗间日暮寒烟重，未到斋时我正眠。"]},{"t":"虎丘六绝句 其三 白莲池","f":"七言绝句","c":["碧泓白石偃樛枝，爱水嫌风老更低。","潭影中间龙影卧，一山好处没人题。"]},{"t":"虎丘六绝句 其四 剑池","f":"七言绝句","c":["石罅泓渟剑气潜，谁将楼阁苦庄严。","只知煖热游人眼，不道苍藤翠木嫌。"]},{"t":"虎丘六绝句 其一 点头石","f":"七言绝句","c":["当年挥麈讲何经，赚得坚顽侧耳听。","我自吟诗无法说，石头莫作定盘星。"]},{"t":"虎丘六绝句 其五 致爽阁","f":"七言绝句","c":["碧嶂横陈似断鳌，画阑相对两雄豪。","东轩只有云千顷，不似西山爽气高。"]},{"t":"虎丘新复古石井泉太守沈虞卿舍人劝农过之为赋三绝谨次韵 其三","f":"七言绝句","c":["传闻公作新亭好，先报侬家拄杖知。","便拟挈瓶来煮茗，绕阑干角遍寻诗。"]},{"t":"虎丘新复古石井泉太守沈虞卿舍人劝农过之为赋三绝谨次韵 其一","f":"七言绝句","c":["劝耕堂上醉高年，和气春风共蔼然。","大士亦修随喜供，夜来古井跃新泉。"]},{"t":"虎丘新复古石井泉太守沈虞卿舍人劝农过之为赋三绝谨次韵 其二","f":"七言绝句","c":["落纸云烟堕翠峦，一泓潭月斗清寒。","凤凰池上挥毫手，却掬山泉淬笔端。"]},{"t":"虎溪","f":"七言绝句","c":["水本无心作浪波，经行偶与石相磨。","不须更问桥安否，唤取于菟载我过。"]},{"t":"郊外阅骁骑剪柳","f":"七言绝句","c":["千骑同瞻白羽挥，惊尘一鬨响金鞿。","不知掣电弯弓过，但觉柳梢随箭飞。"]},{"t":"采莲三首 其一","f":"七言绝句","c":["溪头风迅怯单衣，两桨凌波去似飞。","折得蘋花双叶子，绿鬟撩乱带香归。"]},{"t":"采莲三首 其二","f":"七言绝句","c":["藕花深处好徘徊，不奈华筵苦见催。","记取南泾茭叶露，明明风熟更重来。"]},{"t":"采莲三首 其三","f":"七言绝句","c":["柔橹无声坐钓鱼，浪花飞点翠罗裾。","空江日暮无来客，肠断三湘一纸书。"]},{"t":"金氏庵","f":"七言绝句","c":["醉墨题窗侧暮鸦，蔓藤缘壁走青蛇。","春深有燕捎飞蝶，日暮无人扫落花。"]},{"t":"金水河","f":"七言绝句","c":["菜市桥西一水环，宫墙依旧俯清湾。","谁怜磊磊河中石，曾上君王万岁山。"]},{"t":"金沙","f":"七言绝句","c":["庄严福地守灵仙，不为人閒计子钱。","一掬斓斑光照眼，路傍馋隶枉流涎。"]},{"t":"钓台","f":"七言绝句","c":["久矣心空客路埃，兹行端为主恩来。","杜陵诗是吾诗句，卧病岂登江上台。"]},{"t":"钓台","f":"七言绝句","c":["山林朝市两尘埃，邂逅人生有往来。","各向此心安处住，钓台无意压云台。"]},{"t":"雨再作政妨海棠","f":"七言绝句","c":["漂红湿紫满莓苔，泼墨浓云尚送雷。","风雨岂无他日再，何须随却海棠来。"]},{"t":"雨后东郭排岸司申梅开方及三分戏书小绝令一面开燕","f":"七言绝句","c":["雨入南枝玉蕊皴，合江云冷冻芳尘。","司花好事相邀勒，不著笙歌不肯春。"]},{"t":"雨凉二首呈宗伟 其一","f":"七言绝句","c":["谁扶病客起龙钟，恩在盆倾一雨中。","问讯九关何路到，拟笺欢喜谢天公。"]},{"t":"雨凉二首呈宗伟 其二","f":"七言绝句","c":["惊雷隐地送凉飔，起舞看山不自持。","说与骚人须早计，片云催雨雨催诗。"]},{"t":"临平道中","f":"七言绝句","c":["烟雨桃花夹岸栽，低低浑欲傍船来。","石湖有此红千叶，前日春寒总未开。"]},{"t":"临洺镇","f":"七言绝句","c":["竟日霜寒暮解围，融融桑柘染斜晖。","北人争劝临洺酒，云有棚头得兔归。"]},{"t":"南塘冬夜倡和","f":"七言律诗","c":["燃萁烘煖夜窗幽，时有新诗趣倡酬。","为问灞桥风雪里，何如田舍火炉头。","寒釭欲暗吟方苦，冻笔难驱字更遒。","绝笑儿痴生活淡，略无岁晚稻粱谋。"]},{"t":"复用韵记昨日坐中剧谈及赵家琵琶之妙呈王正之提刑二绝 其一","f":"七言绝句","c":["病来六结总龟藏，不用浓薰戒定香。","花下酒边非我事，但馀消瘦是东阳。"]},{"t":"复用韵记昨日坐中剧谈及赵家琵琶之妙呈王正之提刑二绝 其二","f":"七言绝句","c":["曹穆新声和者稀，如今妙手属天支。","转关濩索都传得，想见飞凰舞绿丝。"]},{"t":"客舍","f":"七言绝句","c":["毂击肩摩锦绣堆，朝声汹汹暮声催。","忽然忆起长桥路，天镜无边白鸟回。"]},{"t":"宣化道中","f":"七言绝句","c":["瘦草萧疏已似秋，盘陀山骨束江流。","两崖若不顽如铁，争得狂澜拍岸休。"]},{"t":"宣德楼","f":"七言绝句","c":["峣阙丛霄旧玉京，御床忽有犬羊鸣。","他年若作清宫使，不挽天河洗不清。"]},{"t":"将赴建康出城","f":"七言绝句","c":["牒诉缤纷塞瓮天，经年痴坐两三椽。","出门纳纳乾坤大，依旧青山绕画船。"]},{"t":"扁鹊墓","f":"七言绝句","c":["活人绝技古今无，名下从教世俗趋。","坟土尚堪充药饵，莫嗔医者例多卢。"]},{"t":"施进之追路出严关且写予真戏题其上","f":"七言绝句","c":["唤渡牂牁瘴水滨，严关关外又逢春。","神仙富贵俱何在，且作全家出岭人。"]},{"t":"春日三首 其三","f":"七言绝句","c":["双鲤无书直万金，画桥新绿一篙深。","青蘋白芷皆愁思，不独江枫动客心。"]},{"t":"春日三首 其二","f":"七言绝句","c":["西窗一雨又斜晖，睡起薰笼换夹衣。","莫放珠帘遮洞户，从教燕子作双飞。"]},{"t":"春日三首 其一","f":"七言绝句","c":["药栏花暖小猧眠，雪白晴云水碧天。","煮酒青梅寒食过，夕阳庭院锁鞦韆。"]},{"t":"春困二绝 其二","f":"七言绝句","c":["诺惺庵里呼春困，特地回头著耳听。","若解昏昏安稳睡，主翁方始是惺惺。"]},{"t":"春困二绝 其一","f":"七言绝句","c":["綵花生菜又新年，节物人情已可怜。","不待春来呼我困，四时何日不堪眠。"]},{"t":"春怀","f":"七言绝句","c":["柳颦梅笑各相恼，诗债棋雠俱见寻。","莫道幽居无一事，春来风物总关心。"]},{"t":"春来风雨无一日好晴因赋瓶花二绝 其二","f":"七言绝句","c":["酒冷花寒无好怀，柴荆终日为谁开。","三分春色三分雨，疋似东风本不来。"]},{"t":"春来风雨无一日好晴因赋瓶花二绝 其一","f":"七言绝句","c":["满插瓶花罢出游，莫将攀折为花愁。","不知烛照香薰看，何似风吹雨打休。"]},{"t":"春晚三首 其二","f":"七言绝句","c":["客去钩窗咏小诗，游丝撩乱柳花稀。","微风尽日吹芳草，蝴蝶双双贴地飞。"]},{"t":"春晚三首 其三","f":"七言绝句","c":["夕阳槐影上帘钩，一枕清风梦昔游。","梦见钱塘春尽处，碧桃花谢水西流。"]},{"t":"春晚三首 其一","f":"七言绝句","c":["阴阴垂柳闭朱门，一曲阑干一断魂。","手把青梅春已去，满城风雨怕黄昏。"]},{"t":"春晚初出西楼","f":"七言绝句","c":["试倚枯藤似籋云，堂阶微步小逡巡。","忽逢岩桂新抽叶，屈指黄紬睡一春。"]},{"t":"春晚即事","f":"七言绝句","c":["屋头清樾暗荆扉，紫葚斓斑翠荚肥。","春晚轩窗人独困，日长篱落燕双飞。"]},{"t":"春晚偶题","f":"七言绝句","c":["寂寥春事冷于秋，雨打风吹断送休。","点检梨花成一梦，蘸红新绿满枝头。"]},{"t":"昱岭","f":"七言绝句","c":["竹舆摇兀走婆娑，石滑泥融侧足过。","昱岭不高人已困，晚登新岭奈君何。"]},{"t":"柏乡","f":"七言绝句","c":["贯生名压汉公卿，自古逢雠不反兵。","仇虏滔天无敢动，柏乡空溷迫人名。"]},{"t":"柏林院","f":"七言绝句","c":["胡来胡现劫灰深，风鼓三灾海印沈。","急过当年无佛处，庭前空有柏森森。"]},{"t":"柳公亭","f":"七言绝句","c":["主人敬客有馀情，催唤绳床坐柳亭。","曲水流觞非故物，马鞍山色旧青青。"]},{"t":"泉亭","f":"七言绝句","c":["收拾风烟锁翠微，乱山穷处结岩扉。","青天不尽鸟飞尽，吴楚川原似衲衣。"]},{"t":"相州","f":"七言绝句","c":["秃巾髽髻老扶车，茹痛含辛说乱华。","赖有乡人聊刷耻，魏公元是鲁东家。"]},{"t":"相国寺","f":"七言绝句","c":["倾檐缺吻护奎文，金碧浮图暗古尘。","闻说今朝恰开寺，羊裘狼帽趁时新。"]},{"t":"秋日二绝 其一","f":"七言绝句","c":["碧芦青柳不宜霜，染作沧洲一带黄。","莫把江山誇北客，冷云寒水更荒凉。"]},{"t":"秋日二绝 其二","f":"七言绝句","c":["新秋病骨顿成衰，不度溪桥半月来。","无事闭门非左计，饶渠屐齿上青苔。"]},{"t":"四时田园杂兴六十首 冬日十二绝 其四十九","f":"七言绝句","c":["斜日低山片月高，睡馀行药绕江郊。","霜风扫尽千林叶，閒倚筇枝数鹳巢。"]},{"t":"四时田园杂兴六十首 其五十三","f":"七言绝句","c":["乾高寅缺筑牛宫，卮酒豚蹄酹土公。","牯牸无瘟犊儿长，明年添种越城东。"]},{"t":"四时田园杂兴六十首 其五十","f":"七言绝句","c":["炙背檐前日似烘，煖醺醺后困蒙蒙。","过门走马何官职，侧帽笼鞭战北风。"]},{"t":"四时田园杂兴六十首 其五十七","f":"七言绝句","c":["煮酒春前腊后蒸，一年长飨瓮头清。","廛居何似山居乐，秫米新来禁入城。"]},{"t":"四时田园杂兴六十首 其五十五","f":"七言绝句","c":["拨雪挑来踏地菘，味如蜜藕更肥醲。","朱门肉食无风味，只作寻常菜把供。"]},{"t":"四时田园杂兴六十首 其五十四","f":"七言绝句","c":["放船閒看雪山晴，风定奇寒晚更凝。","坐听一篙珠玉碎，不知湖面已成冰。"]},{"t":"四时田园杂兴六十首 其五十二","f":"七言绝句","c":["松节然膏当烛笼，凝烟如墨暗房栊。","晚来拭净南窗纸，便觉斜阳一倍红。"]},{"t":"四时田园杂兴六十首 其五十九","f":"七言绝句","c":["探梅公子款柴门，枝北枝南总未春。","忽见小桃红似锦，却疑侬是武陵人。"]},{"t":"四时田园杂兴六十首 其五十一","f":"七言绝句","c":["屋上添高一把茅，密泥房壁似僧寮。","从教屋外阴风吼，卧听篱头响玉箫。"]},{"t":"四时田园杂兴六十首 其六十","f":"七言绝句","c":["村巷冬年见俗情，邻翁讲礼拜柴荆。","长衫布缕如霜雪，云是家机自织成。"]},{"t":"四时田园杂兴六十首 其五十六","f":"七言绝句","c":["榾柮无烟雪夜长，地炉煨酒煖如汤。","莫嗔老妇无盘饤，笑指灰中芋栗香。"]},{"t":"四时田园杂兴六十首 其五十八","f":"七言绝句","c":["黄纸蠲租白纸催，皂衣旁午下乡来。","长官头脑冬烘甚，乞汝青钱买酒回。"]},{"t":"秋前三日大雨","f":"七言绝句","c":["暑残堪喜亦堪憎，恰似沙场喋血兵。","纵有背城馀烬在，能禁几度泻檐声。"]},{"t":"种竹了题爱山亭","f":"七言绝句","c":["洒扫宣华舍此君，烟中月下绿生尘。","他年叶叶清风满，莫忘今年借宅人。"]},{"t":"科桑","f":"七言绝句","c":["斧斤留得万枯株，独速槎牙立暝途。","饱尽春蚕收罢茧，更殚馀力付樵苏。"]},{"t":"秭归郡圃绝句二首 其二","f":"七言绝句","c":["孤城偪仄复偪仄，前山后山青欲来。","市声萧条衙鼓静，惟有叱滩喧万雷。"]},{"t":"秭归郡圃绝句二首 其一","f":"七言绝句","c":["花竹萧骚小圃畦，官居翻似隐沦栖。","巴山四合秋阳满，杜宇黄鹂相对啼。"]},{"t":"羑里城","f":"七言绝句","c":["陵谷迁移尚故墟，天盈商罪未蠲除。","古今行客同嗤骂，何止三篇泰誓书。"]},{"t":"胡孙梯","f":"七言绝句","c":["木磴鳞鳞滑带泥，微生欹侧寄枯藜。","胡孙愁处我犹过，个里如今幸有梯。"]},{"t":"胥口","f":"七言绝句","c":["扁舟拍浪信西东，何处孤帆万里风。","一雨快晴云放树，两山中断水粘空。"]},{"t":"草虫扇","f":"七言绝句","c":["莫嫌络纬股鸣悲，解向寒窗促晓机。","海眼多花无藉在，颠狂只待学于飞。"]},{"t":"赵州石桥","f":"七言绝句","c":["石色如霜铁色新，洨河南北尚通津。","不因再度皇华使，谁洗奚车塞马尘。"]},{"t":"赵故城","f":"七言绝句","c":["金石笙篁绝代无，鼪鼯藜藿正乘除。","园翁但爱城泥暖，侵早锄霜种晚蔬。"]},{"t":"送刘唐卿户曹擢第西归六首 其六","f":"七言绝句","c":["四海西州旧故多，烦君问讯各如何。","心期本自无南北，万里天波一月波。"]},{"t":"送刘唐卿户曹擢第西归六首 其五","f":"七言绝句","c":["我识岷峨最上头，当年脚力与云浮。","两山父老如相问，一席三椽正卧游。"]},{"t":"送刘唐卿户曹擢第西归六首 其三","f":"七言绝句","c":["槐黄灯火困豪英，此去书窗得此生。","学力根深方蒂固，功名水到自渠成。"]},{"t":"送刘唐卿户曹擢第西归六首 其二","f":"七言绝句","c":["学道何关紫与青，发身聊假佛名经。","归来解尽程书缚，千古文章似建瓴。"]},{"t":"送刘唐卿户曹擢第西归六首 其四","f":"七言绝句","c":["中年亲友惜分离，况我身兼老病衰。","馀景庶几犹及见，登瀛召客过门时。"]},{"t":"送刘唐卿户曹擢第西归六首 其一","f":"七言绝句","c":["摩挲汉柱怆分襟，邂逅吴船喜盍簪。","别久十年知几梦，情亲万里只初心。"]},{"t":"送同年万元亨知阶州 其二","f":"七言绝句","c":["路入南山旧汉畿，油油清渭照牙旗。","古来百战功名地，正是鸡鸣起舞时。"]},{"t":"送同年万元亨知阶州 其三","f":"七言绝句","c":["十年关陇困科输，圣德如天尽扫除。","临遣中和二千石，好乘春日下宽书。"]},{"t":"送同年万元亨知阶州 其一","f":"七言绝句","c":["老我曾颁万里春，怜君飞棹也浮秦。","当年千佛名经里，又见西游第二人。"]},{"t":"送许耀卿监丞同年赴静江倅四绝 其一","f":"七言绝句","c":["南国春深雁欲回，湘江花浪一帆开。","知君不为骖鸾去，直为渊明五斗来。"]},{"t":"送许耀卿监丞同年赴静江倅四绝 其三","f":"七言绝句","c":["雁塔交亲比断金，故人岁晚更情深。","只今不隔同年面，想见青云异日心。"]},{"t":"送许耀卿监丞同年赴静江倅四绝 其四","f":"七言绝句","c":["官涂真有上竿鱼，玉笋翻乘别驾车。","闻道留行有公论，从今日日看除书。"]},{"t":"送寿老往云间行化","f":"七言绝句","c":["天平船子过华亭，舍卫城中次第行。","留取钵盂归院洗，东岩新出一泉清。"]},{"t":"送举老归庐山","f":"七言绝句","c":["二千里往回似梦，四十年今昔如浮。","去矣莫久留桑下，归欤来共煨芋头。"]},{"t":"送琴客许扬归永嘉","f":"七言绝句","c":["乌帽休冲九陌埃，瘦藤定约到秋回。","龙湫雁荡经行处，断取松风万壑来。"]},{"t":"送端言","f":"七言绝句","c":["东君留恋一分春，蜂蝶阑珊燕子新。","桃李无情空绿径，市桥杨柳送行人。"]},{"t":"重阳不见菊二绝 其一","f":"七言绝句","c":["节物今年事事迟，小春全未到东篱。","可怜短发空欹帽，欠了黄花一两枝。"]},{"t":"重阳不见菊二绝 其二","f":"七言绝句","c":["冷蕊萧疏蝶懒飞，商量何日是花时。","重阳过后开无害，只恐先生不赋诗。"]},{"t":"重阳后菊花二首 其二","f":"七言绝句","c":["过了登高菊尚新，酒徒诗客断知闻。","恰如退士垂车后，势利交亲不到门。"]},{"t":"重阳后菊花二首 其一","f":"七言绝句","c":["寂莫东篱湿露华，依前金靥照泥沙。","世情儿女无高韵，只看重阳一日花。"]},{"t":"重送文处厚因寄蜀父老三首 其三","f":"七言绝句","c":["灌口江源不断流，峨眉山月几番秋。","江山好处吾能记，为问江山记客否。"]},{"t":"重送文处厚因寄蜀父老三首 其二","f":"七言绝句","c":["下峡东归十五年，因君话旧意茫然。","烦将远道悠悠梦，直到天西暑雪边。"]},{"t":"重送文处厚因寄蜀父老三首 其一","f":"七言绝句","c":["江上连樯叠鼓行，不争微利即争名。","算来无似君潇洒，来往空船载月明。"]},{"t":"钟山阁上望雨","f":"七言绝句","c":["天阔山长雨似烟，忽然飞去暗平川。","粳禾未实籼禾瘦，不用廉纤便霈然。"]},{"t":"闻石湖海棠盛开亟携家过之三绝 其三","f":"七言绝句","c":["低花妨帽小携筇，深浅胭脂一万重。","不用高烧银烛照，煖云烘日正春浓。"]},{"t":"闻石湖海棠盛开亟携家过之三绝 其二","f":"七言绝句","c":["家人扶上锦城头，蜂蝶团中烂熳游。","报答春光须小醉，红云洞里按伊州。"]},{"t":"闻石湖海棠盛开亟携家过之三绝 其一","f":"七言绝句","c":["东风花信十分开，细意留连待我来。","开过十分风不动，更无一片点苍苔。"]},{"t":"闻春远牡丹盛开","f":"七言绝句","c":["东轩闻道有花开，痴坐三椽首谩回。","纵得好晴犹懒看，那堪风雨揭天来。"]},{"t":"除夜前二日夜雨","f":"七言绝句","c":["雪不成花夜雨来，垄头一洗定无埃。","小童却怕溪桥滑，明日先生合探梅。"]},{"t":"香山","f":"七言绝句","c":["抖擞轩裳一鬨尘，任教空翠滴乌巾。","老身已到篮舆上，处处青山是故人。"]},{"t":"香山","f":"七言绝句","c":["采香径里木兰舟，嚼蕊吹芳烂熳游。","落日青山都好在，桑间荞麦满芳洲。"]},{"t":"唐山","f":"七言绝句","c":["勋唐遗德照清湾，百圣闻风不敢班。","何物苦寒胡地鬼，二名犹敢废尧山。"]},{"t":"唐懿仲诸公见过小饮凌寒残梅之下二绝 其二","f":"七言绝句","c":["问人何处是花蹊，香玉匀铺不见泥。","莫怪山翁行步涩，更无空处著枯藜。"]},{"t":"唐懿仲诸公见过小饮凌寒残梅之下二绝 其一","f":"七言绝句","c":["春风动是隔年期，更对残花把一卮。","少待和烟和月看，依稀犹似未开时。"]},{"t":"壶春堂","f":"七言绝句","c":["松漠丹成去不归，龙髯无复有攀时。","芳园留得觚棱在，长与都人作泪垂。"]},{"t":"四时田园杂兴六十首 其二十七","f":"七言绝句","c":["二麦俱秋斗百钱，田家唤作小丰年。","饼炉饭甑无饥色，接到西风熟稻天。"]},{"t":"四时田园杂兴六十首 其二十六","f":"七言绝句","c":["五月江吴麦秀寒，移秧披絮尚衣单。","稻根科斗行如块，田水今年一尺宽。"]},{"t":"四时田园杂兴六十首 其三十","f":"七言绝句","c":["下田戽水出江流，高垄翻江逆上沟。","地势不齐人力尽，丁男长在踏车头。"]},{"t":"四时田园杂兴六十首 其三十二","f":"七言绝句","c":["槐叶初匀日气凉，葱葱鼠耳翠成双。","三公只得三株看，閒客清阴满北窗。"]},{"t":"四时田园杂兴六十首 其二十九","f":"七言绝句","c":["小妇连宵上绢机，大耆催税急于飞。","今年幸甚蚕桑熟，留得黄丝织夏衣。"]},{"t":"四时田园杂兴六十首 其三十四","f":"七言绝句","c":["千顷芙蕖放棹嬉，花深迷路晚忘归。","家人暗识船行处，时有惊忙小鸭飞。"]},{"t":"四时田园杂兴六十首 其三十六","f":"七言绝句","c":["蜩螗千万沸斜阳，蛙黾无边聒夜长。","不把痴聋相对治，梦魂争得到藜床。"]},{"t":"四时田园杂兴六十首 其四十二","f":"七言绝句","c":["秋来只怕雨垂垂，甲子无云万事宜。","穫稻毕工随晒谷，直须晴到入仓时。"]},{"t":"四时田园杂兴六十首 其三十三","f":"七言绝句","c":["黄尘行客汗如浆，少住侬家漱井香。","借与门前磐石坐，柳阴亭午正风凉。"]},{"t":"四时田园杂兴六十首 其三十八","f":"七言绝句","c":["朱门巧夕沸欢声，田舍黄昏静掩扃。","男解牵牛女能织，不须徼福渡河星。"]},{"t":"四时田园杂兴六十首 其四十一","f":"七言绝句","c":["垂成穑事苦艰难，忌雨嫌风更怯寒。","笺诉天公休掠剩，半偿私债半输官。"]},{"t":"四时田园杂兴六十首 其四十三","f":"七言绝句","c":["中秋全景属潜夫，棹入空明看太湖。","身外水天银一色，城中有此月明无。"]},{"t":"四时田园杂兴六十首 其三十九","f":"七言绝句","c":["橘蠹如蚕入化机，枝间垂茧似蓑衣。","忽然蜕作多花蝶，翅粉才乾便学飞。"]},{"t":"四时田园杂兴六十首 其二十八","f":"七言绝句","c":["百沸缲汤雪涌波，缲车嘈囋雨鸣蓑。","桑姑盆手交相贺，绵茧无多丝茧多。"]},{"t":"四时田园杂兴六十首 其四十","f":"七言绝句","c":["静看檐蛛结网低，无端妨碍小虫飞。","蜻蜓倒挂蜂儿窘，催唤山童为解围。"]},{"t":"四时田园杂兴六十首 秋日十二绝 其三十七","f":"七言绝句","c":["杞菊垂珠滴露红，两蛩相应语莎丛。","虫丝罥尽黄葵叶，寂历高花侧晚风。"]},{"t":"宴坐庵四首 其三","f":"七言绝句","c":["粥鱼吼罢鼓逢逢，卧听饥鼯上晓釭。","一点斜光明纸帐，悟知檐雀已穿窗。"]},{"t":"宴坐庵四首 其一","f":"七言绝句","c":["油灯已暗忽微明，石鼎将乾尚有声。","衲被蒙头笼两袖，藜床无地著功名。"]},{"t":"宴坐庵四首 其四","f":"七言绝句","c":["跏趺合眼是无何，静里惟闻鸟雀多。","俗客叩门称问字，又烦居士起穿靴。"]},{"t":"宴坐庵四首 其二","f":"七言绝句","c":["五更风竹闹轩窗，听作江船浪隐床。","枕上翻身寻断梦，故人待漏满靴霜。"]},{"t":"晒茧","f":"七言绝句","c":["隔篱处处雪成窝，牢闭柴荆断客过。","叶贵蚕饥危欲死，尚能包裹一丝窠。"]},{"t":"晓行","f":"七言绝句","c":["篝灯驿吏唤人行，寥落星河向五更。","马上谁惊千里梦，石头冈下小车声。"]},{"t":"戏书二首 其二","f":"七言绝句","c":["群儿欺老少陵穷，口燥唇乾发漫冲。","颠沛须臾犹执礼，古来惟有一高共。"]},{"t":"晓泊横塘","f":"七言绝句","c":["短梦难成却易惊，披衣起漱玉池清。","遥知中夜南风转，汹汹前村草市声。"]},{"t":"晓起","f":"七言绝句","c":["窗明惊起倒裳衣，铃索频摇定怪迟。","即入簿书丛里去，少留欹枕听黄鹂。"]},{"t":"栾城","f":"七言绝句","c":["颓垣破屋古城边，客传萧寒爨不烟。","明府牙绯危受杖，栾城风物一凄然。"]},{"t":"桃花坛下望龟峰","f":"七言绝句","c":["石坛无土谩嵚岑，何自能生小柏林。","拟擘蛤蜊龟壳上，病来不杀懒登临。"]},{"t":"案上梅花二首 其二","f":"七言绝句","c":["地炉火煖日烘窗，一夜花须半吐黄。","鼻观圆通熏百和，博山三夕罢烧香。"]},{"t":"案上梅花二首 其一","f":"七言绝句","c":["南坡玉雪万花团，旧约东风载酒看。","冷落铜瓶一枝亚，今年天女亦酸寒。"]},{"t":"桐川郡圃梅极盛皆围抱高木浙中无有","f":"七言绝句","c":["家住丹枫白苇林，横枝一笑万黄金。","玉溪园里逢千树，还尽春风未足心。"]},{"t":"桐庐","f":"七言绝句","c":["湿云垂野淡疏林，十日山行九日阴。","梅子弄黄应要雨，不知客路已泥深。"]},{"t":"桐庐江中初打桨","f":"七言绝句","c":["二十年前鬓未斑，下滩归路落潮乾。","如今衰雪三千丈，却趁潮平再上滩。"]},{"t":"殊不恶斋秋晚閒吟五绝 其二","f":"七言绝句","c":["旁若无人鼠饮砚，麾之不去蝇登盘。","天凉睡起枕痕煖，日晚慵来香字寒。"]},{"t":"殊不恶斋秋晚閒吟五绝 其五","f":"七言绝句","c":["中秋昨已等閒过，重九今还如梦来。","霜鬓数茎羞堕帻，黄花三度笑空杯。"]},{"t":"浙江小矶春日","f":"七言绝句","c":["客里无人共一杯，故园桃李为谁开。","春潮不管天涯恨，更捲西兴暮雨来。"]},{"t":"浣花戏题争标者","f":"七言绝句","c":["凌波一剧便捐生，得失何曾较重轻。","蜗角虚名人尚爱，锦标安得笑渠争。"]},{"t":"浴罢","f":"七言绝句","c":["西城落日半轮明，浴罢衣裳一倍轻。","玉宇风来归鸟急，火云销尽绿云生。"]},{"t":"海棠欲开雨作","f":"七言绝句","c":["春睡花枝醉梦回，安排银烛照妆台。","苍茫不解东风意，政用此时吹雨来。"]},{"t":"留侯庙","f":"七言绝句","c":["功成轻举信良谋，心与鸱夷共一舟。","吕媪区区无鸟喙，先生轻负赤松游。"]},{"t":"病中三偈 其二","f":"七言绝句","c":["一交销取万黄金，将病求医在用心。","化尽此身成药树，不妨栽得病根深。"]},{"t":"病中三偈 其三","f":"七言绝句","c":["莫把无言绝病根，病根深处是无言。","丈夫解却维摩缚，八字轰开不二门。"]},{"t":"病中绝句八首 其八","f":"七言绝句","c":["晴色先从喜鹊知，斜阳一抹照天西。","竹鸡何物能无赖，如许泥深更苦啼。"]},{"t":"病中绝句八首 其三","f":"七言绝句","c":["石鼎飕飕夜煮汤，乱拖芝朮斗温凉。","化儿幻我知何用，祗与人间试药方。"]},{"t":"病中绝句八首 其四","f":"七言绝句","c":["病中心境两俱降，犹忆江湖白鸟双。","一夜雨声鸣纸瓦，听成飞雪打船窗。"]},{"t":"病中绝句八首 其七","f":"七言绝句","c":["盆倾瓴建夜翻渠，绕屋蛙声一倍粗。","想见西堂浑不睡，明朝踏湿看菖蒲。"]},{"t":"病中绝句八首 其五","f":"七言绝句","c":["檐头排溜密如帘，溪上层阴定解严。","最是看山奇绝处，白云堆絮拥青尖。"]},{"t":"病中绝句八首 其二","f":"七言绝句","c":["溽暑薰天地涌泉，弯跧避湿挂行缠。","出门斟酌无忙事，睡过黄梅细雨天。"]},{"t":"病中绝句八首 其一","f":"七言绝句","c":["空里情知不著花，逢场将病当生涯。","蒲团软暖无时节，夜听蚊雷晓听鸦。"]},{"t":"病倦不能过谷帘三峡寄题","f":"七言绝句","c":["白龙青峡紫烟炉，山北山南只半涂。","说与同来绿玉杖，他年终补卧游图。"]},{"t":"真定舞","f":"七言绝句","c":["紫袖当棚雪鬓凋，曾随广乐奏云韶。","老来未忍耆婆舞，犹倚黄钟衮六么。"]},{"t":"真瑞堂前丹桂 其二","f":"七言绝句","c":["官忙风月镇长閒，开遍香红酒尚寒。","若要与花相领略，千岩随分有阑干。"]},{"t":"真瑞堂前丹桂 其一","f":"七言绝句","c":["血色凡花太俗生，花工新意染秋英。","袍红太重鞓红浅，画不能摹句写成。"]},{"t":"秦楼","f":"七言绝句","c":["栏街看幕似春游，斑犊雕车碧画油。","奚女家人称贵主，缕金长袖倚秦楼。"]},{"t":"胭脂井三首 其三","f":"七言绝句","c":["腰支旅拒更神游，桃叶山前水自流。","三十六书都莫恨，烦将歌舞过扬州。"]},{"t":"胭脂井三首 其一","f":"七言绝句","c":["昭光殿下起楼台，拚得山河付酒杯。","春色已从金井去，月华空上石头来。"]},{"t":"衮山道中","f":"七言绝句","c":["虎啸狐鸣苦竹丛，魂惊终日走蒙茸。","松林断处前山缺，又见南湖数十峰。"]},{"t":"诺惺庵枕上","f":"七言绝句","c":["噩梦惊回晓枕寒，青灯犹照药炉边。","纸窗弄色如胧月，又了浮生一夜眠。"]},{"t":"读史三首 其一","f":"七言绝句","c":["百岁亏成费械机，乌鸢蝼蚁竟同归。","一檠灯火挑明灭，两眼昏花管是非。"]},{"t":"读史三首 其三","f":"七言绝句","c":["镂冰琢雪战毛氂，画饼声名骨朽时。","汗简书青已儿戏，岘山辛苦更沉碑。"]},{"t":"读史三首 其二","f":"七言绝句","c":["堂堂列传冠元功，纸上浮云万事空。","我若材堪当世用，他年应只似诸公。"]},{"t":"读甘露遗事二首 其二","f":"七言绝句","c":["上林辇路草青青，谁向凭高识圣情。","谩展东封图画看，不如醲酒乱平生。"]},{"t":"读甘露遗事二首 其一","f":"七言绝句","c":["神理人情本不同，绝怜鼠辈倖元功。","天公盍假毛氂助，成败都悬反掌中。"]},{"t":"酒边二绝 其二","f":"七言绝句","c":["日长绣倦酒红潮，閒束罗巾理六么。","新样筑毬花十八，丁宁小玉慢吹箫。"]},{"t":"酒边二绝 其一","f":"七言绝句","c":["团扇香中袅袅风，断肠声里看羞红。","不须过处催乾盏，听彻歌头盏自空。"]},{"t":"铁锡","f":"七言绝句","c":["八环流韵宝枝鸣，古铁无花紫翠明。","莫遣閒人容易振，泉飞石落鬼寰惊。"]},{"t":"高景山夜归","f":"七言绝句","c":["伊轧篮舆草露间，夜凉月暗走孱颜。","忽逢陂水明如镜，照见沉沉倒景山。"]},{"t":"高景庵读旧题有感","f":"七言绝句","c":["莓苔风雨旧诗留，十七年前鬓未秋。","岩桂拂云篁竹拱，树犹如此一搔头。"]},{"t":"高楼曲","f":"五言绝句","c":["岁暮天涯客，黄昏蝙蝠飞。","高楼人不到，小雨怯单衣。"]},{"t":"偃月泉","f":"七言绝句","c":["松风竹露午犹寒，知有龙蟠一掬悭。","我欲今年来结夏，莫扃岫幌掩云关。"]},{"t":"假十二峰","f":"七言绝句","c":["巴东三峡数巫阳，山入西陵更郁苍。","何以假为非确论，直疑溟涬弟高唐。"]},{"t":"偶书","f":"七言绝句","c":["伯劳东去燕西飞，同寄春风二月时。","可恨同时不同调，此情那得更相知。"]},{"t":"偶书","f":"七言绝句","c":["出处由人不系天，痴儿富贵更求仙。","东家就食西家宿，世事何缘得两全。"]},{"t":"偶箴","f":"七言绝句","c":["情知万法本来空，犹复将心奉八风。","逆顺境来欣戚变，咄哉谁是主人翁。"]},{"t":"偶题","f":"七言绝句","c":["檐雨初乾团扇风，夕阳芳树绿葱葱。","蕉心榴萼俱无赖，要与春衫相并红。"]},{"t":"宿东寺二首 其二","f":"七言绝句","c":["一声黄鹄夜深归，栖雀惊鸣触殿扉。","北斗半垂楼阁外，风幡浑欲上云飞。"]},{"t":"宿东寺二首 其一","f":"七言绝句","c":["淡天如水雾如尘，残雪和霜冻瓦鳞。","织女无言千古恨，素娥有意十分春。"]},{"t":"宿州","f":"七言绝句","c":["狐鸣鬼啸夜茫茫，元是官军旧战场。","土伯不能藏碧燐，三三两两照前冈。"]},{"t":"宿阊门","f":"七言绝句","c":["五更潮落水鸣船，霜送新寒到枕边。","报道雾收红日上，野翁犹盖短篷眠。"]},{"t":"寄蜀州杨道人","f":"七言绝句","c":["老来万事总萧然，犹忆西州暑雪边。","为报岷峨山水道，如今真个得归田。"]},{"t":"寄题汉中新作南楼二首 其二","f":"七言绝句","c":["甲子周天事好还，关河响动剑光寒。","秦川草木多如荠，时倚楼阑直北看。"]},{"t":"寄题汉中新作南楼二首 其一","f":"七言绝句","c":["我作筹边倚半霄，西山云雪照弓刀。","如今且说南楼胜，应共汉坛相对高。"]},{"t":"寄题石湖海棠二首 其二","f":"七言绝句","c":["老懒居家似出家，园林春色雨沾沙。","海棠尚自无心看，天女何须更散花。"]},{"t":"寄题石湖海棠二首 其一","f":"七言绝句","c":["手开芳径越城头，红锦屠苏结绮楼。","不把万枝银烛照，淡云微月替人愁。"]},{"t":"寄题西湖并送净慈显老三绝 其一","f":"七言绝句","c":["南北高峰旧往还，芒鞋踏遍两山间。","近来却被官身累，三过西湖不见山。"]},{"t":"寄题西湖并送净慈显老三绝 其三","f":"七言绝句","c":["中秋月了又黄花，卯后新醅午后茶。","别没工夫谭不二，文殊休更问毗耶。"]},{"t":"寄题西湖并送净慈显老三绝 其二","f":"七言绝句","c":["膏肓泉石痼烟霞，半世游山不著家。","老入蒲团三昧定，坐看穿膝长芦芽。"]},{"t":"寄题祝郢州白雪楼","f":"七言绝句","c":["楚望风烟倚绣楹，使君静治有高情。","袛应襦裤新翻曲，压倒当年寡和声。"]},{"t":"寄题郫县蘧仙观四楠","f":"七言绝句","c":["沉犀浦上旧仙踪，老木长春翠扫空。","敢请丹光来万里，为扶云峤驾飞鸿。"]},{"t":"寄题鹿伯可见一堂 其一","f":"七言绝句","c":["梦觉春闱俱转蓬，仙凡今隔玉霄东。","聊攀铁锁问何似，岂敢避堂邀盖公。"]},{"t":"晚步","f":"七言绝句","c":["排门帘幕夜香飘，灯火人声小市桥。","满县月明春意好，旗亭吹笛近元宵。"]},{"t":"晚步西园","f":"七言绝句","c":["料峭轻寒结晚阴，飞花院落怨春深。","吹开红紫还吹落，一种东风两样心。"]},{"t":"晚思","f":"七言绝句","c":["藓墙莎砌响幽虫，睡起翻书觉梦中。","残暑一窗风不动，秋阳入竹碎青红。"]},{"t":"四时田园杂兴六十首 其十四","f":"七言绝句","c":["湖莲旧荡藕新翻，小小荷钱没涨痕。","斟酌梅天风浪紧，更从外水种芦根。"]},{"t":"四时田园杂兴六十首 其十五","f":"七言绝句","c":["蝴蝶双双入菜花，日长无客到田家。","鸡飞过篱犬吠窦，知有行商来买茶。"]},{"t":"四时田园杂兴六十首 其十六","f":"七言绝句","c":["湔裙水满绿蘋洲，上巳微寒懒出游。","薄暮蛙声连晓闹，今年田稻十分秋。"]},{"t":"四时田园杂兴六十首 晚春十二绝 其十三","f":"七言绝句","c":["紫青莼菜卷荷香，玉雪芹芽拔薤长。","自撷溪毛充晚供，短篷风雨宿横塘。"]},{"t":"四时田园杂兴六十首 其四十八","f":"七言绝句","c":["新霜彻晓报秋深，染尽青林作缬林。","惟有橘园风景异，碧丛丛里万黄金。"]},{"t":"四时田园杂兴六十首 其四十七","f":"七言绝句","c":["细捣枨齑买鲙鱼，西风吹上四腮鲈。","雪松酥腻千丝缕，除却松江到处无。"]},{"t":"晚潮","f":"七言绝句","c":["东风吹雨晚潮生，叠鼓催船镜里行。","底事今年春涨小，去年曾与画桥平。"]},{"t":"望乡台","f":"七言绝句","c":["千山已尽一峰孤，立马行人莫疾驱。","从此蜀川平似掌，更无高处望东吴。"]},{"t":"望都","f":"七言绝句","c":["荒寺疏钟解客鞍，由山东畔白烟寒。","望都风土连唐县，翁媪排门带瘿看。"]},{"t":"题赵昌四季花图 其四 梅花山茶","f":"五言绝句","c":["月淡玉逾瘦，雪深红欲燃。","同时不同调，聊用慰衰年。"]},{"t":"梅雨五绝 其二","f":"七言绝句","c":["乙酉甲申雷雨惊，乘除却贺芒种晴。","插秧先插蚤籼稻，少忍数旬蒸米成。"]},{"t":"梦中作","f":"七言绝句","c":["漠漠人间一气平，虚无宫殿锁飞琼。","碧云万里海光动，何处书来金鹤鸣。"]},{"t":"欲雪","f":"七言绝句","c":["乌鸦撩乱舞黄云，楼上飞花已唾人。","说与江梅须早计，冯夷无赖欲争春。"]},{"t":"深溪铺中二绝追路寄呈元将仲显二使君 其一","f":"七言绝句","c":["贺州归去柳州还，分路千山与万山。","把酒故人都别尽，今朝真个出阳关。"]},{"t":"深溪铺中二绝追路寄呈元将仲显二使君 其二","f":"七言绝句","c":["祗有南风捲路尘，断无南客送车轮。","故人合在潇湘见，却向潇湘别故人。"]},{"t":"淳安","f":"七言绝句","c":["篙师叫怒破涛泷，水石如钟自击撞。","欲识人间奇险处，但从歙浦过桐江。"]},{"t":"淳熙五年四月二日直宿玉堂怀旧二绝句 其二","f":"七言绝句","c":["雪山刁斗不停挝，夜把军书敢顾家。","珍重玉堂今夜梦，静闻宫漏隔宫花。"]},{"t":"淳熙五年四月二日直宿玉堂怀旧二绝句 其一","f":"七言绝句","c":["桂海冰天老岁华，直庐重上玉皇家。","当年曾识青青鬓，惟有东墙一架花。"]},{"t":"清远店","f":"七言绝句","c":["女僮流汗逐毡軿，云在淮乡有父兄。","屠婢杀奴官不问，大书黥面罚犹轻。"]},{"t":"清音堂与赵德庄太常小饮在馀干琵琶洲傍洲以形似得名","f":"七言绝句","c":["曲浦弯环绕县青，一杯閒客两飘零。","琵琶不语苍烟暮，山水清音著意听。"]},{"t":"清湘驿送王柳州南归二绝 其一","f":"七言绝句","c":["南归北去路茫茫，不是行人也断肠。","可惜湘江春夜月，落花时节照离觞。"]},{"t":"清湘驿送王柳州南归二绝 其二","f":"七言绝句","c":["我已兼程无脚力，君犹追路有襟期。","从今月下共花下，谁复醉吟先和诗。"]},{"t":"渐水","f":"七言绝句","c":["黄流日夜向南风，道出封丘处处逢。","紫盖黄旗在湖海，故应河伯欲朝宗。"]},{"t":"琉璃河","f":"七言绝句","c":["烟林葱茜带回塘，桥眼惊人失睡乡。","健起褰帷揩病眼，琉璃河上看鸳鸯。"]},{"t":"续长恨歌七首 其三","f":"七言绝句","c":["闻道蓬壶重见时，瘦来全不耐风吹。","无端却作尘间念，已被仙官圣得知。"]},{"t":"续长恨歌七首 其六","f":"七言绝句","c":["骊山六十二高楼，突兀华清最上头。","玉羽川长湘浦暗，三郎无事更神游。"]},{"t":"续长恨歌七首 其一","f":"七言绝句","c":["金杯潋滟晓妆寒，国色天香胜牡丹。","白凤诏书来已暮，六宫铅粉半春阑。"]},{"t":"续长恨歌七首 其七","f":"七言绝句","c":["帝乡云驭若为留，八景三清好在不。","玉笛不随双鹤去，人间犹得听梁州。"]},{"t":"续长恨歌七首 其二","f":"七言绝句","c":["紫薇金屋闭春阳，石竹山花却自芳。","莫道故情无觅处，领巾犹有隔生香。"]},{"t":"续长恨歌七首 其四","f":"七言绝句","c":["别后相思梦亦难，东虚云路海漫漫。","仙凡顿隔银屏影，不似当时取次看。"]},{"t":"续长恨歌七首 其五","f":"七言绝句","c":["人似飞花去不归，兰昌宫殿几斜晖。","百年只有云容姊，留得当时旧舞衣。"]},{"t":"绿萼梅","f":"七言绝句","c":["朝罢东皇放玉鸾，霜罗薄袖绿裙单。","贪看修竹忘归路，不管人间日暮寒。"]},{"t":"菊楼","f":"七言绝句","c":["东篱秋色照疏芜，挽结高花不用扶。","净洗西风尘土面，来看金碧万浮图。"]},{"t":"野景","f":"七言绝句","c":["菰蒲声里荻花乾，鹭立江天水镜宽。","画不能成诗不到，笔端无处著荒寒。"]},{"t":"雪中苦寒戏嘲二绝 其一","f":"七言绝句","c":["冥凌分职大间关，辛苦行冬强作难。","费尽无边风与雪，劣能供得一番寒。"]},{"t":"雪中送炭与龚养正","f":"七言绝句","c":["谁与幽人煖直身，筠笼冲雪送乌薪。","烦君笑领婆欢喜，探借新年五日春。"]},{"t":"雪中闻墙外鬻鱼菜者求售之声甚苦有感三绝 其一","f":"七言绝句","c":["饭箩驱出敢偷閒，雪胫冰须惯忍寒。","岂是不能扃户坐，忍寒犹可忍饥难。"]},{"t":"雪中闻墙外鬻鱼菜者求售之声甚苦有感三绝 其三","f":"七言绝句","c":["啼号升斗抵千金，冻雀饥鸦共一音。","劳汝以生令至此，悠悠大块亦何心。"]},{"t":"雪中闻墙外鬻鱼菜者求售之声甚苦有感三绝 其二","f":"七言绝句","c":["忧渴焦山业海深，贪渠刀蜜坐成禽。","一身冒雪浑家煖，汝不能诗替汝吟。"]},{"t":"雪后苦寒","f":"七言绝句","c":["旋融檐滴冻琅玕，风力如刀刮面寒。","雪阵搅空风却软，天公知我倚阑干。"]},{"t":"雪后雨作","f":"七言绝句","c":["瑞叶飞来麦已青，更烦膏雨发欣荣。","东风不是厌滕六，却怕雪天容易晴。"]},{"t":"雪寒探梅","f":"七言绝句","c":["酸风如箭莫凭阑，冻合横枝雪未乾。","吴下得春元自晚，那堪天与十分寒。"]},{"t":"黄伯益官舍赏梅","f":"七言绝句","c":["一杯何处洗愁颜，黄法曹家玉树寒。","翠袖撚香留客看，春风都在小阑干。"]},{"t":"喜收知旧书复畏答书二绝 其一","f":"七言绝句","c":["故人寥落似晨星，珍重书来问死生。","笔意不如当日健，鬓边应也雪千茎。"]},{"t":"喜收知旧书复畏答书二绝 其二","f":"七言绝句","c":["强裁尺素答相思，两目眵昏腕力疲。","牵率老夫令至此，门前犹说报书迟。"]},{"t":"喜周妹自四明到","f":"七言绝句","c":["团栾话里老庞衰，一妹仍从海浦来。","孤苦尚馀兄弟乐，如今虽病也眉开。"]},{"t":"喜雨","f":"七言绝句","c":["昨遣长须借踏车，小池须水引鸣蛙。","今朝一雨添新涨，便合翻泥种藕花。"]},{"t":"喜雪示桂人","f":"七言绝句","c":["腊雪同云岭外稀，南人北客尽冬衣。","从今老杜诗犹信，梅片飞时雪也飞。"]},{"t":"富阳","f":"七言绝句","c":["不到江湖恰五年，歙山青绕屋头边。","富春渡口明人眼，落日孤舟浪拍天。"]},{"t":"寒夜独步中庭","f":"七言绝句","c":["忍寒索句踏霜行，刮面风来须结冰。","倦仆触屏呼不应，梅花影下一窗灯。"]},{"t":"寒雨","f":"七言绝句","c":["何事冬来雨打窗，夜声滴滴晓声淙。","若为化作漫天雪，径上孤篷钓晚江。"]},{"t":"插秧","f":"七言绝句","c":["种密移疏绿毯平，行间清浅縠纹生。","谁知细细青青草，中有丰年击壤声。"]},{"t":"斑骓","f":"七言绝句","c":["斑骓别后月纤纤，门外疏桐影画帘。","留下可怜将不去，西风吹上两眉尖。"]},{"t":"渡淮","f":"七言绝句","c":["船旗衮衮径长淮，汴口人看拨不开。","昨夜南风浪如屋，果然双节下天来。"]},{"t":"游宁国奉圣寺","f":"七言绝句","c":["松梢台殿郁高标，山转溪回一水朝。","不惜褰裳呼小渡，夜来春涨失浮桥。"]},{"t":"湘江怨","f":"五言绝句","c":["蘋芷迷烟路，莲舟忘却归。","夜寒江水黑，风雨梦如飞。"]},{"t":"湘潭","f":"七言绝句","c":["暮雨樯竿县一湾，长官立马水云间。","风吹江沫浮浮去，谁在沙头闭户閒。"]},{"t":"程助教远饯求诗","f":"七言绝句","c":["残山剩水带离亭，送客烦君远作程。","直欲明年击吴榜，白沙翠竹是柴荆。"]},{"t":"缓带轩独坐","f":"七言绝句","c":["午日烘开豆蔻苞，檐尘飞动雀争巢。","蒙蒙困眼无安处，閒送炉烟到竹梢。"]},{"t":"落鸿","f":"七言绝句","c":["落鸿声里怨关山，泪湿秋衣不肯乾。","只道一番新雨过，谁知双袖倚楼寒。"]},{"t":"谢龚养正送蕲竹杖","f":"七言绝句","c":["一声霜晓谩吹愁，八尺风漪不耐秋。","上座独超三昧地，诺惺庵里證般舟。"]},{"t":"赏海棠三绝 其三","f":"七言绝句","c":["忆向宣华夜倚阑，花光妍煖月光寒。","如今蹋飒嫌风露，且只铜瓶满插看。"]},{"t":"赏海棠三绝 其一","f":"七言绝句","c":["芳春随分到贫家，儿女多情惜岁华。","聊为海棠修故事，去年灯烛去年花。"]},{"t":"赏海棠三绝 其二","f":"七言绝句","c":["烛光花影两相宜，占断风光二月时。","但得常如妃子醉，何妨独欠少陵诗。"]},{"t":"道见蓼花","f":"七言绝句","c":["秋风袅袅露华鲜，去岁如今刺钓船。","歙县门西见红蓼，此身曾在白鸥前。"]},{"t":"销夏湾","f":"七言绝句","c":["蓼矶枫渚故离宫，一曲清涟九里宫。","纵有暑光无著处，青山环水水浮空。"]},{"t":"新荔枝四绝 其四","f":"七言绝句","c":["趠舶飞来不作难，红尘一骑笑长安。","孙郎皱玉无消息，先破潘郎玳瑁盘。"]},{"t":"新荔枝四绝 其二","f":"七言绝句","c":["海北天西两鬓蓬，闽山犹欠一枝筇。","鄞船荔子如新摘，行脚何须更雪峰。"]},{"t":"新荔枝四绝 其一","f":"七言绝句","c":["荔浦园林瘴雾中，戎州沽酒擘轻红。","五年食指无占处，何意相逢万壑东。"]},{"t":"瑞香三首 其三","f":"五言绝句","c":["一丛三百朵，细细拆浓檀。","帘幕护花气，不知窗外寒。"]},{"t":"瑞香三首 其二","f":"五言绝句","c":["紫云蹙绣被，团栾覆衣篝。","浓薰百和韵，香极却成愁。"]},{"t":"瑞香三首 其一","f":"五言绝句","c":["小槛移秀色，端来媚禅房。","道人不解饮，醺然醉天香。"]},{"t":"睡觉","f":"七言绝句","c":["寻思断梦半瞢腾，渐见天窗纸瓦明。","宿鸟噪群穿竹去，县前犹自打残更。"]},{"t":"睢水","f":"七言绝句","c":["一战填河拥汉屯，拔山意气已鲸吞。","直南即是阴陵路，兵果难将胜负论。"]},{"t":"福胜阁","f":"七言绝句","c":["翚飞五级半空翔，指点楼栏说太皇。","劫火不能侵愿力，岿然独似汉灵光。"]},{"t":"简毕叔滋觅牡丹","f":"七言绝句","c":["冷落韶光谷雨寒，一年孤负倚阑干。","欲知春色偏浓处，须向香风径里看。"]},{"t":"虞姬墓","f":"楚辞体","c":["刘项家人总可怜，英雄无策庇婵娟。","戚姬葬处君知否，不及虞兮有墓田。"]},{"t":"蜀花以状元红为第一金陵东御园紫绣毬为最","f":"七言绝句","c":["西楼第一红多叶，东苑无双紫压枝。","梦里东风忙里过，蒲团药鼎鬓成丝。"]},{"t":"跨马过练墟喜晴","f":"七言绝句","c":["稻穗初乾怕雨时，晚来蒸煖欲霏微。","西风若肯吹云尽，不惜飘飘侧帽归。"]},{"t":"酬姜尧章","f":"七言绝句","c":["鹅鹜声暗雪意豪，直前不惮夜行劳。","更能櫜鞬尊裴度，千古人知李愬高。"]},{"t":"锦亭然烛观海棠","f":"七言绝句","c":["银烛光中万绮霞，醉红堆上缺蟾斜。","从今胜绝西园夜，压尽锦官城里花。"]},{"t":"雷万春墓","f":"七言绝句","c":["九陨元身不陨名，言言千载气如生。","欲知忠信行蛮貊，过墓胡儿下马行。"]},{"t":"雷雨邻舍起龙","f":"七言绝句","c":["雨工避事欲蟠泥，帝遣丰隆执以归。","连鼓一声人失箸，不知挂壁几梭飞。"]},{"t":"墙外卖药者九年无一日不过吟唱之声甚适雪中呼问之家有十口一日不出即饥寒矣","f":"七言绝句","c":["十口啼号责望深，宁容安稳坐毡针。","长鸣大咤欺风雪，不是甘心是苦心。"]},{"t":"碧瓦","f":"七言绝句","c":["碧瓦楼头绣幕遮，赤栏桥外绿溪斜。","无风杨柳漫天絮，不雨棠梨满地花。"]},{"t":"缥缈峰","f":"七言绝句","c":["满载清閒一棹孤，长风相送入仙都。","莫愁怀抱无消豁，缥缈峰头望太湖。"]},{"t":"翠楼","f":"七言绝句","c":["连衽成帷迓汉官，翠楼沽酒满城欢。","白头翁媪相扶拜，垂老从今几度看。"]},{"t":"蔺相如墓","f":"七言绝句","c":["玉节经行虏障深，马头酾酒奠疏林。","兹行璧重身如叶，天日应临慕蔺心。"]},{"t":"嘲风","f":"七言绝句","c":["纷红骇绿骤飘零，痴騃封姨没性灵。","报道海棠方熟睡，也须留眼为渠青。"]},{"t":"嘲里人新婚","f":"七言绝句","c":["冷艳頩容一笑开，休将鸾扇更徘徊。","箜篌细写归舟字，彷佛游仙梦里来。"]},{"t":"横塘","f":"七言绝句","c":["南浦春来绿一川，石桥朱塔两依然。","年年送客横塘路，细雨垂杨系画船。"]},{"t":"题蜀果图四首 其二 樱桃","f":"五言绝句","c":["火齐宝璎珞，垂于绿茧丝。","幽禽都未觉，和露折新枝。"]},{"t":"樱桃花","f":"七言绝句","c":["借煖冲寒不用媒，匀朱匀粉最先来。","玉梅一见怜痴小，教向傍边自在开。"]},{"t":"蝙蝠","f":"五言绝句","c":["伏翼昏飞急，营营定苦饥。","聚蚊充口腹，生汝亦奚为。"]},{"t":"镇下放船过东山二首 其二","f":"七言绝句","c":["老禅竿木各逢场，诗客端来共苇航。","一任颠风聒高浪，满船欢笑和诗忙。"]},{"t":"镇下放船过东山二首 其一","f":"七言绝句","c":["打头风急鼻雷鼾，醉梦閒心铁石顽。","惟有爱山贪未厌，西山才了又东山。"]},{"t":"题山水横看二首 其一","f":"七言绝句","c":["烟山漠漠水漫漫，老柳知秋渡口寒。","尽是西溪肠断处，凭君将与故人看。"]},{"t":"题山水横看二首 其二","f":"七言绝句","c":["霜入丹枫白苇林，横烟平远暮江深。","君看雁落帆飞处，知我秋风故国心。"]},{"t":"题天平寿老方丈","f":"七言绝句","c":["二十三年再入山，此山于我有前缘。","时人不用怜衰病，天与丹房一线泉。"]},{"t":"题开元天宝遗事四首 其四","f":"七言绝句","c":["剥啄延秋屋上乌，明朝箭道入东都。","宫中亦有风流阵，不及渔阳突骑粗。"]},{"t":"题开元天宝遗事四首 其三","f":"七言绝句","c":["朝天车马诏频催，斸得新汤未敢开。","忽报猪龙掀宇宙，阿瞒虚读相书来。"]},{"t":"题开元天宝遗事四首 其二","f":"七言绝句","c":["谢蛮舞袖贵妃弦，秦国如花虢国妍。","不赏缠头三百万，阿姨何处费金钱。"]},{"t":"题开元天宝遗事四首 其一","f":"七言绝句","c":["御前羯鼓透春空，笑觉花奴手未工。","一曲打开红杏蕊，须知天子是天公。"]},{"t":"题日记","f":"七言绝句","c":["谁言万事转头空，未转头时亦梦中。","若向梦中寻梦觉，觉来还入大槐宫。"]},{"t":"题记事册","f":"七言绝句","c":["划破虚空一剑间，六根同转上头关。","如今宴坐庵中事，政在凡夫道法间。"]},{"t":"题传记二首 其一","f":"七言绝句","c":["莫将綵笔寄朝云，红泪罗巾隔路尘。","说与东风无限恨，倩风吹断去年春。"]},{"t":"题传记二首 其二","f":"七言绝句","c":["綵舟归去海山青，寂莫瑶台月自明。","啼雨落花春已尽，梦魂何必更多情。"]},{"t":"题毕少董翻经图","f":"五言绝句","c":["绛帐胡沙暗，青编古意深。","谁知洛下咏，中有越人吟。"]},{"t":"题米元晖吴兴山水横卷","f":"七言绝句","c":["道场山麓接何山，影落苕溪浸碧澜。","只欠荷花三十里，橛头船上把渔竿。"]},{"t":"题张晞颜两花图二首 其二 玉梨","f":"七言绝句","c":["雪薄冰轻不耐春，雨中愁绪月中真。","莫教梦作云飞去，留伴昭阳第一人。"]},{"t":"题张晞颜两花图二首 其一 繁杏","f":"七言绝句","c":["红粉团枝一万重，当年独自费东风。","若为报答春无赖，付与笙歌鼎沸中。"]},{"t":"题李云叟画轴兼寄江安杨简卿明府二绝 其一","f":"七言绝句","c":["苍烟枯木共荒寒，篱落堤湾汹涨湍。","归路宛然归未得，閒将李叟画图看。"]},{"t":"题李云叟画轴兼寄江安杨简卿明府二绝 其二","f":"七言绝句","c":["新图来自雪边州，皴石枯槎笔最遒。","明府能诗如此画，为渠题作小营丘。"]},{"t":"题杨商卿扇","f":"七言绝句","c":["君归我去两销魂，愁满千山锁瘴云。","后夜短檠风雨暗，谁能相伴细论文。"]},{"t":"题宝林寺可赋轩","f":"七言绝句","c":["十里山行杂市声，道傍无处濯尘缨。","宝林寺里逢修竹，方有诗情约略生。"]},{"t":"题易元吉獐猿两图二首 其二","f":"五言绝句","c":["乌逐山公噪，惊麇仰望疑。","春林无一事，獝狘自生悲。"]},{"t":"题易元吉獐猿两图二首 其一","f":"五言绝句","c":["择食麇相唤，无人意不惊。","猿啼风动叶，机熟两忘情。"]},{"t":"题现老真","f":"七言绝句","c":["三十年来共葛藤，如今莲社冷如冰。","茶瓜樱笋游山会，从此斋厨欠一僧。"]},{"t":"题画卷五首 其四","f":"七言绝句","c":["暑云泼墨送惊雷，坐见前山骤雨来。","今夜一凉千万里，更无焦卷与尘埃。"]},{"t":"题画卷五首 其三","f":"七言绝句","c":["春阴十日溪头暗，夜半西风雨脚收。","但觉奔霆吼空谷，遥知万壑正争流。"]},{"t":"题画卷五首 其二","f":"七言绝句","c":["欹倾栈路绕山明，隔陇人家犬吠声。","无限白云堆去路，不知谁识许宣平。"]},{"t":"题画卷五首 其一","f":"七言绝句","c":["凿落秋江水石明，高枫老柳两滩横。","君看叠巘云容变，又有中宵雨意生。"]},{"t":"题南塘客舍","f":"七言绝句","c":["閒里方知得此生，痴人身外更经营。","君看坐贾行商辈，谁复从容唱渭城。"]},{"t":"题城山挂月堂壁","f":"七言绝句","c":["百叠烟鬟得眼明，坐来心迹喜双清。","秋阳满地西风起，犹有啼莺四五声。"]},{"t":"题城山晚对轩壁","f":"七言绝句","c":["一枕清风梦绿萝，人间随处是南柯。","也知睡足当归去，不奈溪山留客何。"]},{"t":"题秋鹭图","f":"七言绝句","c":["昨夜新霜冷钓矶，绿荷消瘦碧芦肥。","一江秋色无人问，尽属风标两雪衣。"]},{"t":"题药方","f":"七言绝句","c":["孤童亦复梦槐柯，无德无功用福多。","天理乘除当老病，巢源王诀奈君何。"]},{"t":"题药簏","f":"七言绝句","c":["合成四大本非真，便有千般病染身。","地火水风都散后，不知染病是何人。"]},{"t":"题赵希远案鹰图","f":"七言绝句","c":["学射春山万岁湖，牙门列骑卷平芜。","如今黄土原边梦，犹识呼鹰嗾犬图。"]},{"t":"题赵昌木瓜花","f":"五言绝句","c":["秋风魏瓠实，春雨燕脂花。","綵笔不可写，滴露匀朝霞。"]},{"t":"题徐熙风牡丹二首 其二 白花","f":"七言绝句","c":["寒入仙裙粟玉肌，舞馀全不耐风吹。","从教旅拒春无力，细看腰支袅袅时。"]},{"t":"题徐熙风牡丹二首 其一 紫花","f":"七言绝句","c":["蕊珠仙驭晓骖鸾，道服朝元露未乾。","天半刚风如激箭，绿绡飘荡紫绡寒。"]},{"t":"题黄州临皋亭","f":"七言绝句","c":["夏口风帆赤壁矶，雪堂酾酒竹楼棋。","系舟一日黄州下，只办登临不办诗。"]},{"t":"题蜀果图四首 其一 木瓜","f":"五言绝句","c":["沈沈黛色浓，糁糁金沙绚。","却笑宣州房，竞作红妆面。"]},{"t":"题锦亭","f":"七言绝句","c":["手开花径锦成窠，浩荡春风载酒过。","来岁游人应解笑，甘棠终少海棠多。"]},{"t":"题谭德称扇","f":"七言绝句","c":["蛮风吹雨瘴江肥，短草荒山鸟不飞。","尽是泸南肠断句，如今分与故人归。"]},{"t":"题醉道士图","f":"七言绝句","c":["蜩鴳鹏鹍任过前，壶中春色瓮中天。","朝来兀兀三杯后，且作人间有漏仙。"]},{"t":"颜桥道中","f":"七言绝句","c":["村村篱落总新修，处处田畴尽有秋。","一段农家好风景，稻堆高出屋山头。"]},{"t":"橙纲","f":"七言绝句","c":["尧舜方堪橘柚包，穹庐亦复使民劳。","华清荔子沾恩幸，一骑回时万骑骚。"]},{"t":"燕堂后卢橘一株冬前先开极香","f":"七言绝句","c":["卢橘花残细细飞，满枝晴日闹蜂儿。","霜馀有此香无奈，合与称题赋小诗。"]},{"t":"燕宫","f":"七言绝句","c":["金盆濯足段文昌，乞索家风饱便忘。","他日楚人能一炬，又从焦土说阿房。"]},{"t":"燕宾馆","f":"七言绝句","c":["九日朝天种落驩，也将佳节劝杯盘。","苦寒不似东篱下，雪满西山把菊看。"]},{"t":"衡阳道中二绝 其一","f":"五言绝句","c":["桑下芜菁晚，高花出短篱。","茅檐少春事，惟记浴蚕时。"]},{"t":"衡阳道中二绝 其二","f":"五言绝句","c":["黑羖钻篱破，花猪突户开。","空山竹瓦屋，犹有燕飞来。"]},{"t":"赠临江简寿玉二首简携王仲显使君书来谒并示孔毅甫梦蟾图今庙堂五府皆有题字 其一","f":"七言绝句","c":["萧滩远客扣田庐，贻我读书楼上书。","千里故情元共月，错云多病故人疏。"]},{"t":"赠临江简寿玉二首简携王仲显使君书来谒并示孔毅甫梦蟾图今庙堂五府皆有题字 其二","f":"七言绝句","c":["卷中图画袖中珍，上有三阶五朵云。","白日青天光范路，未饶蟾窟梦纷纭。"]},{"t":"赠举书记归云丘 其二","f":"七言绝句","c":["四股涧松雷斧碎，十围岩桂烧痕枯。","不知阶下跳珠处，旧竹春来有笋无。"]},{"t":"赠举书记归云丘 其三","f":"七言绝句","c":["青山面目想依依，水石风林入梦思。","白发苍颜心故在，只如当日看山时。"]},{"t":"赠举书记归云丘 其一","f":"七言绝句","c":["一枕清风四十霜，孤生无处话凄凉。","相看只有庞眉客，还在云丘旧草堂。"]},{"t":"濯缨亭在吴兴南门外","f":"七言绝句","c":["凄风急雨脱然晴，当道横山似见迎。","野水茫茫何用许，烂供游子濯尘缨。"]},{"t":"蹋鸱巾","f":"七言绝句","c":["重译知书自贵珍，一生心愧蹋鸱巾。","雨中折角君何爱，帝有衣裳易介鳞。"]},{"t":"蟠龙瀑布自山顶漫汗淋漓分数道而下望之宛从天降当为城中布水第一","f":"七言绝句","c":["银汉来从左界天，天风吹浪落苍巅。","人间只见秧田润，唤作蟠龙洞里泉。"]},{"t":"覆盆铺","f":"七言绝句","c":["三登三降冈始断，一步一休日欲斜。","浊酒半瓶不得煖，覆盆有铺无浆家。"]},{"t":"鳗井","f":"七言绝句","c":["决甃神通未易论，雨声留客夜翻盆。","不辞客路春泥滑，且足秧田旧水痕。"]},{"t":"夔州竹枝歌九首 其九","f":"七言绝句","c":["当筵女儿歌竹枝，一声三叠客忘归。","万里桥边有船到，绣罗衣服生光辉。"]},{"t":"夔州竹枝歌九首 其八","f":"七言绝句","c":["滟滪如襆瞿唐深，鱼复阵图江水心。","大昌盐船出巫峡，十日溯流无信音。"]},{"t":"夔州竹枝歌九首 其七","f":"七言绝句","c":["白帝庙前无旧城，荒山野草古今情。","只馀峡口一堆石，恰似人心未肯平。"]},{"t":"夔州竹枝歌九首 其三","f":"七言绝句","c":["新城果园连瀼西，枇杷压枝杏子肥。","半青半黄朝出卖，日午买盐沽酒归。"]},{"t":"一龛","f":"七言律诗","c":["一龛窄似鸟窠禅，世界悠悠任大千。","与老有情冬后煖，去仙无几日高眠。","斫开竹后初三径，忘却诗来又一年。","破戒忽题无味句，劣能成字不成篇。"]},{"t":"乙未元日用前韵书怀今年五十矣","f":"七言律诗","c":["浮生四十九俱非，楼上行藏与愿违。","纵有百年今过半，别无三策但当归。","定中久已安心竟，饱外何须食肉飞。","若使一丘并一壑，还乡曲调尽依稀。"]},{"t":"丁未春日瓶中梅殊未开二首 其二","f":"五言律诗","c":["夜雪腊前冻，朝阳春后苏。","人怜疏蕊瘦，花笑病翁臞。","露白能多少，寻春似有无。","诗催全不力，煮水换铜壶。"]},{"t":"丁未春日瓶中梅殊未开二首 其一","f":"五言律诗","c":["暖閤无人到，寒枝为我横。","情钟吹蕊破，静极觉香生。","老去魂休断，春来眼且明。","逃禅时索笑，百匝傍窗行。"]},{"t":"丁酉正月二日东郊故事","f":"七言律诗","c":["椒盘宿酒未全醒，扰扰金鞍逐画軿。","麦雨一犁随处绿，柳烟千缕几时青。","客愁旧岁连新岁，归路长亭间短亭。","万里松楸双泪堕，风前安得讳飘零。"]},{"t":"丁酉重九药市呈坐客","f":"七言律诗","c":["莫向登临怨落晖，自缘羁宦阻归期。","年来厌把三边酒，此去休哦万里诗。","乌帽不辞欹短发，黄花终是欠东篱。","若无合坐挥毫健，谁解西风楚客悲。"]},{"t":"七月二日上沙夜泛","f":"七言律诗","c":["困倚船窗看斗斜，起来风露满天涯。","亭亭宿鹭明菰叶，闪闪凉萤入稻花。","月下片云应夜雨，山根炬火忽人家。","江湖处处无穷景，半世红尘老岁华。"]},{"t":"九月三十日夜出关候致远不至","f":"五言律诗","c":["风劲便轻棹，霜严怯弊裘。","青山蟠巨浸，红树立沧洲。","月黑雁犹去，灯寒人更愁。","烟松漫小岘，何处问鸣驺。"]},{"t":"二月二十七日病后始能扶头","f":"七言律诗","c":["复幕重帘苦见遮，暮占栖雀晓占鸦。","残灯煮药看成老，细雨鸣鸠过尽花。","心为蚤衰元自化，发从无病已先华。","更蒙厉鬼相提唱，此去山林属当家。"]},{"t":"二月三日登楼有怀金陵宣城诸友","f":"七言律诗","c":["百尺西楼十二栏，日迟花影对人閒。","春风已入片时梦，寒食从今数日间。","折柳故情多望断，落梅新曲与愁关。","诗成欲访江南便，千里烟波万叠山。"]},{"t":"入秭归界","f":"七言律诗","c":["山根系马得浆家，深入穷乡事可嗟。","蚯蚓祟人能作瘴，茱萸随俗强煎茶。","幽禽不见但闻语，野草无名都著花。","窈窕崎岖殊未艾，去程方始问三巴。"]},{"t":"八十四盘","f":"七言律诗","c":["冥鸿无伴鹤孤飞，回首尘笼一笑嬉。","八十四盘新拄杖，万三千乘旧牙旗。","石梯碧滑云生后，木叶红斑雪霁时。","说与同行莫惆怅，人间捷径转嵚巇。"]},{"t":"十一月十二日枕上晓作","f":"五言律诗","c":["竹响风成阵，窗明雪已花。","柴扉吟冻犬，纸瓦啄饥鸦。","宿酒欺寒力，新诗管岁华。","日高犹拥被，蓐食愧邻家。"]},{"t":"十一月十日海云赏山茶","f":"七言律诗","c":["门巷欢呼十里村，腊前风物已知春。","两年池上经行处，万里天边未去人。","客鬓花身俱岁晚，妆光酒色且时新。","海云桥下溪如镜，休把冠巾照路尘。"]},{"t":"十二月二十四日西楼观雪","f":"七言律诗","c":["一夜珠帘不下钩，彻明随雪上西楼。","瑶池万顷昆崙近，玉垒千峰滴博收。","已报春回南亩润，从教寒勒北枝愁。","四筵都为丰年醉，录事何须校酒筹。"]},{"t":"十二月十八日海云赏山茶","f":"七言律诗","c":["追趁新晴管物华，马蹄松快帽檐斜。","天南腊尽风晞雪，冰下春来水漱沙。","已报主林催市柳，仍从掌故问山茶。","丰年自是驩声沸，更著牙前画鼓挝。"]},{"t":"十月朝开炉偶书余病归二年未能拜埽松楸曩常以此日侍先兄游洞庭并写悲感之怀","f":"五言律诗","c":["圃芋今年紫，篱枫昨日丹。","开炉修故事，听雨说新寒。","橘社重游阻，楸行再拜难。","此时西望眼，衰涕不胜弹。"]},{"t":"咏吴中二灯 其二 万眼罗","f":"五言律诗","c":["弱骨千丝结，轻毬万锦装。","綵云笼月魄，宝气绕星芒。","檀点红娇小，梅妆粉细香。","等閒三夕看，消费一年忙。"]},{"t":"三月二十三日海云摸石","f":"七言律诗","c":["劝耕亭上往来频，四海萍浮老病身。","乱插山茶犹昨梦，重寻池石已残春。","惊心岁月东流水，过眼人情一鬨尘。","赖有贻牟堪饱饭，道逢田畯且眉伸。"]},{"t":"三月十九日夜极冷","f":"七言律诗","c":["谁勒馀寒不放回，春深犹煖地炉灰。","乡心忽向灯前动，夜雨先从竹里来。","鶗鴂已如莺百啭，酴醾那复雪千堆。","调糜煮药东风老，惭愧茶瓯与酒杯。"]},{"t":"三次喜雨诗韵少伸嘉颂","f":"七言律诗","c":["向非贤牧政通灵，几负松陵耒耜经。","天籁侵晨占少女，雨师连夜檄玄冥。","作霖岂必求商野，召见谁能右汉庭。","闻有追锋传好语，从今侧耳为君听。"]},{"t":"上巳日万岁池上呈程咏之提刑","f":"七言律诗","c":["浓春酒煖绛烟霏，涨水天平雪浪迟。","绿岸翻鸥如北渚，红尘跃马似西池。","麦苗剪剪尝新面，梅子双双带折枝。","试比长安水边景，只无饥客为题诗。"]},{"t":"上巳前一日学射山万岁池故事","f":"七言律诗","c":["北郊征路记前回，三尺惊尘马踏开。","新涨忽明多病眼，好风如把及时杯。","青黄麦垄平平去，疏密桤林整整来。","游骑不知都几许，长堤十里转轻雷。"]},{"t":"上元有感","f":"五言律诗","c":["岳树五千仞，莲花千万枝。","宛然明月夜，非是少年时。","已自欢悰少，那堪官绪羁。","人言急行乐，何以且迟迟。"]},{"t":"上元观灯","f":"七言律诗","c":["万家罗绮竞喧阗，乐事能并在锦川。","兰烛连衢千对烂，冰轮此夕十分圆。","喜逢蜀国寻春日，正是摩陀供佛天。","人物熙熙醒醉里，却思风景似当年。"]},{"t":"上方寺","f":"五言律诗","c":["舣棹古销夏，支筇新上方。","珠湾锁员折，冰镜沉空光。","枫缬醉晴日，橘黄明蚤霜。","閒门松竹径，随处有清凉。"]},{"t":"上沙田舍","f":"七言律诗","c":["更无云物起微阴，垄亩人家各好音。","岁晚阳和归稻把，夜来霜力到枫林。","儿童笑里丰年面，乌鸟声中落日心。","酿秫炊粳都入手，剩拚腰脚办登临。"]},{"t":"上清宫","f":"七言律诗","c":["历井扪参兴未阑，丹梯通处更跻攀。","冥濛蜀道一云气，破碎岷山千髻鬟。","但觉星辰垂地上，不知风雨满人间。","蜗牛两角犹如梦，更说纷纷触与蛮。"]},{"t":"下岩","f":"七言律诗","c":["畴昔中岩一梦残，下岩风景亦高寒。","峡中无处堪停棹，雨后今朝始凭阑。","不用苦求毫相现，祇教长挂水帘看。","山僧劝我题苍壁，坡谷前头未敢刊。"]},{"t":"与正夫朋元游陈侍御园","f":"七言律诗","c":["沙际春风捲物华，意行聊复到君家。","年年我是曾来客，处处梅皆旧识花。","官减不妨诗事业，地寒犹办醉生涯。","城中马上那知此，尘满长裾席帽斜。"]},{"t":"与长文正夫游北山","f":"七言律诗","c":["柳岸松门胜处通，马蹄踏雾入空濛。","春寒有力欺游子，天色无情没断鸿。","雨脚远连山脚暗，杏梢斜倚竹梢红。","驼裘拥鼻吾衰矣，年少犹嫌料峭风。"]},{"t":"与胡经仲陈朋元游照山堂梅数百株盛开","f":"七言律诗","c":["九陌缁尘满客襟，钱塘门外有园林。","胡床住处梅无限，酒旆垂边柳未深。","晴日暖风千里目，残山剩水一人心。","元方伯始皆吾党，解后清游直万金。"]},{"t":"与游子明同过石湖","f":"七言律诗","c":["契阔相逢一笑欢，当年森桂共骖鸾。","试谈旧事醒村酒，仍趁新晴暖客鞍。","梅粉都皴啼宿雨，柳黄不展噤春寒。","从今鼎鼎多幽事，仍喜蛙声不在官。"]},{"t":"习閒","f":"七言律诗","c":["习閒成懒懒成痴，六用都藏缩似龟。","雪已许多犹不饮，梅今如此尚无诗。","閒看猫暖眠毡褥，静听猧寒叫竹篱。","寂寞无人同此意，时时惟有睡魔知。"]},{"t":"大厅后堂南窗负暄","f":"七言律诗","c":["万壑无声海不波，一窗油纸暮春和。","醉眠陡觉氍毹赘，围坐翻嫌榾柮多。","水暖玉池添漱咽，花生银海费揩摩。","端如拥褐茅檐下，袛欠乌乌击缶歌。"]},{"t":"大热泊乐温有怀商卿德称","f":"五言律诗","c":["暑候秋逾浊，江流晚更浑。","瘴风如火焮，岚月似烟昏。","城郭廪君国，山林妃子园。","故人新判袂，得句与谁论。"]},{"t":"大雪书怀","f":"七言律诗","c":["天将奇赏发清欢，畴昔登临插羽翰。","梅下寻诗骑马滑，松梢索酒倚楼寒。","闭门老子愁无赖，返棹归来兴已阑。","聊掬玉尘添石鼎，自煎鱼眼破龙团。"]},{"t":"小溪县","f":"五言律诗","c":["刈麦千平垄，横槎一小溪。","梓花红绽碎，粟穗绿垂低。","村妇犹多跣，山猿遂少啼。","东川虽已过，锦里尚云西。"]},{"t":"己丑中秋寓宿玉堂闻沈公雅大卿刘正夫户部集张园赏月走笔寄之","f":"七言律诗","c":["笑看收云捲雨忙，沉沉宫树纳空光。","夜长来伴玉堂宿，天近似闻丹桂香。","鳷鹊楼栏浮瑞气，凤凰城阙带新凉。","遥知胜绝西园会，也忆车公对举觞。"]},{"t":"己丑五月被召至行在遇周畏知司直和五年前送周归弋阳韵见赠复次韵答之","f":"七言律诗","c":["分袂悠悠尔许年，莫嗔蓬鬓两萧然。","酒槽不奈青春老，经笥空供白昼眠。","暗绿千章新活计，软红三尺旧尘缘。","相逢且作西湖客，山绕荷花舣画船。"]},{"t":"巾子山又雨","f":"七言律诗","c":["百日篮舆困局跧，三晨泥坂兀跻攀。","晚晴幸自垫江县，今雨奈何巾子山。","树色于人殊漠漠，云容怜我稍班班。","如今只忆雪溪句，乘兴而来兴尽还。"]},{"t":"马当洑阻风居人云非五日或七日风不止谓之重阳信","f":"七言律诗","c":["拍岸回流逆上矶，枯杨折苇静相依。","趁墟渔子晨争渡，赛庙商人晚醉归。","重九信来风未慭，大千行遍昨俱非。","羁愁万斛从头数，带眼今秋又减围。"]},{"t":"中秋无月复次韵","f":"七言律诗","c":["屋山从捲杜陵茅，门径慵芟仲蔚蒿。","澹澹白虹风晕壮，纷纷苍狗雨云高。","凌空累箸仙无术，半夜撞钟句谩豪。","枵腹题诗将底用，真成兔角与龟毛。"]},{"t":"乌戍密印寺","f":"七言律诗","c":["青堆溪上水平堤，绛瓦参差半掩扉。","我与圣公俱客寓，人传帝子尚灵威。","胜缘龃龉三重障，志士辛勤十载归。","花木禅房都不见，但馀蝙蝠昼群飞。"]},{"t":"予寓邑中与诸子讲学巨山侄孙转示初冬书事因用韵","f":"七言律诗","c":["霜风几夕报初寒，蟋蟀归来已四迁。","旧物有毡眠软暖，讲堂逢鳝馈新鲜。","功名久已遗清老，征戍何由及晚年。","暴客更缘贫见外，时危身老亦悠然。"]},{"t":"云露","f":"七言律诗","c":["饮少尝遭大户嗤，病中全是独醒时。","三年鲁望自怜赋，万祀渊明真止诗。","破戒忽传云露法，赏心仍把雪梅枝。","一杯未问长生事，先罥蛛尘药裹丝。"]},{"t":"元夕后连阴","f":"七言律诗","c":["问讯东风几日来，冷烟寒雾锁池台。","扫空积雪翻成雨，收尽残灯未见梅。","夜饮厌厌非老伴，春阴漠漠是愁媒。","谁能腰鼓催花信，快打凉州百面雷。"]},{"t":"元夕呈冲卿侍郎","f":"七言律诗","c":["人间胜事不常有，自古年华无重回。","半夜飞云并行月，平明微雨拂轻埃。","莲花正在山头发，桃树应从洞里开。","寄语夫君急行柬，省闱看是辟书来。"]},{"t":"元日","f":"七言律诗","c":["老来百味絮沾泥，期会关身尚火驰。","几夜乡心欹枕处，今年脚力上楼时。","酒缸幸有乾坤大，丹鼎何忧日月迟。","莫道神仙无可学，学仙犹胜簿书痴。"]},{"t":"元日","f":"七言律诗","c":["屋角峥嵘斗柄移，案头萧索烛花垂。","与时消息评新药，若节春秋忆旧诗。","饥饭困眠全体懒，风餐露宿半生痴。","尊前现在休嫌老，最后屠苏把一卮。"]},{"t":"元日立春感叹有作二首 其二","f":"五言律诗","c":["元日兼春日，閒身是老身。","行年申直戊，交运丑支辛。","岂敢綦安佚，聊希刮钝屯。","童儿看书户，把笔已如神。"]},{"t":"元日立春感叹有作二首 其一","f":"五言律诗","c":["元日兼春日，霜寒又雪寒。","并烦传菜手，同捧颂椒盘。","叠膝稀穿履，扶头懒正冠。","五年如此度，宁得讳衰残。"]},{"t":"元日奉呈项丈诸生","f":"五言律诗","c":["节物阴涔里，人情冷淡中。","百忧寻老大，一笑属儿童。","雪意愁饥雀，风声入断鸿。","新衣满闾巷，终日自西东。"]},{"t":"元日钟山宝公塔","f":"七言律诗","c":["雪后江皋未放春，老来犹驾两朱轮。","归心历历来时路，官事驱驱病里身。","未暇鸡窠寻古佛，且防鹤帐怨山人。","君看王谢墩边地，今古功名一窖尘。"]},{"t":"元夜忆群从","f":"五言律诗","c":["愁里仍蒿径，閒中更荜门。","青灯聊自照，浊酒为谁温。","隙月知无梦，窗梅寄断魂。","遥怜好兄弟，飘泊两江村。"]},{"t":"公安渡江","f":"五言律诗","c":["食罢雨方作，起行泥已深。","伴愁多楚些，吟病独吴音。","莫怨马蹄滑，须愁蚕事侵。","梅黄时节是，未可决晴阴。"]},{"t":"公退书怀","f":"七言律诗","c":["昨者腾章奏发仓，今兹飞檄议驱蝗。","四无告者仅一饱，七不堪中仍百忙。","皦日自能临俯仰，浮云宁解制行藏。","求田问舍亦何有，岁晚倦游思故乡。"]},{"t":"公辨用前韵见赠复次韵","f":"七言律诗","c":["先生笔力玉山鳌，气压明堂一柱蒿。","雪椀涤毫词绝妙，朱弦缩瑟调弥高。","心兵不起无三粲，坐客常多似四豪。","喜有过从南北巷，苏兰薪桂瀹溪毛。"]},{"t":"公辨再赠复次韵","f":"七言律诗","c":["书生活计极萧骚，爝火微明似束蒿。","犬子地寒徒壁立，元龙身懒谩楼高。","笔端未办誇三绝，酒里犹能扫二豪。","又向诗坛蕲借一，强磨铅钝齿吹毛。"]},{"t":"午窗遣兴家人谋过石湖","f":"七言律诗","c":["云日初收破柱雷，小窗坐稳兴悠哉。","熏炉花气朝酲解，茶鼎松风午梦回。","谢客门阑风动竹，惜春时节雨肥梅。","画船破浪亦一快，闻道湖光如泼醅。"]},{"t":"天平先陇道中时将赴新安掾","f":"七言律诗","c":["霜桥冰涧净无尘，竹坞梅溪未放春。","百叠海山乡梦熟，三年江路旅愁生。","松楸永寄孤穷泪，泉石终收漫浪身。","好住邻翁各安健，归来相访说情真。"]},{"t":"太上皇帝灵驾发引挽歌词六首 其六","f":"五言律诗","c":["文德尧新庙，威灵禹旧山。","海门宾羽卫，地轴启云关。","无路攀仙驾，当年拱圣颜。","小臣衰疾泪，空望帝乡潸。"]},{"t":"太上皇帝灵驾发引挽歌词六首 其五","f":"五言律诗","c":["帝业虽天广，皇心本谷虚。","神应游混沌，梦不返华胥。","挍德难涯涘，铭功总绪馀。","谁能言大道，第入四坟书。"]},{"t":"太上皇帝灵驾发引挽歌词六首 其四","f":"五言律诗","c":["传圣家人礼，凝神象帝先。","勋华今历数，汾社古山川。","众父尊归父，中天更有天。","寿宫何所厌，亟上白云仙。"]},{"t":"太上皇帝灵驾发引挽歌词六首 其三","f":"五言律诗","c":["箫勺妖氛静，甄陶叶气还。","春回慈殿驾，天作祐陵山。","开辟风云惨，登平日月閒。","艰难虽独瘠，寿域遍人间。"]},{"t":"太上皇帝灵驾发引挽歌词六首 其二","f":"五言律诗","c":["自将吴津骑，谁婴泰一锋。","旄头连夜落，京观隔江封。","舞武三成备，书文九译重。","修攘遗策在，嗣圣续车攻。"]},{"t":"太上皇帝灵驾发引挽歌词六首 其一","f":"五言律诗","c":["绍运钟阳九，兴王抚半千。","断鳌娲立极，翔凤汉中天。","宵旰三星纪，希夷十闰年。","声容弥宇宙，浯石不胜镌。"]},{"t":"太平瑞圣花","f":"五言律诗","c":["雪外扪参岭，烟中濯锦洲。","密攒文杏蕊，高结綵云毬。","百世嘉名重，三登瑞气浮。","挽春同住夏，看到火西流。"]},{"t":"太保节使赵公挽词","f":"五言律诗","c":["结发险艰会，捐躯跳荡功。","鬓凋犹陛戟，心在惜韬弓。","剑履三槐次，楼台四壁中。","诸郎竞文武，不朽是清风。"]},{"t":"巴东峡口","f":"五言律诗","c":["水宿频欹侧，徒行又险艰。","舟危神女峡，马瘦鬼门关。","照夜烧畬陇，缘云种笮山。","催成头雪白，休说鬓丝斑。"]},{"t":"巴蜀人好食生蒜臭不可近顷在峤南其人好食槟榔合蛎灰扶留藤一名蒌藤食之辄昏然已而醒快三物合和唾如脓血可厌今来蜀道又为食蒜者所薰戏题","f":"五言律诗","c":["旅食谙殊俗，堆盘骇异闻。","南餐灰荐蛎，巴馔菜先荤。","幸脱蒌藤醉，还遭胡蒜熏。","丝莼乡味好，归梦水连云。"]},{"t":"忆昔","f":"七言律诗","c":["铅刀曾齿莫邪铦，游倦归欤雪满髯。","柳带受风元不结，荷盘承露竟无黏。","逢场鼓笛如灰冷，送老齑盐似蜜甜。","留得本来真面目，行藏何假问龟占。"]},{"t":"水乡酌别但能之主管能之将过石康","f":"七言律诗","c":["南郭河桥市井喧，绿荷香处有江天。","一帘梅雨炉烟外，三叠阳关烛泪前。","马耳西风君并海，船头北渚我归田。","后期只恐参商似，且醉金槽四十弦。"]},{"t":"王仲行尚书录示近诗闻今日劝农灵岩次韵纪事","f":"七言律诗","c":["馆娃宫殿压云头，自昔登临隘九州。","雪浪长风三万顷，苍烟古木二千秋。","宾僚谁伴作诗苦，父老竞传敷政优。","想见归骖穿夜市，月边灯火满西楼。"]},{"t":"王希武通判挽词二首 其一","f":"五言律诗","c":["当代名臣后，惟公奕世贤。","及亲三釜养，遗子一经传。","药石探奇字，芸香缉断编。","堂堂今不见，尘迹自依然。"]},{"t":"王季海秘监再赋成园复次韵","f":"七言律诗","c":["云庄风榭对东西，清暑光阴近竹迷。","一斗正缘诗兴尽，两眉休为客愁低。","披开豹雾寻陈迹，扫尽蛛尘看旧题。","健往莫愁骑马滑，阑珊梅雨不成泥。"]},{"t":"王南卿母挽词","f":"五言律诗","c":["栉縰称纯孝，笄珈蚤隐忧。","病中心已化，身外世如浮。","闻道悲风木，谁能驻壑舟。","佳儿行古道，足以贲潜幽。"]},{"t":"长至日与同舍游北山","f":"五言律诗","c":["岁晚山同色，湖平雾不收。","寒云低阁雪，佳节静供愁。","竹柏森严立，蒲荷索莫休。","瘦筇知脚力，政尔耐清游。"]},{"t":"丙午新正书怀十首 其十","f":"七言律诗","c":["殊方节物记吾曾，海北天西一瘦藤。","乌榄鸡槟尝老酒，酥花芋叶试新灯。","瘴云度岭浓如墨，边雪窥窗冷欲冰。","閒展两乡图画看，卧游何必减深登。"]},{"t":"丙午新正书怀十首 其九","f":"七言律诗","c":["窗明窗暗篆烟馡，珍重晨光与夕晖。","东院斋钟披被坐，南城严鼓岸巾归。","几人霜滑骑朝马，何处灯残织晓机。","懒里若承三昧力，始知忙里事俱非。"]},{"t":"丙午新正书怀十首 其八","f":"七言律诗","c":["经过扫轨但幽栖，巢稳林深寄一枝。","栗里归来窗下卧，香山老去病中诗。","东风马耳尘劳后，半夜鸡声睡熟时。","俯仰平生尽尘迹，恰如腷膊几枰棋。"]},{"t":"丙午新正书怀十首 其七","f":"七言律诗","c":["炭熟香浓石鼎煨，人言小閤是春台。","蕉心翠展一冬在，梅藟粉融连夜开。","肃肃九冰妨发育，温温三火护恢台。","养生此外无遗说，梨枣元须趁暖栽。"]},{"t":"丙午新正书怀十首 其六","f":"七言律诗","c":["俗情如絮已泥沾，因病偷閒意属厌。","鹏鴳相安无可笑，熊鱼自古不容兼。","灰藏榾柮多时暖，雪压蔓菁满意甜。","温饱闭门吾事办，异时书判指如签。"]},{"t":"丙午新正书怀十首 其五","f":"七言律诗","c":["厉风翻海雪漫天，百计逃寒息万缘。","稳作被炉如卧炕，厚裁绵旋胜披毡。","尊前现在瞢腾醉，饭后无何烂熳眠。","斟酌出门高兴尽，从教閒却剡溪船。"]},{"t":"丙午新正书怀十首 其三","f":"七言律诗","c":["煮茗烧香了岁时，静中光景笑中嬉。","身閒一日似两日，春浅南枝如北枝。","朝镜略无功业到，午窗惟有睡魔知。","年来并束床头易，一任平章济叔痴。"]},{"t":"丙午新正书怀十首 其二","f":"七言律诗","c":["瘦骨难胜遇节衣，日高催起趁晨炊。","病怜楖栗随身惯，老觉屠苏到手迟。","一饱但蕲庚癸诺，百年甘守甲辰雌。","莫言此外都无事，柳眼梅梢正索诗。"]},{"t":"丙午新正书怀十首 其一","f":"七言律诗","c":["不用桃符贴画鸡，身心安处是天倪。","行年六十旧历日，汗脚尺三新杖藜。","祝我剩周花甲子，谢人深劝玉东西。","春风若借筋骸便，先渡南村学灌畦。"]},{"t":"丙申元日安福寺礼塔","f":"七言律诗","c":["岭梅蜀柳笑人忙，岁岁椒盘各异方。","耳畔逢人无鲁语，鬓边随我是吴霜。","新年后饮屠苏酒，故事先然窣堵香。","石笋新街好行乐，与民同处且逢场。"]},{"t":"东林寺","f":"七言律诗","c":["谈易翻经宰木春，三生犹自袅烟熏。","客尘长隔虎溪水，劫火不侵香谷云。","老矣懒供莲社课，归哉忺读草堂文。","山头一任天灯现，个事何曾落见闻。"]},{"t":"代人七月十四日生朝","f":"七言律诗","c":["秋入壶中玉宇鲜，芝兰桃李共熙然。","已饶瑞荚明朝满，先借清蟾一夜圆。","北阙紫泥应道路，东山红袖莫云烟。","如今且醉江湖酒，来岁城南尺五天。"]},{"t":"代圣集赠别","f":"七言律诗","c":["一曲悲歌水倒流，尊前何计缓千忧。","事如梦断无寻处，人似春归挽不留。","草色粘天鶗鴂恨，雨声连晓鹧鸪愁。","迢迢绿浦帆飞远，今夜新晴独倚楼。"]},{"t":"冬至日天庆观朝拜云日晴丽遥想郊禋庆成作驩喜口号","f":"七言律诗","c":["淅淅霜风不满旗，紫烟黄气捧朝曦。","五更贯索埋光后，万里钩陈放仗时。","留滞周南无旧事，布宣汉德有新诗。","丰年四海皆温饱，愿把欢心寿玉卮。"]},{"t":"冬至日铜壶阁落成","f":"七言律诗","c":["走遍人间行路难，异乡风物杂悲欢。","三年北户梅边暖，万里西楼雪外寒。","已办鬓霜供岁籥，仍拚髀肉了征鞍。","故园云物知何似，试上东楼直北看。"]},{"t":"冬至夜发峡州舟中作","f":"五言律诗","c":["舟中万里行，灯下一阳生。","不减在家好，都忘为旅情。","霜乾风愈劲，云淡月微明。","况有诗兼酒，樽前莫问更。"]},{"t":"北山堂开炉夜坐","f":"七言律诗","c":["困眠醒坐一龛多，竹洞无关断客过。","贪向炉中煨榾柮，懒从掌上看庵摩。","閒无杂念惟诗在，老不甘心奈镜何。","八万四千安乐法，元无秘密可伽陀。"]},{"t":"北门覆舟山道中","f":"七言律诗","c":["苒苒霜风掠弊貂，簿书尘外访渔樵。","林烟色淡如濛雨，塘水痕深似落潮。","雁字江天闻塞管，梅梢山路欠溪桥。","骑驴索句当年事，岁暮骚人不自聊。"]},{"t":"去年多雪苦寒梅花遂晚元夕犹未盛开","f":"七言律诗","c":["隔年寒力冻芳尘，勒住东风寂寞滨。","只管苦吟三尺雪，那知迟把一枝春。","灯烘画阁香犹冷，汤煖铜瓶玉尚皴。","花定有情堪索笑，自怜无术唤真真。"]},{"t":"发荆州","f":"七言律诗","c":["初上篷笼竹笮船，始知身是剑南官。","沙头沽酒市楼暖，径步买薪江墅寒。","自古秦吴称绝国，于今归峡有名滩。","千山万水垂垂老，只欠天西蜀道难。"]},{"t":"四月十日出郊","f":"七言律诗","c":["约束南风彻晓忙，收云捲雨一川凉。","涨江混混无声绿，熟麦骚骚有意黄。","吏卒远时閒信马，田园佳处忽思乡。","邻翁万里应相念，春晚不归同插秧。"]},{"t":"四月五日集陈园照山堂","f":"七言律诗","c":["寻壑经丘到此堂，官闲聊作送春忙。","短篱水面残红满，团扇风前众绿香。","尽捲帘旌延竹色，深斟杯酒纳山光。","洞门无锁城门近，转午鸡啼日正长。"]},{"t":"圣集誇说少年俊游用韵记其语戏之","f":"七言律诗","c":["京尘红软扑雕鞍，年少王孙酒量宽。","倚袖竹风怜翠薄，捧杯花露怯金寒。","黄云城上栖乌曲，绿水桥边斗鸭栏。","别后相思惟故物，壁煤侵损扇中鸾。"]},{"t":"外舅挽词二首 其一","f":"五言律诗","c":["植德千章茂，硎材百鍊刚。","事功才止此，物理故难量。","雁序云天远，兰阶雨露芳。","公无憾身后，人自惜堂堂。"]},{"t":"外舅挽词二首 其二","f":"五言律诗","c":["幽介联昏援，门阑阅岁更。","方欣承燕几，何意写铭旌。","笑语犹寻梦，恩勤已隔生。","情伤到深处，有泪不胜倾。"]},{"t":"正月十四日雨中与正夫朋元小集夜归","f":"七言律诗","c":["灯市凄清灯火稀，雨巾风帽笑归迟。","月明想在云堆处，客醉都忘马滑时。","老去樽前花隔雾，春来句里鬓成丝。","浮生不了悲欢事，作剧儿童总未知。"]},{"t":"民病春疫作诗悯之","f":"七言律诗","c":["乖气肆行伤好春，十家九空寒螀呻。","阴阳何者强作孽，天地岂其真不仁。","去腊奇寒衾似铁，连年薄热甑生尘。","疲氓惫矣可更病，我作此诗当感神。"]},{"t":"玉堂寓直","f":"七言律诗","c":["摛文窗户九霄中，岸帻烧香愧老农。","上直马归催下钥，传更人唱促鸣钟。","金城巀嵲云千雉，碧瓦参差月万重。","骨冷魂清都不梦，玉阶萧瑟听秋蛩。"]},{"t":"用汉中帅阎才元侍郎韵送樊子南西归兼呈侍郎","f":"七言律诗","c":["万里山巅与水涯，春风招看杏园花。","向来科第直溷子，此去文章应满家。","休学游仙穷越巂，且从知己控褒斜。","南楼东望当思我，药裹堆中两鬓华。"]},{"t":"田舍","f":"五言律诗","c":["呼唤携锄至，安排筑圃忙。","儿童眠落叶，鸟雀噪斜阳。","烟火村声远，林菁野气香。","乐哉今岁事，天末稻云黄。"]},{"t":"甲午岁朝寓桂林记去年是日泊桐江谒严子陵祠迤逦度岭感怀赋诗","f":"七言律诗","c":["去年晓缆解江皋，也把屠苏泛浊醪。","一席饱风渔浦阔，千山封雪钓台高。","将军老矣鸣孤剑，客子归哉咏大刀。","早晚扁舟寻旧路，柁楼吹笛破云涛。"]},{"t":"甲午除夜犹在桂林念致一弟使虏今夕当宿燕山会同馆兄弟南北万里感怅成诗","f":"七言律诗","c":["把酒新年一笑非，鹡鸰原上巧相违。","墨浓云瘴我犹住，席大雪花君未归。","万里关山灯自照，五更风雨梦如飞。","别离南北人谁免，似此别离人亦稀。"]},{"t":"立冬夜舟中作","f":"五言律诗","c":["人逐年华老，寒随雨意增。","山头望樵火，水底见渔灯。","浪影生千叠，沙痕没几棱。","峨眉欲还观，须待到晨兴。"]},{"t":"立春","f":"五言律诗","c":["候管灰初动，条风已发春。","万灵归化育，一气验平均。","农事牛先示，人情蠖欲伸。","优哉汉疏广，樽酒过嘉辰。"]},{"t":"立春日郊行","f":"七言律诗","c":["竹拥溪桥麦盖坡，土牛行处亦笙歌。","曲尘欲暗垂垂柳，醅面初明浅浅波。","日满县前春市合，潮平浦口暮帆多。","春来不饮兼无句，奈此金幡綵胜何。"]},{"t":"立春日陪魏丞相登三江亭","f":"七言律诗","c":["佳节登临始此回，聊从晻霭望蓬莱。","水分江北渡头去，风自海东潮外来。","太白天寒犹带雪，十洲池暖已浮醅。","一尊往酹发船鼓，我亦归帆相次开。"]},{"t":"前堂观月","f":"七言律诗","c":["箕踞绳床政自豪，远游何暇续离骚。","萧森万竹秋逾瘦，突兀双楠夜更高。","东郭风喧三鼓市，西城石汹二江涛。","色尘声界如如现，本自无禅不用逃。"]},{"t":"?䢹驿大雨","f":"五言律诗","c":["暮雨连朝雨，长亭又短亭。","今朝骑马怯，平日系船听。","竹叶垂头碧，秧苗满意青。","农畴方可望，客路敢遑宁。"]},{"t":"龙学侍郎清河侯张公挽词二首 其二","f":"五言律诗","c":["太息逢萋锦，平生付薄冰。","沧溟淙赤舌，白日照青蝇。","岳麓身犹健，星维驭已升。","天如遗一老，人亦望三登。"]},{"t":"龙学侍郎清河侯张公挽词二首 其一","f":"五言律诗","c":["白水名多士，清河最有声。","人危孔北海，帝识柳宜城。","蜀险谈间固，蛮讧檄到平。","凌烟何处在，风雨上铭旌。"]},{"t":"龙学尚书新安侯罗公挽词二首 其二","f":"五言律诗","c":["一昨更调瑟，如闻欲赐环。","途殚泣西狩，望绝起东山。","华屋林霏惨，新阡草露班。","春风埋玉泪，重为庾公潸。"]},{"t":"仲行再示新句复次韵述怀","f":"七言律诗","c":["神仙懒学古浮丘，祖意慵参老赵州。","四壁尘埃心似水，一生风露鬓先秋。","病衰谨谢吴中客，技拙甘同楚国优。","斥鴳蓬蒿元自足，世间何必卧高楼。"]},{"t":"会庆节大慈寺茶酒","f":"七言律诗","c":["霜晖催晓五云鲜，万国欢呼共一天。","澹澹煖红旗转日，浮浮寒碧瓦收烟。","衔杯乐圣千秋节，击鼓迎冬大有年。","忽忆捧觞供玉座，不知身在雪山边。"]},{"t":"光福塘上","f":"七言律诗","c":["指点炊烟隔莽苍，午餐应可寄前庄。","鸡声人语小家乐，木叶草花深巷香。","春去已空衣尚絮，雨来何晚稻初芒。","祗今农事村村急，第一先陂贮水塘。"]},{"t":"再出东郊","f":"五言律诗","c":["晚景增年惯，官身作客谙。","大都缘偶熟，岂是性能堪。","昔者开三径，他时老一龛。","越溪亲种竹，芸绿想毵毵。"]},{"t":"再用前韵","f":"七言律诗","c":["休论今昨总皆非，世味诚甘与我违。","蜀道虽如履平地，杜鹃终劝不如归。","三冬自苦坐毛颖，一梦微官陪螱飞。","夜久南枝翻倦鹊，茫茫月白众星稀。"]},{"t":"再次喜雨诗韵以表随车之应","f":"七言律诗","c":["仙篆驱龙效水灵，佛螺吹梵演云经。","何烦础汗生蒸润，便借炉薰作晦冥。","一念故应周法界，万神元不隔明庭。","昌时圭璧形声应，不似周时莫我听。"]},{"t":"再次韵述怀约子文见过","f":"七言律诗","c":["灰木心形雪满头，鹤凫长短不悲忧。","瓮畦纯白无机械，蒲局枭卢任博投。","若爱陶陶并兀兀，先须莫莫与休休。","个中情话谁能共，鸡黍明当挽仲由。"]},{"t":"再到虎丘","f":"七言律诗","c":["不过溪桥又两年，偶随筇竹访幽禅。","有缘再踏云岩路，无处重寻石井泉。","拟辍半山分座住，先携一枕借床眠。","觉来饱吃红莲饭，正是塘东稻熟天。"]},{"t":"再渡胥口","f":"七言律诗","c":["古来此地快蓬心，天绕明湖日照临。","一雁云平时隐现，两山波动对浮沉。","衰髯都共荻花老，醉面不如枫叶深。","罾户钓徒来问讯，去年盟在肯重寻。"]},{"t":"再游天平有怀旧事且得卓庵之处呈寿老","f":"七言律诗","c":["访旧光阴二十年，残僧相对两依然。","木兰已老无花发，石竹依前有麝眠。","万户直须龟手药，一龛何用买山钱。","从今半座须分我，共说昏昏一觉禅。"]},{"t":"再题青城山","f":"七言律诗","c":["万里清游不暇慵，双旌换得一枝筇。","来从井络直西路，上到江源第一峰。","海内閒身输我佚，山中佳气为人浓。","题诗试刻岩前石，付与他年藓晕重。"]},{"t":"再题瓶中梅花","f":"七言律诗","c":["园林篱落冻芳尘，南北枝间玉蕊皴。","风袂挽香虽淡薄，月窗横影已精神。","雪霜春事年年晚，今古诗情日日新。","铁石如翁犹索句，真成嚼蜡对横陈。"]},{"t":"刘德修少卿避暑惠山因便寄赠","f":"七言律诗","c":["鸣凤朝阳尺五天，匆匆忽过白鸥边。","遥怜海内无双士，独酌人间第二泉。","决去君今身似叶，赠行谁有笔如椽。","老夫但祝重相见，未拟消魂赋黯然。"]},{"t":"合江亭隔江望瑶林庄梅盛开过江访之马上哦此","f":"五言律诗","c":["何处春能早，疏篱限激湍。","竹间烟雪迥，马上晚香寒。","唤渡聊相觅，巡檐得细看。","极知微雨意，未许日烘残。"]},{"t":"孙真人庵","f":"七言律诗","c":["何处仙翁旧隐居，青莲巉绝似蓬壶。","云深未到淘朱洞，雨小先寻炼药炉。","涧下草香疑可饵，林间虎伏试教呼。","閒身尽办供薪水，定肯分山一半无。"]},{"t":"孙黄渡","f":"七言律诗","c":["舍舟从陆更间关，径仄仍荒亦未乾。","棘刺近人牢闭眼，泥涂兀马紧扶鞍。","茶山盗薮路程恶，麦垄人家怀抱宽。","担仆舆夫尽劬瘁，病翁那得更加餐。"]},{"t":"安乡县西晚泊","f":"五言律诗","c":["水阔鸟乌倦，墟寒童仆饥。","一湾村县过，百折暮江迟。","晓梦孤灯见，春阴病骨知。","简书宁不畏，旅力奈先疲。"]},{"t":"州宅堂前荷花","f":"七言律诗","c":["凌波仙子静中芳，也带酣红学醉妆。","有意十分开晓露，无情一饷敛斜阳。","泥根玉雪元无染，风叶青葱亦自香。","想得石湖花正好，接天云锦画船凉。"]},{"t":"戏答澹庵小偈","f":"五言律诗","c":["莫问前程事，漂然海上舟。","命乖逢鬼国，缘合遇蓬丘。","毕竟非身计，俱成错路头。","故乡随脚是，流浪不知休。"]},{"t":"戏题索桥","f":"五言律诗","c":["织簟匀铺面，排绳强架空。","染人高晒帛，猎户远张罿。","薄薄难承雨，翻翻不受风。","何时将蜀客，东下看垂虹。"]},{"t":"戏赠勤长老","f":"七言律诗","c":["从君挥麈演金乘，我已无心缠葛藤。","第一圆通三鼓梦，大千世界一窗灯。","罢参柏子庭前意，权作梅花树下僧。","饭饱閒行复閒坐，人间有味是无能。"]},{"t":"早发竹下","f":"七言律诗","c":["结束晨装破小寒，跨鞍聊得散疲顽。","行冲薄薄轻轻雾，看放重重叠叠山。","碧穗炊烟当树直，绿纹溪水趁桥弯。","清禽百啭似迎客，正在有情无思间。"]},{"t":"早衰","f":"七言律诗","c":["早衰头脑已冬烘，信拙心情似苦空。","僚旧姓名多健忘，家人长短总佯聋。","一窗煖日棋声里，四壁寒灯药气中。","晚景只消如此过，不堪拈出教儿童。"]},{"t":"早衰不寐","f":"七言律诗","c":["官事拘挛似力田，作劳归晚意茫然。","按摩合体俱非我，展转通宵似远年。","一叟披衣惟兀坐，群儿得枕便佳眠。","人生元是华胥客，休向迷涂更著鞭。"]},{"t":"有会而作","f":"七言律诗","c":["拙是天资懒是真，本来何用戒香薰。","强阳气尽冥恩怨，杜德机深泯见闻。","念动即时漂鬼国，心空随处走魔军。","室中已自空诸有，休负天机与地文。"]},{"t":"有怀石湖旧隐","f":"七言律诗","c":["浩荡沙鸥久倦飞，摧颓枥马不胜鞿。","官中风月常虚度，梦里关山或暂归。","橘社十年霜欲饱，鲈江一雨水应肥。","冷云著地塘蒲晚，谁为披蓑煖钓矶。"]},{"t":"有怀龚养正","f":"五言律诗","c":["好在楚龚子，秋来情话稀。","昨承书素说，行侍板舆归。","烟水潮平棹，风霜岁晚衣。","几时真访戴，莫待雪花霏。"]},{"t":"有感今昔二首 其二","f":"七言律诗","c":["飘风骤雨谩惊春，扫荡何烦臂屈伸。","天识不衷宜不恕，神歆非类即非仁。","休雠地下枯鱼骨，且斗尊前健犊身。","静看可怜还可笑，香山宁是幸灾人。"]},{"t":"有感今昔二首 其一","f":"七言律诗","c":["阳春白雪雅音希，俚耳冬烘辄笑嗤。","麋见丽姬翻决骤，鸟闻韶乐却忧悲。","烂奚轻薄人何敢，伏猎荒唐自不知。","蚓窍蝇鸣莫嘲诮，彭亨菌蠢正当时。"]},{"t":"次伯安推官赠别韵","f":"七言律诗","c":["交情弥岁竟匆匆，短棹归寻一亩宫。","塞责文书容我懒，及时杯酒赖君同。","披云峰顶城头月，揽秀堂前扇里风。","千里音书慰离索，莫言天远费鳞鸿。"]},{"t":"次胡经仲知丞赠别韵","f":"七言律诗","c":["先生有道抗浮云，拄颊看山意最真。","霜鬓不堪痟首疾，翠蛾常作捧心颦。","官如斯立蓝田小，家似渊明栗里贫。","俯仰别来蓂荚换，只今谁与话情亲。"]},{"t":"次黄必先主簿同年赠别韵二首 其二","f":"七言律诗","c":["山郭官閒得烂游，弥年还往话绸缪。","西园剥栗催奴课，东院寻梅劝客留。","笔下修锋千首富，谈间和气两眉浮。","别来怅望何时见，谩上重城谩上楼。"]},{"t":"次景琳录事赠别韵","f":"七言律诗","c":["放船鸣橹便秦吴，送别空烦长者车。","宿雾锁山常羃羃，断云将雨忽疏疏。","高城五岭花深处，短棹三江木落初。","赖得溪流通尺素，蒲根仍有一双鱼。"]},{"t":"次韵子文","f":"七言律诗","c":["幻尘久已破狐涎，身世谁能料鼠肝。","暮夜雨收千嶂出，晨朝风卷四维宽。","我今无事不如梦，君岂有心犹觅安。","但促小槽添压石，龙头珠滴夜珊珊。"]},{"t":"次韵子文雨后思归","f":"七言律诗","c":["断云将雨洗松篁，昨夜痴龙起蛰藏。","人自无情孤乐事，天犹有意作新凉。","尊前不见凌波袜，楼下空闻拜月香。","万事安能尽如愿，且来相伴压糟床。"]},{"t":"次韵子文客舍小楼","f":"七言律诗","c":["客里仍携一束书，闭门虹气自凌虚。","未闻光范延珠履，谁向甘泉从玉车。","散尽生涯千答布，收将文价百车渠。","淹留且结西湖夏，同到秋风赋遂初。"]},{"t":"次韵子永夜雨","f":"五言律诗","c":["办作长愁客，工哦苦雨吟。","挑灯今夕意，欹枕故园心。","漏屋疏疏滴，空檐细细斟。","相过巷南北，屐齿怕泥深。"]},{"t":"次韵子永雪后见赠","f":"七言律诗","c":["雪瓴待伴半阴晴，竟日檐冰溜雨声。","九陌泥乾尘未动，南山石露塔犹明。","稍闻吉语占农事，便觉归心胜宦情。","想得秫田来岁好，瓦盆加酿灌愁城。"]},{"t":"次韵太守出郊","f":"七言律诗","c":["晓装缇骑踏芳辰，江为安澜露浥尘。","棨戟前驱留住月，笙箫后备带行春。","鱼龙水面金杯满，鸾鹤山头綵笔新。","闻道将军宽礼数，不辞酩酊吐车茵。"]},{"t":"次韵尹少稷察院九宫坛斋宿","f":"五言律诗","c":["草草驰三里，萧萧共一餐。","吏方绵礼蕝，公自将诗坛。","隙月窥床近，窗风刮坐寒。","鸦鸣未忍散，端为四并难。"]},{"t":"次韵王夷仲正字同游成氏园","f":"七言律诗","c":["秀岩堂上玉东西，把酒登临望眼迷。","天宇四垂粘地近，海山一抹带潮低。","绝知客好无尘事，聊记吾曾有醉题。","倚赖群仙联姓字，他年谁敢一杴泥。"]},{"t":"次韵王浚明用时举苦热韵见赠","f":"七言律诗","c":["暑窗当午思昏昏，雷起千峰睡不闻。","铄石谁能招楚魄，斲冰我欲访湘君。","年华只合加餐饭，事业休工刺绣文。","赖有两贤南北巷，岁寒幽谷共兰薰。"]},{"t":"次韵平江韩子师侍郎见寄三首 其一","f":"七言律诗","c":["自古四愁湘水深，谁将城郭启山林。","有情碧嶂团栾绕，无数朱楼缥缈临。","蚺鼓揭天惊客坐，象鍪航海厌蛮琛。","三千客路长安远，故旧书来直万金。"]},{"t":"次韵平江韩子师侍郎见寄三首 其二","f":"七言律诗","c":["灵泉杖屦浙江头，经济长怀尚典州。","堂上读书朝气爽，台前呼月海光浮。","交情尺素勤双鲤，笔力枯松挽万牛。","已把三章翻乐府，为君击节变蛮讴。"]},{"t":"次韵平江韩子师侍郎见寄三首 其三","f":"七言律诗","c":["前年冲雪过双溪，风帽泥鞯骑吹随。","烂醉依前逢锦瑟，好音惟是欠黄鹂。","功名未试玉璜玦，离别频倾金屈卮。","畴昔北征烦吉梦，南征合有梦归时。"]},{"t":"次韵正夫游王园会者六人","f":"七言律诗","c":["丘园窈窕复崎岖，草木生香景倍殊。","花下百杯齐物我，云边一眼尽江湖。","不知朱户趑趄者，能胜青山放浪无。","六逸萧然真可画，为君题作竹溪图。"]},{"t":"次韵边公辨","f":"七言律诗","c":["错落参旗罥竹梢，柴荆临水闭蓬蒿。","春风吹晓玉蟾堕，秾露洗空银汉高。","双鹊绕枝应也倦，一蛩吟壁已能豪。","新秋只合添诗兴，莫学潘郎叹二毛。"]},{"t":"次韵同年杨廷秀使君寄题石湖 其一","f":"七言律诗","c":["仪凰当瑞九韶成，何事栖鸾滞碧城。","公退萧然真吏隐，文名藉甚更诗声。","句从月胁天心得，笔与冰瓯雪椀清。","书到石湖春亦到，平堤梅影縠纹生。"]},{"t":"次韵同年杨廷秀使君寄题石湖 其二","f":"七言律诗","c":["半世轻随出岫云，如今归作卧云人。","小山有赋招游子，大块无私佚老身。","禅版梦中千嶂晓，鬓丝风里万花春。","新年社瓮鹅黄满，剩醉田头紫领巾。"]},{"t":"次韵同年杨使君回自毗陵同泛石湖舟中见赠 其一","f":"五言律诗","c":["客舫中流下，人家夹岸看。","洛花堆锦煖，吴藕镂冰寒。","莫厌清欢暂，须知后会难。","小诗烦本事，任秃綵毫端。"]},{"t":"次韵许季韶通判水乡席上","f":"七言律诗","c":["青山绿浦竹间明，彷佛苕溪好处行。","解愠风来如故旧，催诗雨作要将迎。","休兵幕府乌鸢乐，熟稻边城鼓笛声。","摹写个中须綵笔，句成仍挟水云清。"]},{"t":"次韵许季韶通判雪观席上","f":"七言律诗","c":["把酒临风瑞露倾，琼浆何用谒云英。","捲帘雨脚银丝挂，倚杖江头绿涨生。","岭海一凉苏暑病，山林千籁试秋声。","兹游奇绝忘羁宦，惭愧烟中短棹横。"]},{"t":"次韵严子文见寄","f":"七言律诗","c":["雨云浓压屋山头，诗句端来写客忧。","雷电已将金薤取，琼瑶难报木瓜投。","无心我正铭三住，有意君堪话四休。","何日寻春同步屧，先教啼鸟说来由。"]},{"t":"次韵严子文旅中见赠","f":"七言律诗","c":["杯中畴昔共江天，倾座新诗报警联。","海浦寸心空共月，京华双鬓各凋年。","交情敢说同方友，句法甘从弟子员。","有意数从文字饮，何须争著祖生鞭。"]},{"t":"次韵即席","f":"七言律诗","c":["留连银烛照金荷，肠断华年一掷梭。","月姊有情难独夜，天孙无赖早斜河。","晶晶霜瓦寒生粟，衮衮风帏细涌波。","鸹鹖晓啼鸣鹊散，许多佳景奈愁何。"]},{"t":"次韵李子永见访二首 其二","f":"五言律诗","c":["有意能停棹，多情易忆家。","清诗穿月胁，远梦绕天涯。","雨蝶衣濡粉，秋蚊喙吐花。","新凉宜小驻，谈笑有丹砂。"]},{"t":"次韵李子永见访二首 其一","f":"五言律诗","c":["混俗休超俗，居家似出家。","有为皆影事，无念即生涯。","莫觅安心法，翻成捏目花。","作糜须谷粟，千劫漫炊砂。"]},{"t":"次韵杨同年秘监见寄二首 其二","f":"七言律诗","c":["吾衰长愧接舆狂，忙里何心领燕香。","尘土簿书憎铁研，水云蓑笠傲金章。","论文无伴法孤起，访旧有情书数行。","何日却同湖上醉，露帏宵幄为君张。"]},{"t":"次韵杨同年秘监见寄二首 其一","f":"七言律诗","c":["瘴云岚雨几时归，应把周南视九夷。","旧说鬼神惊落笔，新传狐兔骇搴旗。","韶江石老箫音在，庾岭梅残驿使迟。","自古朱弦清庙具，莫贪鹏海看天池。"]},{"t":"次韵陈季邻户部旦过庵","f":"七言律诗","c":["宦游触处似悬匏，北岳南山想献嘲。","指手百年休铸铁，盖头一把暂诛茅。","玉京岁晚梧桐落，水国霜清橘柚包。","飞锡已随归梦去，何人顶上鹊成巢。"]},{"t":"次韵宗伟阅番乐","f":"七言律诗","c":["十日閒愁昼掩关，起寻一笑共清欢。","罢休诗社工夫淡，洗净书生气味酸。","尽遣馀钱付桑落，莫随短梦到槐安。","绣靴画鼓留花住，剩舞春风小契丹。"]},{"t":"次韵宗伟温伯","f":"七言律诗","c":["冉冉流光迫岁馀，青林日夜向人疏。","雨滋岩桂重堆粟，风折庭蕉又献书。","逋客解兰思婉娩，先生弹铗厌清虚。","一尘不立浑输我，即境心安是故庐。"]},{"t":"次韵朋元久雨","f":"七言律诗","c":["谁酿愁䨧玉宇间，都缘梅子要斓斑。","腾腾困思午犹梦，扰扰奔云风未还。","休问满城骑马滑，不妨长日闭门闲。","今朝晴色熹微似，乾鹊飞来语屋山。"]},{"t":"次韵朋元游王氏园","f":"七言律诗","c":["联翩步屧翠微间，回首红尘自鲜欢。","捲地雨添千涧急，拥门云锁两山盘。","绝怜茶笋能留客，仍喜蛙声不在官。","雪白杨梅消息未，重来应至麦秋寒。"]},{"t":"次韵林子章阻浅留滞","f":"七言律诗","c":["客行端似未归云，指点璿杓几易辰。","喜有风花黄作晕，似闻溪涨绿生鳞。","我从走俗言无味，君已鸣文笔有神。","绣段炳然空辱赠，急翻缇袭扫蛛尘。"]},{"t":"次韵知郡安抚九日南楼宴集三首 其三","f":"七言律诗","c":["斯民邹鲁更丰年，雅道凄凉见此贤。","万陇登禾新霁色，千村鸣柝旧寒烟。","锵金绝世诗情妙，倚剑凌空隶墨鲜。","珍重北窗山六六，使君名与汝俱传。"]},{"t":"次韵知郡安抚九日南楼宴集三首 其一","f":"七言律诗","c":["双旌暮捲小舂容，画栋云生笑语中。","但觉山光侵酒绿，不知日脚染溪红。","控临缥缈疑无地，指点虚无欲驭风。","谁遣玉蟾催骑吹，归来人影在朦胧。"]},{"t":"次韵知郡安抚九日南楼宴集三首 其二","f":"七言律诗","c":["珠履参陪北海觞，仍邀拥节旧中郎。","碧城香雾连天暝，黄叶霜风捲地凉。","佳节转头论聚散，清波从古阅兴亡。","明年重把茱萸醉，公在丛霄贡玉堂。"]},{"t":"次韵知郡安抚元夕赏倅厅红梅三首 其二","f":"七言律诗","c":["真色生香绝世逢，烟光池面两溶溶。","楚邻不待施朱好，虢国翻嫌傅粉浓。","晴日暧云春照耀，温风霁月夜舂容。","酒阑且驻纱笼看，慢破团团一壁龙。"]},{"t":"次韵知郡安抚元夕赏倅厅红梅三首 其一","f":"七言律诗","c":["春入林梢一再风，破寒匀染费天工。","虽然媚荡新妆别，只与横斜旧格同。","午枕乍醒铅粉退，晓奁初罢蜡脂融。","后来颜色休论似，夹路漫山取次红。"]},{"t":"次韵知郡安抚元夕赏倅厅红梅三首 其三","f":"七言律诗","c":["司花一笑为谁开，知道朱幡得得来。","疏影有情当洞户，蔫香无语堕空杯。","风生翰墨留连看，月入笙歌次第催。","来岁如今翻旧唱，五云丛里望三台。"]},{"t":"次韵郑校书参议留别","f":"五言律诗","c":["年丰方共庆，岁晚客他之。","吏事朝还暮，人生合复离。","江山残梦破，风月片帆移。","后会吾衰矣，桑榆一茧丝。"]},{"t":"次韵胡邦衡秘监","f":"五言律诗","c":["斯言向来立，千古敢疵瑕。","有命孤蓬转，何心劲箭加。","人穷名满世，天定客还家。","回首冥恩怨，虚空不著花。"]},{"t":"次韵蚤蚊","f":"七言律诗","c":["羽虫么魔塞区寰，造化胡为弗疾顽。","长养污泥草木处，纵横大地山河间。","夜声雷动人力屈，秋喙花开天理还。","但愿江湖无白鸟，何须金鼎铸神奸。"]},{"t":"次韵赵德庄吏部休沐","f":"五言律诗","c":["窈窕新堂好，委蛇夜直还。","遥知欹帽发，正奈捲帘山。","门外客姑去，窗前人对闲。","谁能乌帽底，尘土涴朱颜。"]},{"t":"次韵项丈雪诗","f":"七言律诗","c":["兜罗世界三千刹，重璧楼台十二城。","云暗峨嵋封古色，日曛鳷鹊溜春声。","莫将蕉叶评摩诘，且撚梅花慰广平。","更忆缑山可怜夜，怯寒谁与伴调笙。"]},{"t":"次韵唐幼度客中幼度相别数年复会于钱塘湖上","f":"七言律诗","c":["西湖冰泮绿生鳞，料峭东风欲中人。","花片不禁寒食雨，鬓丝犹那涌金春。","江山契阔诗情在，京洛追随客梦新。","唤取歌声不愁思，为君吹水引杯频。"]},{"t":"次韵耿时举王直之夜坐","f":"五言律诗","c":["庭叶翻翻闹，灯花粟粟秾。","关山千里雁，风雨满城钟。","陇上新登谷，江头旧熄烽。","今年吾计得，安稳读三冬。"]},{"t":"次韵袁起岩甘雨即日应祈","f":"七言律诗","c":["天遣贤侯惠此州，随车一雨缓千忧。","药寮坐看云穿屋，莲棹归将叶盖头。","三伏凉来那易得，百年饱外更何求。","合词但祝为霖手，早侍薰弦十二旒。"]},{"t":"次韵袁起岩送示郡沼双莲图","f":"七言律诗","c":["珠渊玉水折方员，涌出双莲照酒边。","压倒小湖三级草，增光后沼两重莲。","苕华名字元相并，桃叶根株本自连。","好把吴歈翻楚些，杨荷新曲胜当年。"]},{"t":"次韵袁起岩喜雨","f":"七言律诗","c":["使君精祷动仙灵，月御俄从毕噣经。","昨夜云头随皂盖，今朝雨脚挂青冥。","池光拍岸浮州宅，湖面粘天涨洞庭。","剩采吴歈歌岁事，传归击壤调中听。"]},{"t":"次韵袁起岩提刑游金焦二山二首 其二","f":"词","c":["忆曾归自雪边州，帆落中?小系舟。","食蛤坐来期汗漫，驾鸿飞去揖浮丘。","卧游久矣无登览，辱赠跫然有唱酬。","寂寞东皋舒啸后，为君濡笔赋临流。"]},{"t":"次韵袁起岩提刑游金焦二山二首 其一","f":"七言律诗","c":["二山巉绝照南州，俯看千樯总芥舟。","日脚镕金浮巨浸，波声翻雪撼高丘。","钟闻两岸诗无敌，口吸西江话已酬。","别有英雄怀古意，他年击楫誓中流。"]},{"t":"次韵袁起岩瑞麦此麦两岐山黄熟其间又出一青枝亦已秀实传记所未载也","f":"七言律诗","c":["民和神福固其宜，况有仁先四者施。","吴稻即看收再熟，周牟先已秀双岐。","蕙风半老黄金穗，梅雨重春绿玉枝。","乐不可支聊发咏，田间日日是芳时。"]},{"t":"次韵起岩喜雪","f":"七言律诗","c":["吹成一雪便吹残，风伯无端岂坐悭。","夜报飞花平瓦垄，晓惊疏雨落檐间。","休教冻解鱼龙水，更待诚通虎豹关。","准拟姑苏台上看，春前三度老青山。"]},{"t":"次韵温伯纳凉","f":"五言律诗","c":["日斜犹畏暑，吏退合偷閒。","霞散红绡薄，溪回碧玉弯。","伴人惟羽扇，娱客欠风鬟。","且复哦新句，相嘲饭颗山。"]},{"t":"次韵温伯城上","f":"五言律诗","c":["闭户成痴坐，扶藜得意行。","楼台浮霁色，市井碎春声。","雪尽小桥出，烟消千嶂生。","病多无脚力，遥羡落鸿轻。"]},{"t":"次韵温伯谋归","f":"七言律诗","c":["官路驱驰易折肱，官曹随处是愁城。","随风片叶乡心动，过雨千峰病眼明。","一脔何须尝世味，寸田久已废吾耕。","羡君早作归欤计，屈指从今几合并。"]},{"t":"次韵答吴江周县尉饮垂虹见寄","f":"七言律诗","c":["垂虹亭上角巾倾，鼍怒龙吟醉不听。","安得对君浮大白，想应嗤我汗新青。","梦魂舞蝶随春草，时节宾鸿点暮汀。","湖海扁舟须及健，莫教明月照星星。"]},{"t":"次韵谢李叔玠追路送笋","f":"五言律诗","c":["堕地锦绷茁，解衣温玉姿。","来偿食竹债，大胜伏雌炊。","少日羹藜子，老来煨芋师。","盘餐登异味，指动已先知。"]},{"t":"次韵韩无咎右司上巳泛湖","f":"七言律诗","c":["休沐辰良不待晴，径称闲客此闲行。","春衫欺雨任教冷，病眼得山元自明。","抹黛浓岚围坐晚，揉蓝新渌没篙清。","栖鸦未到催归去，想被东风笑薄情。"]},{"t":"次韵甄云卿晚登浮丘亭","f":"七言律诗","c":["宾筵旧压三千客，燕榭新高十二城。","泼墨云头连树暗，垂丝雨脚过溪生。","葛巾羽扇吾身健，雪椀冰瓯子句清。","从此相从须痛饮，故应此事胜公荣。"]},{"t":"次韵蜀客西归者来过石湖并寄成都旧僚","f":"七言律诗","c":["走遍尘埃倦鸟还，故乡元在水云间。","黄粱饭里梦魂醒，青箬笠前身世閒。","鸥鹭飞来俱玉立，松篁岁晚各苍颜。","岷峨交旧如相问，铁锁无扃任客攀。"]},{"t":"次韵魏端仁感怀俳谐体","f":"七言律诗","c":["浪学骚人赋远游，大千何事不悠悠。","酒边点检颜红在，镜里端详鬓雪羞。","过眼浮云翻覆易，曲肱短梦破除休。","孤烟落日冥鸿去，心更冥鸿最上头。"]},{"t":"江安道中","f":"七言律诗","c":["秾绿连村荔子丹，瘴云将雨暗前湾。","张旗且喜三滩驶，叱驭曾惊九折艰。","泸水舟閒迷古渡，马湖碑缺伴荒山。","威名功业吾何有，无事飘飘犯百蛮。"]},{"t":"池州九日用杜牧之齐山韵","f":"七言律诗","c":["年年佳节歌式微，秋浦片帆还欲飞。","万里蜀魂思远道，九歌楚调送将归。","杯中山影分秋色，木末江光借夕晖。","细撚黄花一枝尽，霏霏金屑满征衣。"]},{"t":"自咏瘦悴","f":"五言律诗","c":["皮下多无肉，秋来瘦不禁。","骨棱春焙銙，筋蹙海山沉。","虮虱从何有，蚊蝇枉见侵。","惟馀老筇杖，相伴两虚心。"]},{"t":"西楼夜坐","f":"七言律诗","c":["抗尘怀抱若为宽，绕屋蛙声亦在官。","岩桂无香秋遂晚，江鲈有约岁将寒。","文书散乱嘲痴绝，灯火凄清语夜阑。","病倦百骸非复我，但思禅板与蒲团。"]},{"t":"西楼秋晚","f":"七言律诗","c":["楼前处处长秋苔，俛仰璿杓又欲回。","残暑已随梁燕去，小春应为海棠来。","客愁天远诗无托，吏案山横睡有媒。","晴日满窗凫鹜散，巴童来按鸭炉灰。"]},{"t":"过鄱阳湖次游子明韵","f":"七言律诗","c":["春工酿雪无端密，大块囊风不肯收。","休问巉岩与欹侧，我今弟靡共波流。","野鹰兀兀平沙上，折苇萧萧古渡头。","满眼荒寒底处所，令人肠断五湖舟。"]},{"t":"问月堂酌别","f":"七言律诗","c":["半明灯火话悲酸，此会情知后会难。","四海宦游多聚散，一生情事足悲欢。","鬓丝今夜不多黑，酒量彻明无数宽。","醉梦登舟都不记，但闻风雨满江寒。"]},{"t":"阴寒终日兀坐","f":"七言律诗","c":["东风微解缀檐冰，仍喜朝来井水清。","腊浅得春全未煖，雪悭和雨最难晴。","小窗日煖犹棋局，穷巷更深尚屐声。","莫把摧颓嫌暮景，且将閒散替劳生。"]},{"t":"但能之提刑相别十年自曲江远寄二诗叙旧良厚次韵为谢亦以首章奉怀略道湘南分携故事末篇自述年来衰病不复故吾也 其二","f":"七言律诗","c":["濩落枵虚似瓠壶，新添雪鬓与霜须。","也知病叟形容变，非是仙儒骨相癯。","岁晚山林如自献，年丰田野亦多娱。","无端拙恙妨清乐，未许扁舟到五湖。"]},{"t":"但能之提刑相别十年自曲江远寄二诗叙旧良厚次韵为谢亦以首章奉怀略道湘南分携故事末篇自述年来衰病不复故吾也 其一","f":"七言律诗","c":["忆昔骖鸾识俊英，朱幡绣斧尽能名。","书随庾岭一枝寄，句挟韶江九奏成。","吴粤交驰清夜梦，参辰不隔故人情。","何时重醉金槽曲，一洗阳关别恨平。"]},{"t":"体中不佳偶书","f":"七言律诗","c":["生平人比似维摩，试比尪孱不啻过。","旧摘衰髯今雪遍，频揩病眼转花多。","从来世味聊复尔，此去官身如老何。","收拾颓龄加药饵，尚堪风月对婆娑。"]},{"t":"馀杭道中","f":"七言律诗","c":["落花流水浅深红，尽日帆飞绣浪中。","桑眼迷离应欠雨，麦须骚杀已禁风。","牛羊路杳千山合，鸡犬村深一径通。","五柳能消多许地，客程何苦镇匆匆。"]},{"t":"初入大峨","f":"七言律诗","c":["烟霞沉痼不须医，此去真同汗漫期。","曾款上清临大面，仍从太白问峨眉。","山中缘法如今熟，世上功名自古痴。","剩作画图归挂壁，他年犹欲卧游之。"]},{"t":"初入巫峡","f":"五言律诗","c":["钻火巴东岸，摐金峡口船。","束江崖欲合，漱石水多漩。","卓午三竿日，中间一罅天。","伟哉神禹迹，疏凿此山川。"]},{"t":"初冬","f":"五言律诗","c":["节令坚冰始，民风古意淳。","星行穷少皞，正岁述咸秦。","俗礼嫌端拜，头风强裹巾。","红泥炉畔酒，从此卜亲邻。"]},{"t":"初归石湖","f":"七言律诗","c":["晓雾朝暾绀碧烘，横塘西岸越城东。","行人半出稻花上，宿鹭孤明菱叶中。","信脚自能知旧路，惊心时复认邻翁。","当时手种斜桥柳，无限鸣蜩翠扫空。"]},{"t":"初约邻人至石湖","f":"七言律诗","c":["窈窕崎岖学种园，此生丘壑是前缘。","隔篱日上浮天水，当户山横匝地烟。","春入葑田芦绽笋，雨倾沙岸竹垂鞭。","荒寒未办招君醉，且吸湖光当酒泉。"]},{"t":"判命坡","f":"七言律诗","c":["钻天岭上已飞魂，判命坡前更骇闻。","侧足三分垂坏磴，举头一握到孤云。","微生敢列千金子，后福犹几万石君。","早晚北窗寻噩梦，故应含笑老榆枌。"]},{"t":"别后寄题汉嘉月榭","f":"七言律诗","c":["隐吏诗情卜筑幽，同年惜别劝淹留。","试倾万景湖亭酒，来看半轮江月秋。","川路虽长犹共此，夜船空载且归休。","碧岩胜处频回首，好事谁能更小楼。"]},{"t":"别拟太上皇帝挽歌词六首 其六","f":"五言律诗","c":["甫贺蝇传赦，俄惊鹤驭风。","首山铜鼎就，前殿玉卮空。","日岂挥戈及，天无鍊石功。","如何千万寿，不待九龄终。"]},{"t":"别拟太上皇帝挽歌词六首 其五","f":"五言律诗","c":["舞羽修文后，投歌讲艺时。","天章云汉丽，国典日星垂。","麟绝仲尼笔，猿啼神禹碑。","伤心河洛水，无处问龙龟。"]},{"t":"别拟太上皇帝挽歌词六首 其四","f":"五言律诗","c":["与子传神器，承家得圣人。","阶庭天下养，壶峤海中春。","四叶斑衣乐，三加玉册新。","寿宫如帝所，何必上霄晨。"]},{"t":"别拟太上皇帝挽歌词六首 其三","f":"五言律诗","c":["敛福开皇极，储祥握赤符。","寇降千猰㺄，胡拜两单于。","洗甲民安枕，垂衣国覆盂。","有生何以报，寿域亘绵区。"]},{"t":"别拟太上皇帝挽歌词六首 其二","f":"五言律诗","c":["大孝天孚佑，精诚敌可摧。","龙輴迁座至，騩驭及泉回。","永祐千章木，慈宁万寿杯。","古今无此事，绝德诏方来。"]},{"t":"别拟太上皇帝挽歌词六首 其一","f":"五言律诗","c":["身济投艰业，时乘拨乱机。","荆榛荒帐殿，风雨颒戎衣。","有日临黄道，无星彗紫微。","至今淮海上，犹咏六龙飞。"]},{"t":"巫山县","f":"五言律诗","c":["借马巫山县，盘舟掉石滩。","梅肥朝雨细，茶老暮烟寒。","门对高唐起，江从滟滪难。","流堆三尺在，旅梦一枝安。"]},{"t":"张正字母夫人朱氏挽词","f":"五言律诗","c":["蘋藻仪邦媛，诗书了岁华。","籯金宁遗子，群玉竟传家。","厚施心无斁，浮生自有涯。","空馀报恩子，三载亦苴麻。"]},{"t":"怀归寄题小艇","f":"七言律诗","c":["日出尘生万劫忙，可怜虚费隙驹光。","若教閒里工夫到，始觉淡中滋味长。","岁晚角巾思芋栗，年来手版愧耕桑。","松风萝月须相信，春水深时上野航。"]},{"t":"李正之提点行至郴用予忙字韵寄和答","f":"五言律诗","c":["天涯逢我病，秋晚送君忙。","感慨交情厚，留连别恨长。","宾筵犹雪观，客路已云庄。","摇落郴江路，应须忆醉乡。"]},{"t":"李郎中挽词二首 其二","f":"五言律诗","c":["忆昔单车使，惟君勇辅行。","马隤招共载，羝乳约同盟。","老去长怀旧，悲来遽隔生。","故人凋落尽，衰涕不胜横。"]},{"t":"李郎中挽词二首 其一","f":"五言律诗","c":["剧郡思贤牧，名曹失望郎。","六参能几日，两鬓未全霜。","霅水新阡远，桐川旧隐荒。","绝怜垂白母，泪血独还乡。"]},{"t":"李翚知县作亭西湖上余用东坡语名之曰饮绿遂为胜概","f":"七言律诗","c":["芷葺莲巢唤客游，芦鞭席帽为君留。","未论吹水堪添酒，且要移床学枕流。","乍霁却阴梅酿雨，暂暄还冷麦催秋。","石湖也似西湖好，烦向苍烟问白鸥。"]},{"t":"李粹伯侍御挽词二首 其二","f":"五言律诗","c":["公昔参敷纳，人期到辨章。","珠光空月皎，玉气忽虹藏。","岁晚东方骑，生平北海觞。","玳簪风雨散，几客奠楸行。"]},{"t":"李粹伯侍御挽词二首 其一","f":"五言律诗","c":["奕叶邯郸后，乘骢第一人。","交情多旧雨，到处有阳春。","磊落功名意，摧颓梦幻身。","黄垆高可隐，何地著经纶。"]},{"t":"杨君居士挽词","f":"五言律诗","c":["孝至兰陔茂，身脩梓里恭。","名场儿中鹄，姻党婿乘龙。","驹隙惊年运，蝉嫣有庆钟。","幽光定无憾，丰刻妙形容。"]},{"t":"步入衡山","f":"七言律诗","c":["应有人家住隔溪，绿阴亭午但闻鸡。","松根当路龙筋瘦，竹笋漫山凤尾齐。","墨染深云犹似瘴，丝来小雨不成泥。","更无骑吹喧相逐，散诞閒身信马蹄。"]},{"t":"没冰铺晚晴月出晓复大雨上漏下湿不堪其忧","f":"七言律诗","c":["晚色熹微煖似薰，儿童欢喜走相闻。","无端星月照湿土，依旧山川生雨云。","旅枕梦寒涔屋漏，征衫潮润冷炉熏。","快晴信是行人愿，又恐田家曝背耘。"]},{"t":"灼艾","f":"五言律诗","c":["血忌详涓日，尻神谨避方。","艾求真伏道，穴按古明堂。","谢去群巫祝，胜如几药汤。","起来成独笑，一病搅千忙。"]},{"t":"甬东道院午坐","f":"七言律诗","c":["一夜西风转酒旗，午馀残暑不多时。","绿荷半蚀霜前叶，丹桂全封雨后枝。","忙里有诗偿日课，老来无赋为秋悲。","梳头小隶那知此，强向窗前数鬓丝。"]},{"t":"社山放船","f":"七言律诗","c":["社下钟声送客船，凌波挝鼓转沧湾。","横烟袅处鸡豚社，落日浓边橘柚山。","八表茫茫孤鸟去，万生扰扰一舟閒。","湖心行路平如镜，陆地风波却险艰。"]},{"t":"花山村舍","f":"五言律诗","c":["潦退滩滩露，沙虚岸岸颓。","涧声穿竹去，云影过山来。","柳菌粘枝住，桑花共叶开。","庵庐少来往，门巷湿苍苔。"]},{"t":"进思堂夜坐怀故山","f":"七言律诗","c":["尘事潮来不可推，身如病鹤强毰毸。","簿书遮断寻诗路，风雨惊残问月杯。","想得竹门无客到，直须雪夜有船回。","鲈乡望眼双明处，袛欠凌霄万仞台。"]},{"t":"闰月四日石湖众芳烂熳","f":"七言律诗","c":["北垞南冈总是家，儿童随逐任驩哗。","开尝腊尾蒸来酒，点数春头接过花。","尽把园林蒙锦绣，多添门户锁烟霞。","杖藜想被春风笑，扶却衰翁管物华。"]},{"t":"陈侍御园坐上","f":"七言律诗","c":["愁眼逢欢春水明，诗情得酒春云生。","花梢蝴蝶作团去，竹里鹁鸠相对鸣。","邂逅浮生此日好，缠绵俗累何时轻。","擘笺沫墨乏奇句，擪笛当筵惭妙声。"]},{"t":"周畏知司直得湖南帅属过吴门复用己丑年倡和韵赠别","f":"七言律诗","c":["邂逅婆娑失少年，剧谈抵掌尚超然。","君犹拄笏看山去，我且披蓑听雨眠。","京洛分襟疑后会，江吴把酒悟前缘。","暂来忽去都如梦，疑是陈卿竹叶船。"]},{"t":"周德万携孥赴龙舒法曹道过水阳相见留别女弟","f":"七言律诗","c":["草草相逢小驻船，一杯和泪饮江天。","妹孤忍使行千里，兄老那堪别数年。","马转不容吾怅望，橹鸣肯为汝留连。","神如相此俱强健，绿发归来慰眼前。"]},{"t":"咏吴中二灯 其一 琉璃毬","f":"五言律诗","c":["龙综缫冰茧，鱼文镂玉英。","雨丝风外绉，云网日边明。","叠晕重重见，分光面面呈。","不深閒里趣，争识个中情。"]},{"t":"咏怀自嘲","f":"五言律诗","c":["檐溜春犹冻，门扉晚未开。","退閒惊客至，衰懒怕书来。","日日教浇竹，朝朝遣探梅。","园丁应窃笑，犹自说心灰。"]},{"t":"夜发昆山","f":"五言律诗","c":["岁寒人墐户，霜重独登舟。","弱橹摇孤梦，疏篷盖百忧。","但吟今不乐，岂计几宜休。","惭愧沙湖月，年年照薄游。"]},{"t":"夜泊归州州有宋玉宅、昭君台","f":"五言律诗","c":["旧国风烟古，新凉瘴疠清。","片云将客梦，微月照江声。","细和悲秋赋，遥怜出塞情。","荒山饮阀阅，儿女擅嘉名。"]},{"t":"宝公祈雨感应用陈申公韵赋诗为谢","f":"七言律诗","c":["膴原龟坼暮春时，夹路炉薰共祷祠。","唤起云头千嶂涌，飞来雨脚万丝垂。","无情梅坞犹红绽，有意秧田尽绿滋。","大施门开须满愿，愿均此施匝天涯。"]},{"t":"府公录示和提干喜雨之作辄次元韵","f":"七言律诗","c":["雨挟潮痕涨具区，流渠决决绕幽居。","荷锄日课都忘倦，抱瓮天机本不疏。","且喜水平昌谷稻，莫教雷假介休车。","老翁饱外还多事，更把林间种树书。"]},{"t":"明日分弓亭按阅再用西楼韵","f":"七言律诗","c":["眼看白露点苍苔，岁月飞流首屡回。","老去读书随忘却，醉中得句若飞来。","闻鸡午夜犹能舞，射雉西郊不用媒。","自笑支离聊复尔，丹心元未十分灰。"]},{"t":"明日至邻水又雨","f":"五言律诗","c":["昨日方无雨，今朝又不晴。","满山皆屐齿，随处有泉声。","颇怪阴霖差，应催老病成。","泥涂千骑士，与我共劳生。"]},{"t":"枕上","f":"七言律诗","c":["一枕经春似宿酲，三衾投晓尚凄清。","残更未尽鸦先起，虚幌无声鼠自惊。","久病厌闻铜鼎沸，不眠惟望纸窗明。","摧颓岂是功名具，烧药炉边过此生。"]},{"t":"枕上作","f":"五言律诗","c":["绕枕蚊相聒，翻釭鼠自忙。","早衰秋梦乱，不寝晓更长。","赋拟骚人屈，吟成病客庄。","安心无可觅，随处且为乡。"]},{"t":"枕上闻雪复作方以为喜起岩再示新诗复次韵","f":"七言律诗","c":["三白何忧稼穑艰，天于玉粒未吾悭。","不知夜色明空外，但觉朝寒到梦间。","谁子骑驴吟灞上，何人跋马客蓝关。","争如睡熟蒲团上，静听饥鸦啄屋山。"]},{"t":"林元复挽诗","f":"七言律诗","c":["胸次峥嵘满贮书，十年名字满江湖。","张公阅世诗千首，扬子传家宅一区。","谩道春风须得意，那知秋雨不成珠。","自从雪魄冰魂散，鲁国今谁更服儒。"]},{"t":"林夫人挽词","f":"七言律诗","c":["翰墨门阑正岿然，故应婉娩亦儒先。","与闻古学三千礼，能诵家书四百篇。","卜协妫姜占永世，梦呼辰巳谶凋年。","班姬合有遗文在，后日从容访孟坚。"]},{"t":"林屋洞","f":"七言律诗","c":["击水抟风浪雪翻，烟销日出见仙村。","旧知浮玉北堂路，今到幽墟三洞门。","石燕翾飞遮炬火，金龙深阻护嵌根。","宝钟灵鼓何须叩，庭柱宵晨已默存。"]},{"t":"泊湘江鱼口滩","f":"七言律诗","c":["知时社燕语樯竿，游子奔波自鲜欢。","趁客卖鱼双桨急，隔林沽酒小旗寒。","潇湘浑似日南落，岳麓已从天外看。","薄暮滩前收百丈，卧闻三老报平安。"]},{"t":"画工李友直为余作冰天桂海二图冰天画使北虏渡黄河时桂海画游佛子岩道中也戏题","f":"七言律诗","c":["许国无功浪著鞭，天教饱识汉山川。","酒边蛮舞花低帽，梦里胡笳雪没鞯。","收拾桑榆身老矣，追随萍梗意茫然。","明朝重上归田奏，更放岷江万里船。"]},{"t":"范村雪后","f":"五言律诗","c":["习气犹馀烬，钟情未湿灰。","忍寒贪看雪，讳老强寻梅。","熨贴愁眉展，勾般笑口开。","直疑身健在，时有句飞来。"]},{"t":"金山岭","f":"五言律诗","c":["阪峻身频偃，崖深首屡回。","云浮平地出，路拂半天来。","但阅关山过，都忘岁月催。","湘南初上马，犹插早春梅。"]},{"t":"雨后田舍书事再用前韵","f":"七言律诗","c":["村村畦圃艺新区，处处田庐葺旧居。","熟透晚梅红的皪，展开新箨翠扶疏。","向来矜寡犹遗秉，此去污邪又满车。","谁解续经如鲁史，为将连岁有年书。"]},{"t":"青城山会庆建福宫宫旧名丈人观，予为请于朝，赐今名。入山前数日，敕书至自行在，予就设醮以祝圣人寿云","f":"七言律诗","c":["墨诏东来汹驿传，璇题金榜照山川。","祥开圣代千秋节，响动仙都九室天。","触石涌云埋紫逻，流金飞火烛苍巅。","祗应老宅庞眉客，长记新宫锡号年。"]},{"t":"青城县何子方使君同年园池","f":"七言律诗","c":["桤塍芋垄意中行，浩荡薰风不计程。","雨脚背人归玉垒，江声随马入青城。","五桥今日新知路，千佛当年旧缀名。","水竹光中同一笑，丐君荷露濯尘缨。"]},{"t":"顷自吏部郎去国时独同舍赵友益追路送诗数月友益得仪真过吴江次元韵招之","f":"七言律诗","c":["东风分袂省西廊，袖有明珠照客航。","道义有情通出处，文章无地著炎凉。","君今犹把一麾去，我敢倦锄三径荒。","邂逅天涯如梦寐，肯来相对话更长。"]},{"t":"亲戚小集","f":"七言律诗","c":["避湿违寒不出门，一冬未省正冠巾。","月从雪后皆奇夜，天向梅边有别春。","秉烛登临空语旧，拥炉情味莫怀新。","荣华势利输人惯，赢得尊前现在身。"]},{"t":"信笔","f":"七言律诗","c":["天地同浮水上萍，羲娥迭耀案头萤。","山中名器两芒屩，花下友朋双玉瓶。","童子昔曾誇了了，主翁今但诺醒醒。","归田赢得多无事，输与诸公汗简青。"]},{"t":"南徐道中","f":"七言律诗","c":["生憎行路与心违，又逐孤帆擘浪飞。","吴岫涌云穿望眼，楚江浮月冷征衣。","长歌悲似垂垂泪，短梦纷如草草归。","若有一廛供闭户，肯将篾舫换柴扉。"]},{"t":"南塘寒食书事","f":"五言律诗","c":["埂外新陂绿，冈头宿烧红。","裹鱼蒸菜把，馈鸭锁筠笼。","酒侣晨相命，歌场夜不空。","土风并节物，不与故乡同。"]},{"t":"南楼望雪","f":"五言律诗","c":["夜月流瑶圃，春风满玉都。","篱疏先剥落，树密正模糊。","乱点横烟雁，惊啼失木乌。","醉魂方浩荡，风袖不支梧。"]},{"t":"垫江县","f":"七言律诗","c":["青泥没髁仆频惊，黄涨平桥马不行。","旧雨云招新雨至，高田水入下田鸣。","百年心事终怀土，一日身谋且望晴。","休入忠州争米市，暝鸦同宿垫江城。"]},{"t":"复自姑苏过宛陵至邓步出陆","f":"七言律诗","c":["浆家馈食槿为藩，酒市停骖竹庑门。","红树亭亭栖晚照，黄茅杳杳被高原。","饮溪有迹于菟过，掠草如飞朴渥翻。","车轨如沟平地少，饱帆天镜忆江村。"]},{"t":"复作耳鸣二首 其一","f":"七言律诗","c":["至音岂寂透希夷，珍重幽田为发挥。","妙用何关新卷叶，圆通自有倒闻机。","梦中鼓响生千偈，觉后舂声失百非。","寄语爵阴吞贼道，玉床安稳坐朱衣。"]},{"t":"复作耳鸣二首 其二","f":"七言律诗","c":["东极空歌下始青，西方宝网奏韶英。","不须路入兜元国，自有音闻室筏城。","牛蚁谁知床下斗，鸡蝇任向梦中鸣。","如今却笑难陀种，无耳何劳强听声。"]},{"t":"姚夫人挽歌词","f":"五言律诗","c":["衿帨虞鳏后，诗书孟母邻。","高怀琴意静，晚福诏恩新。","自古悲风木，于今咏涧蘋。","松铭无溢美，百世考坚珉。"]},{"t":"客中呈幼度","f":"七言律诗","c":["手板头衔意已慵，墨池书枕兴无穷。","酿泥深巷五更雨，吹酒小楼三面风。","草色有无春最好，客心去住水长东。","今朝合有家书到，昨夜灯花缀玉虫。"]},{"t":"将至石湖道中书事","f":"五言律诗","c":["水绿鸥边涨，天青雁外晴。","柳堤随草远，麦陇带桑平。","白道吴新郭，苍烟越故城。","稍闻鸡犬闹，僮仆想来迎。"]},{"t":"幽栖","f":"七言律诗","c":["幽栖先自懒衣裳，秋暑薰肌汗似浆。","对客绪言多勉强，谋家生事总荒唐。","蚤眠不待星当户，晚饭常占日半墙。","莫道閒中无外慕，朝朝屈指望新凉。"]},{"t":"思归再用枕上韵","f":"五言律诗","c":["老觉触事懒，病添归计忙。","行年心已化，畴昔意空长。","五柳栗里宅，百花锦城庄。","何时去检校，一棹水云乡。"]},{"t":"故太夫人章氏挽词二首 其二","f":"五言律诗","c":["积庆今如许，生儿得宁馨。","轲亲躬授教，韦子世传经。","寿斝明卿月，安舆拱使星。","市桥何处在，梦断一溪青。"]},{"t":"故太夫人章氏挽词二首 其一","f":"五言律诗","c":["洵美相门裔，有齐邦媛贤。","藻蘋南涧下，萱竹北堂前。","孝敬三从谨，哀荣五福全。","松铭诸健笔，题作晋陵阡。"]},{"t":"施元光在昆山病中远寄长句次韵答之","f":"七言律诗","c":["四海飘蓬客舍边，几多云水与风烟。","绝无膂力驱长辔，空有孤忠誓大川。","参井忽随征马上，斗牛应挂故山前。","亲交情话知何许，诗到天涯喜欲颠。"]},{"t":"春后微雪一宿而晴","f":"七言律诗","c":["綵胜金幡换物华，垂垂天意晚平沙。","东君未破含春蕊，青女先飞剪水花。","夜逐回风鸣瓦垄，晓成疏雨滴檐牙。","朝暾不与同云便，烘作晴空万缕霞。"]},{"t":"春前十日作","f":"七言律诗","c":["腊浅犹赊十日春，官忙长愧百年身。","雪催未动诗无力，愁遣还来酒不神。","节物何曾欺老病，书生自惯说悲辛。","终朝戚促成何事，今古纷纷一窖尘。"]},{"t":"春晚","f":"楚辞体","c":["荒园萧瑟懒追随，舞燕啼莺各自私。","窗下日长多得睡，尊前花老不供诗。","吾衰久矣双蓬鬓，归去来兮一钓丝。","想见篱东春涨动，小舟无伴柳丝垂。"]},{"t":"春晚即事留游子明王仲显","f":"五言律诗","c":["绣地红千点，平桥绿一篙。","楝花来石首，谷雨熟樱桃。","笑我生尘甑，惭君有意袍。","故人能少驻，门径久蓬蒿。"]},{"t":"春晚卧病故事都废闻西门种柳已成而燕宫海棠亦烂熳矣","f":"七言律诗","c":["轩窗深窈似禅房，竟日虚明袅断香。","诗债无边春已老，睡魔有约昼初长。","市桥烟雨应官柳，墟苑池台自海棠。","游骑行歌莫相笑，遨头六结已龟藏。"]},{"t":"春朝早起","f":"五言律诗","c":["莫笑眠常早，还怜起不迟。","秾香温夜气，小雨湿春姿。","瘦比中年甚，寒惟病骨知。","羡渠儿女健，绕屋探南枝。"]},{"t":"洪景卢内翰使还入境以诗迓之","f":"七言律诗","c":["玉帛干戈汹并驰，孤臣叱驭触危机。","关山无极申舟去，天地有情苏武归。","汉月凌秋随使节，胡尘捲暑避征衣。","国人渴望公颜色，为报褰帷入帝畿。"]},{"t":"独游虎跑泉小庵","f":"五言律诗","c":["苔径弯环入，茅斋取次成。","蔓花缘壁起，閒草上阶生。","宿雨松篁色，新晴燕雀声。","筒泉烹御米，聊共老僧倾。"]},{"t":"癸水亭落成示坐客长老之记曰癸水绕东城永不见刀兵余作亭于水上其详具记中","f":"七言律诗","c":["天将福地巩严城，形胜山川表里明。","旧说桂林无瘴气，今知漓水辟刀兵。","云深铜柱边声乐，月冷珠池海面平。","愿挽江流接河汉，为君直北洗欃枪。"]},{"t":"秋老四境雨已沛然晚坐筹边楼方议祈晴楼下忽有东界农民数十人诉山田却要雨须长吏致祷感之作诗","f":"七言律诗","c":["岁晚羁怀有所思，秋来病骨最先知。","镜中公案已甘老，纸上课程休讳痴。","西堰颇闻江涨急，东山犹说雨来迟。","锦城乐事知多少，忧旱忧霖蹙尽眉。"]},{"t":"秋雨快晴静胜堂席上","f":"七言律诗","c":["一笑憧憧雁鹜行，簿书堆里赋秋阳。","心如坠絮沾泥懒，身似飞泉激石忙。","雨后蹲鸱先稻熟，霜前浮蚁斗枨香。","天涯节物遮愁眼，且复随乡便入乡。"]},{"t":"秋前风雨顿凉","f":"七言律诗","c":["秋期如约不须催，雨脚风声两快哉。","但得暑光如寇退，不辞老景似潮来。","酒杯触拨诗情动，书卷招邀病眼开。","明日更凉吾已卜，暮云浑作乱峰堆。"]},{"t":"秭归县","f":"五言律诗","c":["永日贪程客，长年吊古诗。","悲秋荒故宅，负石惨空祠。","峻壁鸦翻倦，高畬麦秀迟。","穷山熊绎国，偪仄建邦时。"]},{"t":"胡长文给事挽词三首 其三","f":"五言律诗","c":["姻馆交情厚，官联事契长。","鸣珂朝并辔，秉独夜传觞。","何意塘蒲晚，翻哦薤露章。","羸躯如可强，恸哭踞湖冈。"]},{"t":"胡长文给事挽词三首 其二","f":"五言律诗","c":["许国心如日，还家鬓未星。","四并供燕喜，万事付撄宁。","东牖樽犹湛，南园醉不醒。","凄凉招隐路，苔蚀履綦青。"]},{"t":"胡长文给事挽词三首 其一","f":"五言律诗","c":["结绶参高妙，垂绅侍邃清。","紫荷青琐闼，玉帐锦官城。","行矣超龟列，终然郁骥程。","寂寥经济事，遗恨入铭旌。"]},{"t":"胡长民监元挽词","f":"五言律诗","c":["太学齑盐旧，中吴翰墨声。","关山题柱笔，风露读书檠。","夜雨绿荷破，孤坟丹桂生。","空将擅场手，往记玉楼成。"]},{"t":"说虎轩夜坐","f":"七言律诗","c":["白云深处卧痴顽，挂起东窗水月宽。","但得好诗生眼底，何须宝刹现毫端。","一身莫作官身想，万境都如梦境看。","蟹舍邻翁能日醉，呼来分与一蒲团。"]},{"t":"送文处厚归蜀类试","f":"七言律诗","c":["万里东来万里归，正怜寡妇与孤儿。","死生契阔心如铁，风雨飘摇鬓欲丝。","早集汉庭陪振鹭，莫留岷岭恋蹲鸱。","故家零落今馀几，门户非君更属谁。"]},{"t":"送文季高倅兴元","f":"七言律诗","c":["素衣京洛怅成缁，青鬓江吴喜未丝。","烛暗不眠谈旧事，酒阑作恶问行期。","琴书情话须亲戚，风雨残春更别离。","屈指归来重一笑，扫除门巷著旌麾。"]},{"t":"送王纯白郎中赴闽漕","f":"七言律诗","c":["声利场中百战鏖，今谁勇退似公豪。","缓寻南粤千山路，先破西兴百尺涛。","平日曼容嫌禄厚，他年文本叹官高。","才名政尔归安往，富贵追踪未可逃。"]},{"t":"送吴元茂丞浦江","f":"七言律诗","c":["玉笋翻乘县佐车，飘然不肯待新除。","才名已被人争说，官薄何妨计小疏。","忆昨西湖同我载，从今南浦望君书。","遥知敛板趋风后，始觉丞哉果负予。"]},{"t":"送吴智叔检详直中秘使闽","f":"七言律诗","c":["抗章襆被岂公难，已说高风立懦顽。","客路莫嫌河畔草，直庐须爱道家山。","秋生莲浦船初泛，春满茶溪骑趣还。","却访故人西府旧，定烦书札堕田间。"]},{"t":"送张真甫中书奉祠归蜀","f":"七言律诗","c":["种成桃李恰新阴，忽忆家山丛桂林。","客路莫嫌归计拙，春江争似骇机深。","一封朝奏钧天梦，万里江行魏阙心。","后日还朝饱风露，黑头应有雪丝侵。"]},{"t":"送李仲镇宰溧阳","f":"七言律诗","c":["相逢已叹十年迟，冷淡贫交又语离。","玉笋换班通籍后，黄梅催雨送帆时。","月岩家世犹为县，金濑溪山好赋诗。","唤起酸寒孟东野，倒流三峡洗馀悲。"]},{"t":"送汪圣锡侍郎帅福唐","f":"七言律诗","c":["承明才入又南州，重见旌旗照柁楼。","道义平生无捷径，风波随处有虚舟。","如公未可违文石，稽古何妨欠碧油。","我亦登门烦著录，此行无力为王留。"]},{"t":"送汪仲嘉待制奉祠归四明分韵得论字","f":"七言律诗","c":["丹霄碧海眇高鶱，厌直承明却自论。","宝马十年听漏箭，扁舟一雨看潮痕。","侍臣相忆松门远，归客还怜菊径存。","清润要非山泽相，又烦一札下云根。"]},{"t":"送陈天予大监同年使闽","f":"七言律诗","c":["春关十载记英游，蚤喜时才近采旒。","夷路著鞭方逸驾，急流回首忽扁舟。","云霄正稳君犹去，尘土无边我合休。","问讯后车容客否，茶山荔浦看南州。"]},{"t":"送陈朋元赴溧阳","f":"七言律诗","c":["九畹滋兰静自芳，啁啾谁复认孤凰。","风流岁晚嫌杯酒，文字功深得鬓霜。","敛板君犹能俛仰，倚楼吾敢计行藏。","船开便作江南客，天色无情更雁行。"]},{"t":"送周子充左史奉祠归庐陵","f":"七言律诗","c":["黄鹄飘然下九关，江船载月客俱还。","名高岂是孤臣愿，身退聊开壮士颜。","倾盖当年真旦暮，沾巾明日有河山。","后期淹速都难料，相对犹怜鬓未斑。"]},{"t":"送周直夫教授归永嘉","f":"七言律诗","c":["青灯相对话儒酸，老去羁游自鲜欢。","昨夜榕溪三寸雨，今朝桂岭十分寒。","知心海内向来少，解手天涯良独难。","一笑不须论聚散，少焉吾亦跨归鞍。"]},{"t":"送周畏知司直归上饶待次","f":"七言律诗","c":["漫郎西笑费三年，故业新闻腹果然。","长麈剧谈抽茧绪，短檠细字缀蚕眠。","频惊陆海风波梦，未了京尘粥饭缘。","后日重来应访旧，五湖烟浪有渔船。"]},{"t":"送施元光赴江西幕府","f":"七言律诗","c":["镇南旌旆照江皋，入幕如今客最高。","月暗秋城稀击柝，云飞朝栋剩挥毫。","长亭酒尽歌三叠，半夜溪深雨一篙。","莫恋阳关更西路，九关归路踏金鳌。"]},{"t":"送洪内翰使虏二首 其二","f":"七言律诗","c":["峨冠方侍玉舆香，双节飘然照大荒。","正倚先生令赵重，宁容骄子诧胡强。","天教忠信行区脱，人许功名上太常。","试卜和羹知未晚，归来烟雨正梅黄。"]},{"t":"送洪内翰使虏二首 其一","f":"七言律诗","c":["郊庙熙成霈率滨，罪如猾夏亦维新。","边烽已却来南虏，使节犹烦第一人。","遥想穹庐占汉月，便呼重译布唐春。","单于若问公家世，说与麒麟画老臣。"]},{"t":"送洪景卢内翰使虏二首 其二","f":"七言律诗","c":["檄到中原杀气销，穹庐那敢说天骄。","今年蕃始来和汉，即日燕当远徙辽。","北土未乾遗老泪，西陵应望孝孙朝。","著鞭往矣功名会，麟阁丹青上九霄。"]},{"t":"送洪景卢内翰使虏二首 其一","f":"七言律诗","c":["金章玉色照离亭，战伐和亲决此行。","国有威灵双节重，家传忠义一身轻。","平生海内文场伯，今日胸中武库兵。","万里往来公有相，淮濆阴德贯神明。"]},{"t":"送赵从善少卿将漕淮东","f":"七言律诗","c":["玉笋风标右汉廷，起家聊直使车星。","古来将相多头黑，此去功名尚鬓青。","披草两年南北巷，折梅明日短长亭。","门前车辙从今少，寂寞柴荆且暂扃。"]},{"t":"重九日行营寿藏之地","f":"七言律诗","c":["家山随处可行楸，荷锸携壶似醉刘。","纵有千年铁门限，终须一个土镘头。","三轮世界犹灰劫，四大形骸强首丘。","蝼蚁乌鸢何厚薄，临风拊掌菊花秋。"]},{"t":"重九独坐玉麟堂","f":"七言律诗","c":["江上西风动所思，又将清赏负东篱。","年年客路黄花酒，日日乡心白雁诗。","笼月秦淮无旧曲，驰烟钟阜有新移。","人生笑口真稀阔，况值官忙闵雨时。"]},{"t":"重九独登赏心亭","f":"七言律诗","c":["谁教佳节滞天涯，强展愁眉管物华。","每岁有诗题白雁，今年无酒对黄花。","悠悠造化占斜日，草草登临记落霞。","宇宙此身元是客，不须弹铗更思家。"]},{"t":"重九赏心亭登高","f":"七言律诗","c":["忆随书剑此徘徊，投老双旌重把杯。","绿鬓风前无几在，黄花雨后不多开。","丰年江陇青黄遍，落日淮山紫翠来。","饮罢此身犹是客，乡心却附晚潮回。"]},{"t":"重阳九经堂作","f":"七言律诗","c":["俗间佳节自匆匆，老去悲秋又客中。","青嶂捲帘三面月，黄花吹鬓几丝风。","十年故国新栽柳，万里他乡旧转蓬。","谁与安排今夜梦，片帆飞到小篱东。"]},{"t":"闻威州诸羌退听边事已宁少城筹边楼阑槛修葺亦毕工作诗寄权制帅高子长","f":"七言律诗","c":["筹边楼上美髯翁，赤白囊飞笑语中。","勃律天西元采玉，蓬婆雪外昨分弓。","踏筵舞罢平阑月，横槊诗成满袖风。","诸校各能歌破阵，何须琴里听平戎。"]},{"t":"除夜","f":"七言律诗","c":["婪尾杯残雪满簪，床头历日费光阴。","故山巧入忙中梦，新岁尤关客里心。","乌鹊倦时三匝绕，鹪鹩稳处一枝深。","劳生佚老寻常事，从政那堪力不任。"]},{"t":"食罢书字","f":"五言律诗","c":["甲子霖涔雨，东南湿蛰风。","荔枝梅子绿，豆蔻杏花红。","扪腹蛮茶快，扶头老酒中。","荒隅经岁客，土俗渐相通。"]},{"t":"凌云九顶","f":"七言律诗","c":["聊为东坡载酒游，万龛迎我到峰头。","江摇九顶风雷过，云抹三峨日夜浮。","古佛临流都坐断，行人识路亦归休。","酣酣午枕眠方丈，一笑閒身始自由。"]},{"t":"夏夜","f":"五言律诗","c":["脉脉惜佳夜，泠泠成浩歌。","傥无诗句子，将奈月明何。","露气濛花重，风声入树多。","清欢殊未办，桂影堕江波。"]},{"t":"家人子辈往石湖检校暮归","f":"五言律诗","c":["南浦回春棹，东城掩暮扉。","儿修鸡栅了，女挈菜篮归。","风力虽欺酒，花香尚染衣。","衰翁牢守舍，肠断钓鱼矶。"]},{"t":"峰门岭遇雨泊梁山","f":"七言律诗","c":["穷乡谁与话悲酸，驻马看云强自宽。","酒力无端妨宿病，诗情不浅任尘官。","虎狼地僻炊烟晚，风雨天低夏木寒。","行尽峰门千万丈，梁山鼓角报平安。"]},{"t":"恭州夜泊","f":"七言律诗","c":["蓖山硗确强田畴，村落熙然粟豆秋。","翠竹江村非锦里，青溪夜月已渝州。","小楼高下依盘石，弱缆西东战急流。","入峡初程风物异，布裙跣妇总垂瘤。"]},{"t":"晓枕闻雨","f":"五言律诗","c":["暗淡更残景，低迷病酒怀。","剔灯寒作伴，添被厚如埋。","胆冷都无梦，心空却似斋。","地炉煎粥沸，听作雨鸣阶。"]},{"t":"晓起","f":"五言律诗","c":["黠鼠缘铃索，饥鸦啄井栏。","不眠秋漏近，多病晓屏寒。","咄咄渠何怪，休休我自阑。","牙门朝日上，箫鼓报平安。"]},{"t":"晓起闻雨","f":"七言律诗","c":["老来稍喜睡魔清，兀坐枯株听五更。","萧索轮囷怜烛烬，飞扬跋扈厌蚊声。","登高事了从教雨，刈熟人忙却要晴。","莫道西成便无虑，大须浓日㬠香粳。"]},{"t":"浙东舟中","f":"五言律诗","c":["处处槿樊圃，家家桃庑门。","鱼盐临水市，烟火隔江村。","雨过张帆重，潮来汲井浑。","弯跧短篷底，休说两朱轓。"]},{"t":"浙东参政寄示会稽蓬莱阁诗轴次韵寄题二首 其二","f":"七言律诗","c":["鳌背飞来绀碧浮，人间还有小蓬丘。","不须击水三千里，已压中天十二楼。","羽驾旧曾将梦到，芝田今合为公秋。","玉霄有客方东望，竟欲乘风驭气游。"]},{"t":"海云回按骁骑于城北原时有吐番出没大渡河上","f":"七言律诗","c":["古道风沙捲夕霏，小江烟浪皱春漪。","天于麦垄犹悭雪，人向梅梢大欠诗。","顿辔青骊飞脱兔，离弦白羽啸寒鸱。","牙门列校俱剽锐，檄与河边秃发知。"]},{"t":"留游子明","f":"五言律诗","c":["得得跫音喜，匆匆笑口开。","牢愁攻易破，归梦挽难回。","我已疏茶椀，君今减酒杯。","不知乘兴棹，更得几回来。"]},{"t":"病中三偈 其一","f":"七言律诗","c":["扰扰随流无定期，波停浪息始应知。","一尘不偶同归处，四海无亲独步时。","苦相打通俱入妙，病缘才入更何疑。","霜清木落千山露，笑杀东风叶满枝。"]},{"t":"病中夜坐","f":"五言律诗","c":["村巷秋舂远，禅房夕磬深。","饥蚊常绕鬓，暗鼠忽鸣琴。","薄薄寒相中，棱棱瘦不禁。","时成洛下咏，却似越人吟。"]},{"t":"病中夜坐呈致远","f":"七言律诗","c":["似雾如烟夜气浮，鹤鸣惊睡起搔头。","含风竹影淡留月，著雨蛩声深怨秋。","万事心空痴已惯，百骸岁晚病相投。","便当采药西山去，脚力蹒跚怕远游。"]},{"t":"病中闻西园新花已茂及竹径皆成而海棠亦未过","f":"七言律诗","c":["梅坞桃蹊斫竹初，三旬高卧信音疏。","春虽与病无交涉，雨莫将花便破除。","祗合蘧蘧随梦去，何须咄咄向空书。","颇闻蜀锦犹相待，去岁今朝已雪如。"]},{"t":"离池阳十里清溪口复阻风","f":"七言律诗","c":["恰从秋浦挂籧篨，又泊清溪十里馀。","愁水愁风吹帽后，作云作雨授衣初。","远寻草市沽新酒，牢闭篷窗理旧书。","行路阻艰催老病，骚骚落雪满晨梳。"]},{"t":"离巫山好晴午后入瞿唐关憩高斋半日","f":"七言律诗","c":["一昨题诗诉苦霖，果然连夜卷曾阴。","尽收行雨瑶姬赐，不徇世情巫峡心。","喜鹊满枝朝日淡，哀猿何处宿云深。","水门山径高斋外，一枕清风屏万金。"]},{"t":"积雨蒸润体中不佳颇思故居之乐戏书呈子文","f":"七言律诗","c":["门外泥深蘸马鞍，墨云未放四维宽。","前山忽接后山暗，暑雨全如秋雨寒。","梦里江湖三叹息，醉中天地一凭阑。","斗升留滞休惆怅，枳棘从来著凤鸾。"]},{"t":"致一斋述事","f":"七言律诗","c":["文书烟海困浮沉，不觉盘跚百病侵。","偶问客年惊我老，忽闻莺语叹春深。","今朝麦粒黄堪面，几日秧田绿似针。","除却一犁春雨足，眼前无物可关心。"]},{"t":"致政孙从政挽词","f":"五言律诗","c":["丈室推居士，安居称老夫。","回骸桑下饿，续命辙中枯。","重道几三叟，轻财似八厨。","欲知潜德报，青紫付遗孤。"]},{"t":"致政承奉卢君挽词二首 其二","f":"七言律诗","c":["纯孝当年有护持，赤眉那敢近姜诗。","眼看庭玉成名后，身及堂萱未老时。","湖海青鞋惊断梦，风霜丹旐挂新悲。","尊前五客今谁在，愁绝庐山十段奇。"]},{"t":"致政承奉卢君挽词二首 其一","f":"七言律诗","c":["泮水桥门识太平，归来霜鬓老柴荆。","淹中学邃方成传，谷口名高岂待卿。","黄壤无情埋玉树，青衫有道胜金籯。","襄阳耆旧今萧索，惟有松风到晚清。"]},{"t":"舫斋晚憩","f":"五言律诗","c":["心作万缘起，境生千劫忙。","谁同油幕静，独对篆烟长。","有尽天魔力，无穷海印光。","雨馀弦月上，尘界本清凉。"]},{"t":"请佛阁晚望雪山数十峰如烂晃耀暑光中","f":"七言律诗","c":["累块苍然是九州，大千起灭更悠悠。","雪光正照天西角，日影长浮雨上头。","峰顶何曾知六月，尘间想已别三秋。","佛毫似欲留人住，横野金桥晚未收。"]},{"t":"请息斋书事三首 其二","f":"七言律诗","c":["刻木牵丝罢戏场，祭馀雨后两相忘。","门虽有雀尚廷尉，食已无鱼休孟尝。","虱里趋时真是贼，虎中宣力任为伥。","篱东舍北谁情话，鸡语鸥盟意却长。"]},{"t":"请息斋书事三首 其三","f":"七言律诗","c":["聚蚋醯边闹似雷，乞儿争背向寒灰。","长平失势见何晚，栗里息交归去来。","休问江湖鱼有沫，但蕲云水鹤无媒。","岩扉岫幌牢扃钥，不是渔樵不与开。"]},{"t":"请息斋书事三首 其一","f":"七言律诗","c":["覆雨翻云转手成，纷纷轻薄可怜生。","天无寒暑无时令，人不炎凉不世情。","栩栩算来俱蝶梦，喈喈能有几鸡鸣。","冰山侧畔红尘涨，不隔瑶台月露清。"]},{"t":"起岩又送立春日再得雪诗亦次韵","f":"七言律诗","c":["十分佳景媚冬残，好事天心不复悭。","已遣梅花斜竹外，更飘瑞叶向人间。","渔蓑晚色都堪画，羌笛春光亦度关。","想得东风来处路，白银宫阙锁三山。"]},{"t":"逍遥楼席上赠张邦达教授张癸未省闱门生也同年进士俱会楼上者七人","f":"七言律诗","c":["畴昔金门看选贤，一星终矣半英躔。","谁怜蛮府清池句，不著南山捷径鞭。","作者七人茅瘴地，肃霜九月菊残天。","浮生聚散如风雨，同倚东楼岂偶然。"]},{"t":"高淳道中","f":"七言律诗","c":["路入高淳麦更深，草泥沾润马骎骎。","雨归陇首云凝黛，日漏山腰石渗金。","老柳不春花自蔓，古祠无壁树空阴。","一箪定属前村店，衮衮炊烟起竹林。"]},{"t":"偶书","f":"七言律诗","c":["太行巫峡费车舟，休向沧溟认一沤。","日下冰山难把玩，雨中土偶任漂流。","元无刻木牵丝技，但合收绳卷索休。","惟有酒缸并饭甑，却须粳秫十分收。"]},{"t":"偶书","f":"七言律诗","c":["捏目华中影现身，有为皆妄懒方真。","已甘搰搰勤为圃，休向滔滔苦问津。","书至五千空拄腹，钱非十万不通神。","君看汗简沉碑者，随水随风几窖尘。"]},{"t":"偶至东堂","f":"七言律诗","c":["岸帻萧骚雪满簪，一閒真是直千金。","归来栗里多情话，病后香山少醉吟。","久坐蒲团蕉叶放，閒拖藜杖藓花深。","饥时吃饭慵时睡，何暇将心更觅心。"]},{"t":"偶然","f":"七言律诗","c":["偶然寸木压岑楼，且放渠侬出一头。","鲸漫横江无奈蚁，鹏虽运海不如鸠。","躬当自厚人何责，世已相违我莫求。","石火光中争底事，宽颜收拾付东流。"]},{"t":"娑罗平","f":"七言律诗","c":["仙圣飞行此是家，路逢真境但惊呀。","神农尝外尽灵药，天女散馀多异花。","岚雨逼衣寒似铁，冰泉炊米硬于沙。","峰头事事殊尘世，缺甃跳梁笑井蛙。"]},{"t":"宿义林院","f":"五言律诗","c":["暝气昏如雨，禅房冷似冰。","竹间东岭月，松杪上方灯。","惊鹘盘金刹，流萤拂玉绳。","明朝穷脚力，连夜斩崖藤。"]},{"t":"宿长芦寺方丈","f":"五言律诗","c":["塔庙新浮水，汀洲旧布金。","聊凭一苇力，与障万波侵。","帆影窥门近，钟声出院深。","夜阑雷破梦，欹枕听潮音。"]},{"t":"寄虎丘范长老","f":"七言律诗","c":["谁云簪绂坐成禽，亦漫为官漫好音。","身已备尝生老病，心何曾住去来今。","一波不动月空照，万籁无情风自吟。","持此东归似同志，故应分我半山林。"]},{"t":"寄溧阳陈朋元明府约秋末过之","f":"七言律诗","c":["海内交情两断金，一官分袂阻登临。","书来恰值看云眼，梦往谁知共月心。","道义只今无捷径，溪山依旧有清音。","西风满棹蒲帆饱，秉烛相寻语夜深。"]},{"t":"寄题永新张教授无尽藏","f":"七言律诗","c":["古来谁道四并难，对境心空著处安。","要识见闻无尽藏，先除梦幻有为观。","削平丘垤孤峰峻，撤去籓篱万象宽。","快诵老坡秋望赋，大千风月一毫端。"]},{"t":"寄题商华叔心远堂用卷中韵","f":"五言律诗","c":["示我新诗卷，知君遁俗情。","安流视巫峡，灰劫笑昆明。","徽外夜弦语，瓮头春蚁生。","蓝桥即仙窟，何况有云英。"]},{"t":"寄赠致远并呈现老","f":"七言律诗","c":["草草家风节物新，从来忧病不忧贫。","琴书稍觉浮生误，香火惟知此事真。","室里谈空思二士，花间对影谩三人。","袛愁卢李分携后，别有箜篌一曲春。"]},{"t":"密室惫坐","f":"七言律诗","c":["如许头颅莫振矜，但寻曲几与枯藤。","馀生不直一弹指，此病宁论三折肱。","何处丹房痴候火，谁家筹室强传灯。","本来识字耕夫耳，今乃仍添百不能。"]},{"t":"得寿藏于先陇之傍俯酬素愿感慨交怀","f":"七言律诗","c":["密迩松楸地一隅，会心何必问青乌。","亢宗虽愧镇公子，没世尚从先大夫。","京兆汉阡贤问望，邢山郑冢俭规模。","家庭遗训焄蒿在，不学邠卿画古图。"]},{"t":"惊蛰家人子辈为易疏帘","f":"七言律诗","c":["二分春色到穷阎，儿女祈翁出滞淹。","幽蛰夜惊雷奋地，小窗朝爽日筛帘。","惠风全解墨池冻，清昼剩翻云笈签。","亲友莫嗔情话少，向来屏息似龟蟾。"]},{"t":"晚入盘门","f":"七言律诗","c":["人语嘲喧晚吹凉，万窗灯火转河塘。","两行碧柳笼官渡，一簇红楼压女墙。","何处采菱闻度曲，谁家拜月认飘香。","轻裘骏马慵穿市，困倚蒲团入睡乡。"]},{"t":"晚归石湖","f":"七言律诗","c":["何须驷马衒乡关，只作归农老圃看。","梦里曾腰綪结佩，年来新著惰游冠。","和烟种竹聊医俗，带月闻蛙不在官。","久矣此心恬不动，如今并与此身安。"]},{"t":"晚步东郊","f":"五言律诗","c":["水墨依林寺，青黄负郭田。","斜阳犹满地，片月早中天。","策策鸦飞急，冥冥树影圆。","西山元自好，那更著云烟。"]},{"t":"晚步北园","f":"七言律诗","c":["刮地晴飙退海痕，出门无扇可障尘。","麦枯瘠土何时雪，梅糁疏林昨夜春。","天镜风烟疑梦事，鬓霜时节尚官身。","裹章束带朝还暮，惭愧青鞋紫领巾。"]},{"t":"晚步吴故城下","f":"七言律诗","c":["意行殊不计榛菅，风袖飘然胜羽翰。","拄杖前头双雉起，浮图绝顶一并盘。","醉红匝地斜曛暖，熨练涵空涨水寒。","却向东皋望烟火，缺蟾先映槲林丹。"]},{"t":"晚步宣华旧苑","f":"七言律诗","c":["乔木如山废苑西，古沟疏水静鸣池。","吏兵窸窣番更后，楼阁崔嵬欲暝时。","有露冷萤犹照草，无风惊雀自迁枝。","归来更了程书债，目眚昏花烛穗垂。"]},{"t":"晚春二首 其二","f":"五言律诗","c":["好事怜春老，无愁耐日长。","炉烟惊扇影，酒面舞花光。","照水云容懒，移床竹意凉。","更烦红槿帽，促拍打山香。"]},{"t":"晚春二首 其一","f":"五言律诗","c":["静极闻檐佩，慵来爱枕帏。","隙虹飞永昼，帘影碎斜晖。","燕踏花枝语，蜂萦柳絮归。","轻飔宜白纻，时节近清微。"]},{"t":"晚登木渎小楼","f":"七言律诗","c":["万象当楼黼绣张，阑干一士立苍茫。","云堆不动山深碧，星出无多月淡黄。","宿鸟尽时犹数点，归鸿惊处更斜行。","松陵政有鲈鱼上，安得长竿坐钓航。"]},{"t":"晚集南楼","f":"七言律诗","c":["浪随儿女怨萍蓬，笑拍阑干万事空。","宇宙勋名无骨相，江山得句有神功。","掉头莫觑秋高鹗，留眼来宾日暮鸿。","懒拙已成三昧解，此生还證一圆通。"]},{"t":"晨出蒋山道中","f":"七言律诗","c":["霜痕如雨沁东郊，乐岁家家一把茅。","故国丘陵多麦垄，新晴篱落有梅梢。","小山何在应招隐，北岭如今已献嘲。","归计未成聊琢玉，飘飖风袖作推敲。"]},{"t":"望金陵行阙","f":"七言律诗","c":["圣代规模跨六朝，行宫台殿压金鳌。","三山落日青鸾近，双阙清风紫凤高。","石虎蹲江蟠王气，玉麟涌地镇神皋。","太平不用千寻锁，静听西城打夜涛。"]},{"t":"梅林先生夫人徐氏挽词二首 其二","f":"五言律诗","c":["昔簉鲤庭后，尝瞻林下风。","一从随地远，五度阅星终。","教载恩勤在，惊呼梦幻空。","送车知几两，独欠旧孤童。"]},{"t":"梅林先生夫人徐氏挽词二首 其一","f":"五言律诗","c":["择对鸣珂里，宜家驷马门。","肃雍成孝敬，燕喜助平反。","阅世弥三寿，还乡忽九原。","松风摇草露，愁绝后堂萱。"]},{"t":"梅根夹","f":"五言律诗","c":["辛苦凌波棹，平安入夹船。","日明渔浦网，风侧瓦窑烟。","老圃容挑菜，村巫横索钱。","且投人处宿，终夜得佳眠。"]},{"t":"检校石湖新田","f":"七言律诗","c":["今朝南野试开荒，分手耘锄草棘场。","下地若干全种秫，高原无几谩栽桑。","芦芽碧处重增岸，梅子黄时早浚塘。","田里只知温饱事，从今拚却半年忙。"]},{"t":"淳熙甲午桂林鹿鸣燕辄赋小诗少见劝驾之意","f":"七言律诗","c":["维南吾国最多儒，耸看招招赴陇书。","竹实秋风辞穴凤，桃花春浪脱渊鱼。","月宫移种新栽桂，江水朝宗旧凿渠。","况有状头坊井上，明年应表第三闾。"]},{"t":"清明日试新火作牡丹会","f":"七言律诗","c":["再钻巴火尚浮家，去国年多客路赊。","那得青烟穿御柳，且将银烛照京花。","香鬟半醉斜枝重，病眼全昏瘴雾遮。","锦地绣天春不散，任教檐雨捲泥沙。"]},{"t":"清明日狸渡道中","f":"五言律诗","c":["洒洒沾巾雨，披披侧帽风。","花燃山色里，柳卧水声中。","石马立当道，纸鸢鸣半空。","墦间人散后，乌鸟正西东。"]},{"t":"鄂州南楼","f":"七言律诗","c":["谁将玉笛弄中秋，黄鹤飞来识旧游。","汉树有情横北渚，蜀江无语抱南楼。","烛天灯火三更市，摇月旌旗万里舟。","却笑鲈乡垂钓手，武昌鱼好便淹留。"]},{"t":"阊门戏调行客","f":"七言律诗","c":["日夜飞帆与跨鞍，阊门川陆路漫漫。","人生自苦身馀几，天色无情岁又寒。","万事惟堪六如观，一杯莫信四并难。","重阳虽过黄花少，尚有迟开玉雪团。"]},{"t":"雪寒围炉小集","f":"七言律诗","c":["席帘纸阁护香浓，说有谈空爱烛红。","高饤膻根浇杏酪，旋融雪汁煮松风。","康年气象冬三白，浮世功名酒一中。","无事闭门渠易得，何人蹑屐响墙东。"]},{"t":"雪意方浓复作雨","f":"五言律诗","c":["拟看飞花阵，翻成建水声。","雨吾宁不识，雪汝几时成。","三白从今卜，千仓待此盈。","黄云如有意，青女莫无情。"]},{"t":"雪霁独登南楼","f":"七言律诗","c":["雪晴风劲晚来冰，楼上奇寒病骨惊。","雀啄空檐银笋堕，鸦翻高树玉尘倾。","青帘闪闪千家静，黄帽亭亭一水横。","坐久天容却温丽，一弯新月对长庚。"]},{"t":"鹿鸣宴","f":"七言律诗","c":["岷峨钟秀蜀多珍，坐上儒先更逸群。","墨沼不忧经覆瓿，琴台重有赋凌云。","文章小技聊干禄，道学初心拟致君。","富贵功名今发轫，愿看稽古策高勋。"]},{"t":"鹿鸣席上赠贡士","f":"七言律诗","c":["登陆由来说四明，台星光处更魁星。","海滨二老尊周室，馆下诸生右汉廷。","秋赋重增人物志，春闱俱上佛名经。","一飞好趁扶摇便，咫尺西兴是北溟。"]},{"t":"喜沈叔晦至","f":"五言律诗","c":["澹若论交味，嘤其求友声。","江湖几鱼沫，风雨一鸡鸣。","旧事休重说，新诗莫细评。","烦将忆勤梦，归对海山横。"]},{"t":"奠唐少梁晋仲兄弟墓下","f":"七言律诗","c":["当年连璧气如蜺，人许跻攀九列齐。","黄壤一时埋玉树，青云何处用丹梯。","生平书札频双鲤，岁晚交情但只鸡。","眼底伤心难制泪，宁论宿草已萋萋。"]},{"t":"寒夜观雪","f":"五言律诗","c":["静极孤鸿响，寒疑万籁喑。","眼花灯下字，髭断雪中吟。","颇似偿前债，非关惜寸阴。","可怜蝴蝶梦，翩作蠹书蟫。"]},{"t":"寒食郊行书事二首 其二","f":"五言律诗","c":["陇麦欣欣绿，山桃寂寂红。","帆边渔蕝浪，木末酒旗风。","信步随芳草，迷途问小童。","赏心添脚力，呼渡过溪东。"]},{"t":"寒食郊行书事二首 其一","f":"五言律诗","c":["野店垂杨步，荒祠苦竹丛。","鹭窥芦箔水，乌啄纸钱风。","媪引浓妆女，儿扶烂醉翁。","深村时节好，应为去年丰。"]},{"t":"寒食客中有怀","f":"七言律诗","c":["江郭花开也寂寥，不须绿暗与红凋。","疾风甚雨过寒食，白日青春吟大招。","芳景尚随流水去，故人应作綵云飘。","烟波千里家何在，惟有溪声似晚潮。"]},{"t":"寓直玉堂拜赐御酒","f":"七言律诗","c":["归鸦陆续堕宫槐，帘幕参差晚不开。","小雨遂将秋色至，长风时送市声来。","近瞻北斗璿玑次，犹梦西山翠碧堆。","惭愧君恩来甲夜，殿头宣劝紫金杯。"]},{"t":"渡太湖","f":"七言律诗","c":["囊风阁雨半晴阴，惨淡谁知造化心。","委命浮沉惟一叶，计身轻重亦千金。","红尘犹道不胜险，白浪莫嗔如许深。","晚得芗山堪寄缆，卧听鼍吼与龙吟。"]},{"t":"湘江洲尾快风挂帆","f":"七言律诗","c":["船头雪浪吼奔雷，十丈高帆满意开。","我自只凭忠信力，风应不为世情来。","儿童屡惜峰峦过，将士犹教鼓笛催。","明日祝融天柱去，更烦先捲乱云堆。"]},{"t":"湘阴桥口市别游子明","f":"七言律诗","c":["马首欲东舟欲西，洞庭桥口暮寒时。","三年再别子轻去，万里独行吾蚤衰。","遥忆美人湘水梦，侧身西望剑门诗。","老来不洒离亭泪，今日天涯老泪垂。"]},{"t":"犍为江楼","f":"七言律诗","c":["河边堵立看归篷，三老开头暮欲东。","涨水稠滩连峡内，浅山浮石似湘中。","无人驿路榛榛草，有客江楼浩浩风。","种落尘消少公事，剩裁新语寄诗筒。"]},{"t":"登西楼","f":"七言律诗","c":["少年豪气合摧锋，青鬓朱颜万事慵。","畴昔四愁无梦到，及时一笑有谁供。","诗情饮兴如云薄，草色花光似酒醲。","千里春心吟不尽，下楼分付晚烟钟。"]},{"t":"蛮触","f":"七言律诗","c":["蛮触纷拿室未虚，心知惩忿欠工夫。","腹须空洞方容物，事过清凉已丧吾。","万仞我山高不极，一团心火蔓难图。","从今立示寒灰观，笑看苍黄走郑巫。"]},{"t":"谢江东漕杨廷秀秘监送江东集并索近诗二首 其二","f":"七言律诗","c":["秃翁衰雪涕垂颐，仿佛三生懒散师。","浃髓沦肤都是病，倾囷倒廪更无诗。","笑看笔格网丝遍，閒数窗棂花影移。","事业光阴今若此，故人休说旧襟期。"]},{"t":"谢江东漕杨廷秀秘监送江东集并索近诗二首 其一","f":"七言律诗","c":["远道悠悠日暮云，愁眉今日为君轩。","残灯独照江东集，短梦相寻白下门。","即事想多梅蕊句，有谁堪共桂花樽。","斯文赖有斯人在，会合何时得细论。"]},{"t":"谢范老问病","f":"七言律诗","c":["三椽一席度秋冬，造化儿嬉困此翁。","帖有王书难治眩，文如陈檄不驱风。","骨枯似蘖肤如腊，发织成毡鬓作蓬。","点检病身还一笑，本来四大满虚空。"]},{"t":"谢赐腊药感遇之什","f":"七言律诗","c":["鸿宝刀圭下九关，十年长奉玺封看。","扶持蒲柳身犹健，收拾桑榆岁又寒。","天地恩深双鬓雪，山川途远一心丹。","疲氓疾苦今何似，拜手归来愧伐檀。"]},{"t":"赏心亭再题","f":"五言律诗","c":["天险东南重，兵雄百二尊。","拂云千雉绕，截水万崖奔。","赤日吴波动，苍烟楚树昏。","向无形胜地，何以控乾坤。"]},{"t":"道子教授奉祠诸生率余祖席如意院","f":"七言律诗","c":["暂移三席款云关，木末阑干暮紫间。","绛帐莫贪江上路，青鞋先试水西山。","伯阳有道来重趼，禦寇他年忆解颜。","怪我抗尘驱俗驾，诸公何事许追攀。"]},{"t":"道中","f":"五言律诗","c":["月冷吟蛩草，湖平宿鹭沙。","客愁无锦字，乡信有灯花。","踪迹随风叶，程途犯斗槎。","君看枝上鹊，薄暮亦还家。"]},{"t":"鲁如晦郎中挽词二首 其一","f":"五言律诗","c":["术业推游刃，功名苦溯洄。","著鞭孤壮志，筹算老奇才。","星省庞眉去，云山袖手来。","知公了时命，何必诔馀哀。"]},{"t":"鲁如晦郎中挽词二首 其二","f":"五言律诗","c":["自古归来引，于今遂隐篇。","棋灯荧夜观，歌板聒春船。","陈迹空华似，佳城露草边。","寂寥鸡黍约，望眼一潸然。"]},{"t":"鲁家洑入沌","f":"七言律诗","c":["过尽巴东巫峡长，荆川鼓棹更茫茫。","避风怕入三江口，乘月贪行百里荒。","夜后逢人尽刀剑，古来踏地皆耕桑。","可怜行路难如此，一簇寒芦尚税场。"]},{"t":"鼎河口枕上作","f":"五言律诗","c":["漂泊离巢燕，弯跧负壳蜗。","瘦嫌莞席硬，老觉画屏奢。","报道帆当落，传呼鼓已挝。","且投人处宿，未到已闻蟆。"]},{"t":"携家石湖赏拒霜","f":"七言律诗","c":["水上晴云綵蝀横，许多蜂蝶趁船行。","渔樵引入新花坞，儿女扶登小锦城。","艳粉发妆朝日丽，湿红浮影晚波清。","谁知摇落霜林畔，一段韶光画不成。"]},{"t":"新安侯夫人俞氏挽词","f":"五言律诗","c":["蚤兆于凰卜，来嫔驷马车。","夫君宜竹帛，子舍各诗书。","露薤丹旌举，风杨组帐虚。","空馀彤管训，他日照乡闾。"]},{"t":"新岁书怀","f":"五言律诗","c":["门阒知閒好，窗晴与睡宜。","岁华书户笔，年例探梅诗。","看长棋三著，量添饭两匙。","豁除身外事，未是苦衰迟。"]},{"t":"新作官梅庄移植大梅数十本绕之","f":"七言律诗","c":["腊前催唤主林神，玉树飞来不动尘。","契阔西湖惭处士，飘零东阁似诗人。","一天午梦空花碎，满地春愁月影新。","扫净宣华藜藋径，他年谁记石湖滨。"]},{"t":"新作锦亭程咏之提刑赋诗次其韵二首 其二","f":"七言律诗","c":["小筑聊锄草棘荒，游人错比召南棠。","花边雾鬓风鬟满，酒畔云衣月扇香。","灿烂吟笺烦索句，淋漓醉墨自成行。","报章迟钝吾衰矣，终日冥搜谩七襄。"]},{"t":"新作锦亭程咏之提刑赋诗次其韵二首 其一","f":"七言律诗","c":["飞鸿衔子谩纷纷，万里西游始识真。","不管吴霜微点鬓，来看蜀锦烂争春。","倚阑定有司花女，秉烛仍留主夜神。","异县赏心谁与共，故人新作坐中宾。"]},{"t":"亲邻招集强往便归","f":"七言律诗","c":["乐天渐老欲谋欢，大似蒸砂不作团。","已觉笙歌无煖热，仍嫌风月太清寒。","气衰况复三而竭，心赏尤于四者难。","却恐人嫌情太薄，聊将花作雾中看。"]},{"t":"新津道中","f":"五言律诗","c":["雨后郊原净，村村各好音。","宿云浮竹色，清溜走桤阴。","曲沼擎青盖，新畦艺绿针。","江天空阔处，不受暑光侵。"]},{"t":"新凉夜坐","f":"七言律诗","c":["吏退焚香百虑空，静闻虫响度帘栊。","江头一尺稻花雨，窗外三更蕉叶风。","日日老添明镜里，家家凉入短檠中。","简编灯火平生事，雪白眵昏奈此翁。"]}]};